  "publicMetadataFingerprint" text,
  record jsonb,
  "renderPayload" jsonb
);

do $$
begin
  if public.site_content_bootstrap_digest('e4a1dd29-14f6-556c-8fb7-f4f947d8b846') is distinct from '57f6ec90225fc4341b446705f50a48b132f2872172d8f93888bf921fe7bfa1bc'
    or (select count(*) from public.site_content_release_records where release_id = 'e4a1dd29-14f6-556c-8fb7-f4f947d8b846') <> 843
  then raise exception using errcode = '23514', message = 'site_content_bootstrap_population_mismatch'; end if;
end;
