commit;
-- Correct governed candidate admission without changing the v3 wrapper surface.

begin;

create or replace function public.match_governed_candidate_chunks_v3(
  query_embedding extensions.vector(1536),
  query_text text,
  match_count integer,
  min_similarity double precision,
  document_filters uuid[],
  owner_filter uuid,
  include_public boolean,
  corpus_scopes text[],
  expected_site_release_id uuid,
  expected_site_release_digest text,
  expected_site_change_epoch bigint,
  site_content_domains text[]
)
returns table (
  id uuid,
  document_id uuid,
  title text,
  file_name text,
  page_number integer,
  chunk_index integer,
  section_heading text,
  content text,
  retrieval_synopsis text,
  image_ids uuid[],
  source_metadata jsonb,
  document_labels jsonb,
  document_summary text,
  similarity double precision,
  text_rank double precision,
  hybrid_score double precision,
  rrf_score double precision,
  lexical_score double precision,
  images jsonb,
  corpus_scope text,
  site_content_domain text,
  site_release_id uuid,
  site_change_epoch bigint,
  pending_exclusion_exact boolean
)
language sql
stable
security definer
set search_path = ''
set work_mem = '64MB'
as $$
  with
  admitted as (
    select
      least(greatest(coalesce(match_count, 12), 1), 96) as bounded_count,
      case
        when query_text is null or pg_catalog.btrim(query_text) = '' then null
        else pg_catalog.websearch_to_tsquery('english', query_text)
      end as tsq
    where include_public is true
      and owner_filter = '00000000-0000-0000-0000-000000000000'::uuid
      and corpus_scopes is not null
      and pg_catalog.cardinality(corpus_scopes) between 1 and 4
      and corpus_scopes <@ array[
        'uploaded_local',
        'clinical_kb_site',
        'australian_public',
        'international_supplementary'
      ]::text[]
  ),
  site_authority as (
    select
      state.active_release_id as release_id,
      state.change_epoch,
      state.served_change_epoch,
      release.release_digest
    from public.site_content_sync_state state
    join public.site_content_releases release
      on release.id = state.active_release_id
     and release.state = 'active'
     and release.target_change_epoch = state.served_change_epoch
     and release.release_digest = state.active_release_digest
    cross join admitted
    where expected_site_release_id is not null
      and expected_site_release_digest ~ '^[0-9a-f]{64}$'
      and expected_site_change_epoch is not null
      and state.initialized
      and state.active_release_id = expected_site_release_id
      and state.active_release_digest = expected_site_release_digest
      and state.change_epoch = expected_site_change_epoch
      and state.served_change_epoch <= state.change_epoch
  ),
  pending_site_set as (
    select not exists (
      select 1
      from public.site_content_public_records record
      left join public.site_content_sync_events event
        on event.event_sequence = record.pending_event_sequence
      where record.pending_event_sequence is not null
        and (
          event.event_sequence is null
          or event.logical_id is distinct from record.logical_id
          or event.target_publication_id is distinct from record.current_publication_id
          or event.target_change_epoch is distinct from record.head_change_epoch
          or event.target_change_epoch > site_authority.change_epoch
        )
    ) and not exists (
      select 1
      from public.site_content_public_records record
      where record.head_change_epoch > site_authority.served_change_epoch
        and (
          record.pending_event_sequence is null
          or record.head_change_epoch > site_authority.change_epoch
        )
    ) as exact
    from site_authority
  ),
  pending_site_logical_ids as (
    select record.logical_id
    from public.site_content_public_records record
    cross join site_authority
    where record.pending_event_sequence is not null
  ),
  document_candidates as (
    select
      chunk.id,
      document.id as document_id,
      document.title,
      document.file_name,
      chunk.page_number,
      chunk.chunk_index,
      chunk.section_heading,
      chunk.content,
      chunk.retrieval_synopsis,
      chunk.image_ids,
      pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
        'source_kind', 'document',
        'source_title', document.metadata->>'source_title',
        'publisher', document.metadata->>'publisher',
        'publisher_code', document.metadata->>'publisher_code',
        'jurisdiction', document.metadata->>'jurisdiction',
        'version', document.metadata->>'version',
        'publication_date', document.metadata->>'publication_date',
        'review_date', document.metadata->>'review_date',
        'uploaded_at', document.metadata->>'uploaded_at',
        'indexed_at', document.metadata->>'indexed_at',
        'corpus_scope', document.metadata->>'corpus_scope',
        'source_role', document.metadata->>'source_role',
        'content_mode', document.metadata->>'content_mode',
        'source_catalogue_key', document.metadata->>'source_catalogue_key',
        'source_policy_version', document.metadata->>'source_policy_version',
        'canonical_url', document.metadata->>'canonical_url',
        'effective_date', document.metadata->>'effective_date',
        'expiry_date', document.metadata->>'expiry_date',
        'supersedes_document_id', document.metadata->>'supersedes_document_id',
        'superseded_by_document_id', document.metadata->>'superseded_by_document_id',
        'retrieved_at', document.metadata->>'retrieved_at',
        'content_hash', document.metadata->>'content_hash',
        'change_state', document.metadata->>'change_state',
        'licence_policy', document.metadata->>'licence_policy',
        'document_status', document.metadata->>'document_status',
        'clinical_validation_status', document.metadata->>'clinical_validation_status',
        'extraction_quality', document.metadata->>'extraction_quality'
      )) as source_metadata,
      coalesce(
        (
          select pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object('id', label.id, 'label', label.label, 'label_type', label.label_type)
            order by label.label_type, label.label, label.id
          )
          from public.document_labels label
          where label.document_id = document.id
        ),
        '[]'::jsonb
      ) as document_labels,
      (
        select summary.summary
        from public.document_summaries summary
        where summary.document_id = document.id
        order by summary.created_at desc, summary.id
        limit 1
      ) as document_summary,
      case
        when query_embedding is null then 0::double precision
        else (1 - (chunk.embedding OPERATOR(extensions.<=>) query_embedding))::double precision
      end as similarity,
      case
        when admitted.tsq is null then 0::double precision
        else pg_catalog.ts_rank_cd(chunk.search_tsv, admitted.tsq)::double precision
      end as text_rank,
      coalesce(
        (
          select pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
              'id', image.id,
              'page_number', image.page_number,
              'storage_path', image.storage_path,
              'caption', image.caption
            )
            order by image.id
          )
          from public.document_images image
          where image.id = any(chunk.image_ids)
        ),
        '[]'::jsonb
      ) as images,
      document.metadata->>'corpus_scope' as corpus_scope,
      (
        admitted.tsq is not null
        and (chunk.search_tsv @@ admitted.tsq or document.title_search_tsv @@ admitted.tsq)
      ) as text_matched
    from public.document_chunks chunk
    join public.documents document on document.id = chunk.document_id
    cross join admitted
    where document.owner_id is null
      and document.status = 'indexed'
      and public.is_committed_document_generation(chunk.index_generation_id, document.index_generation_id)
      and (document_filters is null or document.id = any(document_filters))
      and document.metadata->>'corpus_scope' = any(corpus_scopes)
      and document.metadata->>'corpus_scope' = 'australian_public'
      and document.metadata->>'source_kind' = 'document'
      and document.metadata->'public_corpus' = 'true'::jsonb
      and document.metadata->>'content_mode' = 'indexed_content'
      and document.metadata->>'document_status' = 'current'
      and coalesce(document.metadata->>'change_state', '') in ('changed', 'unchanged')
      and document.metadata->>'licence_policy' = 'public_index_permitted'
      and nullif(document.metadata->>'source_catalogue_key', '') is not null
      and nullif(document.metadata->>'source_policy_version', '') is not null
      and nullif(document.metadata->>'publication_approval_id', '') is not null
      and nullif(document.metadata->>'publication_manifest_digest', '') is not null
  ),
  site_candidates as (
    select
      record.logical_chunk_id as id,
      record.logical_document_id as document_id,
      record.record->>'title' as title,
      record.record->>'route' as file_name,
      null::integer as page_number,
      0::integer as chunk_index,
      record.record->>'domain' as section_heading,
      record.normalized_text as content,
      null::text as retrieval_synopsis,
      '{}'::uuid[] as image_ids,
      pg_catalog.jsonb_build_object(
        'corpus_scope', 'clinical_kb_site',
        'source_kind', 'registry_record',
        'source_role', record.record->>'sourceRole',
        'content_mode', 'indexed_content',
        'source_title', record.record->>'title',
        'version', record.record->>'publicationVersion',
        'document_status', record.record->>'sourceStatus',
        'clinical_validation_status', record.record->>'validationStatus',
        'extraction_quality', 'good',
        'content_hash', record.record->>'contentHash',
        'site_content_lineage', record.record->'sourceLineage'
      ) as source_metadata,
      '[]'::jsonb as document_labels,
      null::text as document_summary,
      case
        when query_embedding is null or record.embedding is null then 0::double precision
        else (1 - (record.embedding OPERATOR(extensions.<=>) query_embedding))::double precision
      end as similarity,
      case
        when admitted.tsq is null then 0::double precision
        else pg_catalog.ts_rank_cd(
          pg_catalog.to_tsvector(
            'english',
            coalesce(record.record->>'title', '') || ' ' || record.normalized_text
          ),
          admitted.tsq
        )::double precision
      end as text_rank,
      '[]'::jsonb as images,
      'clinical_kb_site'::text as corpus_scope,
      (
        admitted.tsq is not null
        and pg_catalog.to_tsvector(
          'english',
          coalesce(record.record->>'title', '') || ' ' || record.normalized_text
        ) @@ admitted.tsq
      ) as text_matched,
      record.record->>'domain' as site_content_domain,
      site_authority.release_id as site_release_id,
      site_authority.change_epoch as site_change_epoch
    from public.site_content_release_records record
    cross join admitted
    cross join site_authority
    cross join pending_site_set
    where 'clinical_kb_site' = any(corpus_scopes)
      and record.release_id = site_authority.release_id
      and pending_site_set.exact
      and (document_filters is null or record.logical_document_id = any(document_filters))
      and record.public_visible
      and not record.tombstone
      and pg_catalog.jsonb_typeof(record.record) = 'object'
      and record.record->>'version' = 'site-content-record-v1'
      and record.record->>'access' = 'public'
      and record.record->>'logicalId' = record.logical_id
      and record.record->>'validationStatus' in ('locally_reviewed', 'approved')
      and record.record->>'sourceStatus' in ('current', 'review_due')
      and record.record->>'domain' in (
        'services', 'forms', 'medications', 'differentials', 'specifiers', 'dsm',
        'formulation', 'therapies', 'dictionary', 'factsheets', 'calculators', 'tools'
      )
      and (
        site_content_domains is null
        or (
          pg_catalog.cardinality(site_content_domains) between 1 and 12
          and site_content_domains <@ array[
            'services', 'forms', 'medications', 'differentials', 'specifiers', 'dsm',
            'formulation', 'therapies', 'dictionary', 'factsheets', 'calculators', 'tools'
          ]::text[]
          and record.record->>'domain' = any(site_content_domains)
        )
      )
      and not exists (
        select 1
        from pending_site_logical_ids pending
        where pending.logical_id = record.logical_id
      )
  ),
  combined as (
    select
      document.*,
      null::text as site_content_domain,
      null::uuid as site_release_id,
      null::bigint as site_change_epoch
    from document_candidates document
    union all
    select * from site_candidates
  ),
  vector_ranked as (
    select
      combined.id,
      combined.corpus_scope,
      row_number() over (order by combined.similarity desc, combined.id) as vector_rank,
      null::bigint as text_match_rank
    from combined
    where query_embedding is not null
      and combined.similarity >= greatest(coalesce(min_similarity, 0.12), 0)
    order by combined.similarity desc, combined.id
    limit (select greatest(bounded_count * 6, 48) from admitted)
  ),
  text_ranked as (
    select
      combined.id,
      combined.corpus_scope,
      null::bigint as vector_rank,
      row_number() over (order by combined.text_rank desc, combined.id) as text_match_rank
    from combined
    where combined.text_matched
    order by combined.text_rank desc, combined.id
    limit (select greatest(bounded_count * 6, 48) from admitted)
  ),
  rank_positions as (
    select
      positions.id,
      positions.corpus_scope,
      min(positions.vector_rank) as vector_rank,
      min(positions.text_match_rank) as text_match_rank
    from (
      select * from vector_ranked
      union all
      select * from text_ranked
    ) positions
    group by positions.id, positions.corpus_scope
  ),
  ranked as (
    select
      combined.*,
      ((combined.similarity * 0.65) + (least(combined.text_rank, 1) * 0.35))::double precision as hybrid_score,
      (
        coalesce(1.0 / (60 + rank_positions.vector_rank), 0)
        + coalesce(1.0 / (60 + rank_positions.text_match_rank), 0)
      )::double precision as rrf_score
    from combined
    join rank_positions using (id, corpus_scope)
  )
  select
    ranked.id,
    ranked.document_id,
    ranked.title,
    ranked.file_name,
    ranked.page_number,
    ranked.chunk_index,
    ranked.section_heading,
    ranked.content,
    ranked.retrieval_synopsis,
    ranked.image_ids,
    ranked.source_metadata,
    ranked.document_labels,
    ranked.document_summary,
    ranked.similarity,
    ranked.text_rank,
    ranked.hybrid_score,
    ranked.rrf_score,
    least(ranked.text_rank, 1)::double precision as lexical_score,
    ranked.images,
    ranked.corpus_scope,
    ranked.site_content_domain,
    ranked.site_release_id,
    ranked.site_change_epoch,
    true as pending_exclusion_exact
  from ranked
  order by ranked.hybrid_score desc, ranked.rrf_score desc, ranked.id
  limit (select bounded_count from admitted);
$$;

revoke all on function public.match_governed_candidate_chunks_v3(
  extensions.vector, text, integer, double precision, uuid[], uuid, boolean, text[], uuid, text, bigint, text[]
) from public, anon, authenticated, service_role;

alter function public.match_governed_candidate_chunks_v3(
  extensions.vector, text, integer, double precision, uuid[], uuid, boolean, text[], uuid, text, bigint, text[]
) owner to postgres;

commit;
-- Reversible corpus-wide document visibility control. The access state and
-- snapshot are backend-readable only; mutations are serialized through the
-- service-role function so prior document owner/public marker state is
-- restored when possible and deleted-owner rows fail closed as non-public and
-- non-retrievable.
create table if not exists public.document_corpus_access_state (
  singleton boolean primary key default true check (singleton),
  mode text not null check (mode in ('private', 'public')),
  activation_id uuid,
  activated_at timestamptz,
  updated_at timestamptz not null default now(),
  check ((mode = 'public') = (activation_id is not null))
);

create table if not exists public.document_corpus_access_snapshots (
  activation_id uuid not null,
  document_id uuid not null references public.documents(id) on delete cascade,
  owner_id uuid,
  public_corpus_present boolean not null,
  public_corpus_value jsonb,
  published_label_ids uuid[] not null default '{}',
  published_summary_ids uuid[] not null default '{}',
  published_table_fact_ids uuid[] not null default '{}',
  captured_at timestamptz not null default now(),
  primary key (activation_id, document_id),
  check (public_corpus_present or public_corpus_value is null)
);

create index if not exists document_corpus_access_snapshots_document_id_idx
  on public.document_corpus_access_snapshots (document_id);

alter table public.document_corpus_access_state enable row level security;
alter table public.document_corpus_access_snapshots enable row level security;

revoke all on table public.document_corpus_access_state
  from public, anon, authenticated, service_role;
revoke all on table public.document_corpus_access_snapshots
  from public, anon, authenticated, service_role;
grant select on table public.document_corpus_access_state to service_role;
grant select on table public.document_corpus_access_snapshots to service_role;

insert into public.document_corpus_access_state (singleton, mode)
values (true, 'private')
on conflict (singleton) do nothing;

create or replace function public.set_document_corpus_access_mode(p_mode text)
returns jsonb
language plpgsql
security definer
set search_path = ''
set lock_timeout = '15s'
as $$
declare
  v_max_child_rows constant integer := 200000;
  v_state public.document_corpus_access_state%rowtype;
  v_activation_id uuid;
  v_snapshot_count integer;
  v_document_count integer;
  v_public_count integer;
  v_child_row_probe integer;
  v_child_rows integer := 0;
  v_updated integer;
begin
  if p_mode not in ('private', 'public') then
    raise exception 'document corpus access mode must be private or public'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('document-corpus-access-mode', 0));

  select *
  into v_state
  from public.document_corpus_access_state
  where singleton
  for update;

  if not found then
    raise exception 'document corpus access state is missing';
  end if;

  if not exists (
    select 1
    from pg_catalog.pg_trigger
    where tgrelid = 'public.documents'::regclass
      and tgname = 'documents_require_publication_approval'
      and not tgisinternal
  ) then
    raise exception 'documents publication guard trigger is missing';
  end if;

  if p_mode = 'public' then
    v_activation_id := case
      when v_state.mode = 'public' then v_state.activation_id
      else extensions.gen_random_uuid()
    end;

    insert into public.document_corpus_access_snapshots (
      activation_id,
      document_id,
      owner_id,
      public_corpus_present,
      public_corpus_value
    )
    select
      v_activation_id,
      d.id,
      d.owner_id,
      coalesce(d.metadata, '{}'::jsonb) ? 'public_corpus',
      coalesce(d.metadata, '{}'::jsonb)->'public_corpus'
    from public.documents d
    on conflict (activation_id, document_id) do nothing;

    -- Bound the added work before doing any of it: the probe stops at the
    -- ceiling and the switch refuses the whole flip rather than turning an
    -- operational call into an unbounded rewrite.
    select count(*)::integer
    into v_child_row_probe
    from (
      select 1
      from public.document_corpus_access_snapshots snapshot
      join public.document_labels l
        on l.document_id = snapshot.document_id and l.owner_id = snapshot.owner_id
      where snapshot.activation_id = v_activation_id
      union all
      select 1
      from public.document_corpus_access_snapshots snapshot
      join public.document_summaries s
        on s.document_id = snapshot.document_id and s.owner_id = snapshot.owner_id
      where snapshot.activation_id = v_activation_id
      union all
      select 1
      from public.document_corpus_access_snapshots snapshot
      join public.document_table_facts f
        on f.document_id = snapshot.document_id and f.owner_id = snapshot.owner_id
      where snapshot.activation_id = v_activation_id
      limit v_max_child_rows + 1
    ) bounded_probe;

    if v_child_row_probe > v_max_child_rows then
      raise exception
        'document corpus access switch would rewrite more than % retrieval-scoped derived owner rows in one synchronous call; publish in batches through public.publish_approved_documents instead',
        v_max_child_rows
        using errcode = '54000';
    end if;

    -- ALTER TABLE takes an ACCESS EXCLUSIVE lock. The trigger bypass is
    -- therefore invisible to concurrent sessions and rolls back on failure.
    execute 'alter table public.documents disable trigger documents_require_publication_approval';
    update public.documents d
    set
      owner_id = null,
      metadata = pg_catalog.jsonb_set(coalesce(d.metadata, '{}'::jsonb), '{public_corpus}', 'true'::jsonb, true),
      updated_at = now()
    where exists (
      select 1 from public.document_corpus_access_snapshots snapshot
      where snapshot.activation_id = v_activation_id and snapshot.document_id = d.id
    )
      and (
        d.owner_id is not null
        or coalesce(d.metadata, '{}'::jsonb)->'public_corpus' is distinct from 'true'::jsonb
      );
    execute 'alter table public.documents enable trigger documents_require_publication_approval';

    -- The three derived tables whose own owner_id reaches a retrieval owner
    -- predicate. Bounded to rows that still carry the snapshotted document
    -- owner, so the private branch restores exactly this set.
    with published as (
      update public.document_labels l
      set owner_id = null, updated_at = now()
      from public.document_corpus_access_snapshots snapshot
      where snapshot.activation_id = v_activation_id
        and snapshot.document_id = l.document_id
        and l.owner_id = snapshot.owner_id
      returning l.id, l.document_id
    ), recorded as (
      update public.document_corpus_access_snapshots snapshot
      set published_label_ids = snapshot.published_label_ids || changed.ids
      from (select document_id, array_agg(id) as ids from published group by document_id) changed
      where snapshot.activation_id = v_activation_id
        and snapshot.document_id = changed.document_id
      returning snapshot.document_id
    )
    select count(*)::integer into v_updated from published;
    v_child_rows := v_child_rows + v_updated;

    with published as (
      update public.document_summaries s
      set owner_id = null, updated_at = now()
      from public.document_corpus_access_snapshots snapshot
      where snapshot.activation_id = v_activation_id
        and snapshot.document_id = s.document_id
        and s.owner_id = snapshot.owner_id
      returning s.id, s.document_id
    ), recorded as (
      update public.document_corpus_access_snapshots snapshot
      set published_summary_ids = snapshot.published_summary_ids || changed.ids
      from (select document_id, array_agg(id) as ids from published group by document_id) changed
      where snapshot.activation_id = v_activation_id
        and snapshot.document_id = changed.document_id
      returning snapshot.document_id
    )
    select count(*)::integer into v_updated from published;
    v_child_rows := v_child_rows + v_updated;

    with published as (
      update public.document_table_facts f
      set owner_id = null
      from public.document_corpus_access_snapshots snapshot
      where snapshot.activation_id = v_activation_id
        and snapshot.document_id = f.document_id
        and f.owner_id = snapshot.owner_id
      returning f.id, f.document_id
    ), recorded as (
      update public.document_corpus_access_snapshots snapshot
      set published_table_fact_ids = snapshot.published_table_fact_ids || changed.ids
      from (select document_id, array_agg(id) as ids from published group by document_id) changed
      where snapshot.activation_id = v_activation_id
        and snapshot.document_id = changed.document_id
      returning snapshot.document_id
    )
    select count(*)::integer into v_updated from published;
    v_child_rows := v_child_rows + v_updated;

    if v_child_rows > v_max_child_rows then
      raise exception
        'document corpus access switch rewrote % retrieval-scoped derived owner rows, above the % row synchronous bound; the flip is rolled back',
        v_child_rows, v_max_child_rows
        using errcode = '54000';
    end if;

    update public.document_corpus_access_state
    set
      mode = 'public',
      activation_id = v_activation_id,
      activated_at = coalesce(activated_at, now()),
      updated_at = now()
    where singleton;
  else
    if v_state.mode = 'private' then
      select count(*)::integer into v_document_count from public.documents;
      return pg_catalog.jsonb_build_object(
        'mode', 'private',
        'changed', false,
        'document_count', v_document_count
      );
    end if;

    v_activation_id := v_state.activation_id;

    -- The restore carries the same ceiling as the publish it reverses.
    select count(*)::integer
    into v_child_row_probe
    from (
      select 1
      from public.document_corpus_access_snapshots snapshot
      join auth.users existing_owner on existing_owner.id = snapshot.owner_id
      join public.document_labels l
        on l.document_id = snapshot.document_id and l.owner_id is null
          and l.id = any(snapshot.published_label_ids)
      where snapshot.activation_id = v_activation_id
      union all
      select 1
      from public.document_corpus_access_snapshots snapshot
      join auth.users existing_owner on existing_owner.id = snapshot.owner_id
      join public.document_summaries s
        on s.document_id = snapshot.document_id and s.owner_id is null
          and s.id = any(snapshot.published_summary_ids)
      where snapshot.activation_id = v_activation_id
      union all
      select 1
      from public.document_corpus_access_snapshots snapshot
      join auth.users existing_owner on existing_owner.id = snapshot.owner_id
      join public.document_table_facts f
        on f.document_id = snapshot.document_id and f.owner_id is null
          and f.id = any(snapshot.published_table_fact_ids)
      where snapshot.activation_id = v_activation_id
      limit v_max_child_rows + 1
    ) bounded_probe;

    if v_child_row_probe > v_max_child_rows then
      raise exception
        'document corpus access switch would rewrite more than % retrieval-scoped derived owner rows in one synchronous call; publish in batches through public.publish_approved_documents instead',
        v_max_child_rows
        using errcode = '54000';
    end if;

    execute 'alter table public.documents disable trigger documents_require_publication_approval';
    update public.documents d
    set
      owner_id = existing_owner.id,
      -- Quarantine whenever the row LANDS ownerless without a true publication marker,
      -- not only when its owner was deleted (#ZBAC9D, 20260902110200). The original
      -- condition missed the row that was ALREADY ownerless and unmarked when public mode
      -- was activated -- the population 20260825025032's header describes -- and restoring
      -- such a row as ownerless-unmarked-indexed is what
      -- documents_ownerless_requires_publication_marker forbids, so the whole
      -- return-to-private call would abort.
      status = case
        when existing_owner.id is null
          and not (
            snapshot.owner_id is null
            and snapshot.public_corpus_present
            and snapshot.public_corpus_value = 'true'::jsonb
          )
        then 'failed'
        else d.status
      end,
      metadata = case
        -- Restoring a public marker without its former owner would turn an
        -- owner-scoped row into a public row. Remove the marker instead.
        when snapshot.owner_id is not null and existing_owner.id is null then
          coalesce(d.metadata, '{}'::jsonb) - 'public_corpus'
        when snapshot.public_corpus_present then
          pg_catalog.jsonb_set(
            coalesce(d.metadata, '{}'::jsonb),
            '{public_corpus}',
            snapshot.public_corpus_value,
            true
          )
        else coalesce(d.metadata, '{}'::jsonb) - 'public_corpus'
      end,
      updated_at = now()
    from public.document_corpus_access_snapshots snapshot
    left join auth.users existing_owner on existing_owner.id = snapshot.owner_id
    where snapshot.activation_id = v_activation_id and snapshot.document_id = d.id;
    execute 'alter table public.documents enable trigger documents_require_publication_approval';

    -- Restore the derived owners this activation published. The inner join to
    -- auth.users keeps a deleted owner unrestorable rather than reattaching a
    -- stale uuid that the owner foreign key would reject anyway; those rows
    -- stay ownerless beside their quarantined document.
    update public.document_labels l
    set owner_id = existing_owner.id, updated_at = now()
    from public.document_corpus_access_snapshots snapshot
    join auth.users existing_owner on existing_owner.id = snapshot.owner_id
    where snapshot.activation_id = v_activation_id
      and snapshot.document_id = l.document_id
      and l.owner_id is null
      and l.id = any(snapshot.published_label_ids);
    get diagnostics v_updated = row_count;
    v_child_rows := v_child_rows + v_updated;

    update public.document_summaries s
    set owner_id = existing_owner.id, updated_at = now()
    from public.document_corpus_access_snapshots snapshot
    join auth.users existing_owner on existing_owner.id = snapshot.owner_id
    where snapshot.activation_id = v_activation_id
      and snapshot.document_id = s.document_id
      and s.owner_id is null
      and s.id = any(snapshot.published_summary_ids);
    get diagnostics v_updated = row_count;
    v_child_rows := v_child_rows + v_updated;

    update public.document_table_facts f
    set owner_id = existing_owner.id
    from public.document_corpus_access_snapshots snapshot
    join auth.users existing_owner on existing_owner.id = snapshot.owner_id
    where snapshot.activation_id = v_activation_id
      and snapshot.document_id = f.document_id
      and f.owner_id is null
      and f.id = any(snapshot.published_table_fact_ids);
    get diagnostics v_updated = row_count;
    v_child_rows := v_child_rows + v_updated;

    if v_child_rows > v_max_child_rows then
      raise exception
        'document corpus access switch rewrote % retrieval-scoped derived owner rows, above the % row synchronous bound; the flip is rolled back',
        v_child_rows, v_max_child_rows
        using errcode = '54000';
    end if;

    update public.document_corpus_access_state
    set mode = 'private', activation_id = null, activated_at = null, updated_at = now()
    where singleton;
  end if;

  select count(*)::integer
  into v_snapshot_count
  from public.document_corpus_access_snapshots
  where activation_id = v_activation_id;

  select
    count(*)::integer,
    count(*) filter (
      where owner_id is null and coalesce(metadata, '{}'::jsonb)->'public_corpus' = 'true'::jsonb
    )::integer
  into v_document_count, v_public_count
  from public.documents;

  return pg_catalog.jsonb_build_object(
    'mode', p_mode,
    'changed', true,
    'activation_id', v_activation_id,
    'snapshot_count', v_snapshot_count,
    'document_count', v_document_count,
    'public_document_count', v_public_count
  );
end;
$$;

comment on function public.set_document_corpus_access_mode(text) is
  'Service-role-only reversible switch for corpus-wide document visibility. Public mode snapshots and publishes document access rows together with the three derived owner columns that are themselves retrieval visibility decisions (document_labels, document_summaries, document_table_facts); private mode restores only child IDs actually published by that activation to surviving owners and quarantines deleted-owner rows from document and retrieval reads. Derived artifacts filtered through their parent document owner are never rewritten. Each branch refuses, and rolls the whole flip back, rather than rewriting more than 200000 of those derived rows in one synchronous call; publish a larger corpus in batches through public.publish_approved_documents. Wall-clock bounding belongs to the caller: issue set local statement_timeout in the same transaction, because a function-level setting cannot re-arm a timer the running statement already started.';

revoke all on function public.set_document_corpus_access_mode(text)
  from public, anon, authenticated, service_role;
grant execute on function public.set_document_corpus_access_mode(text) to service_role;

-- The On Call mode's operational entries: orientation shelves, role-based
-- contacts, referral pathways, teaching sessions, escalation playbook cards and
-- site logistics. One table, discriminated by `section`, with the per-section
-- fields in `details` and validated in the API layer by a Zod schema per
-- section (src/lib/on-call/entry-model.ts).
--
-- `owner_id` is NOT NULL on purpose. Unlike `documents`, a null owner carries no
-- visibility meaning here: this table has no public state and must never gain
-- one, because its rows are a hospital's internal contact and orientation
-- information. Ownership is enforced at the API layer via the service-role
-- client, the same application-layer model as clinical_registry_records.
create table if not exists public.on_call_entries (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users(id) on delete cascade,
  section text not null check (
    section in ('contacts', 'playbook', 'referrals', 'orientation', 'education', 'logistics')
  ),
  slug text not null check (btrim(slug) <> ''),
  title text not null check (btrim(title) <> ''),
  subtitle text,
  body text,
  details jsonb not null default '{}'::jsonb,
  linked_document_ids uuid[] not null default '{}',
  tags text[] not null default '{}',
  -- A personal direct number. Excluded from the printable card and from any
  -- export; see src/lib/on-call/card-selection.ts.
  is_personal boolean not null default false,
  include_on_card boolean not null default false,
  sort_order integer not null default 0,
  -- When the owner last confirmed this entry is still correct. NULL means never.
  -- There is deliberately no stored due date or stale flag: freshness is derived
  -- at read time, so the twelve-month interval can change without a backfill.
  last_verified_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (owner_id, section, slug)
);

create index if not exists on_call_entries_owner_section_idx
  on public.on_call_entries(owner_id, section, sort_order, title);

drop trigger if exists on_call_entries_updated_at on public.on_call_entries;
create trigger on_call_entries_updated_at
  before update on public.on_call_entries
  for each row execute function public.set_updated_at();

alter table public.on_call_entries enable row level security;

revoke all on public.on_call_entries from anon, authenticated;

grant select, insert, update, delete on table public.on_call_entries to service_role;

drop policy if exists "on call entries service role all" on public.on_call_entries;
create policy "on call entries service role all" on public.on_call_entries
  for all to service_role using (true) with check (true);

-- CME: an owner's continuing-education record.
--
-- Single-owner, single-layer tenancy, the same design as `on_call_entries`:
-- RLS on, no grant at all to anon/authenticated, service_role only, and the
-- real owner predicate is `.eq("owner_id", …)` in application code where
-- `npm run check:owner-scope` can prove it.
--
-- `cme_requirements.spec` is jsonb rather than columns because the four
-- requirement shapes are not a fixed set: a trainee's weekly supervision
-- cadence and a count scoped to a rotation are already known to be coming, and
-- a shape change must not be a migration against the live clinical database.

create table if not exists public.cme_years (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  year smallint not null,
  total_hours numeric(6, 2) not null,
  -- Provenance travels with the targets and renders on every screen showing one.
  confirmed_on date not null,
  confirmed_source text not null,
  closed_at timestamptz,
  shortfall_note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (owner_id, year)
);

create table if not exists public.cme_requirements (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  year_id uuid not null references public.cme_years (id) on delete cascade,
  label text not null,
  source text not null check (source in ('national', 'college')),
  spec jsonb not null,
  completed_on date,
  sort_order smallint not null default 0,
  created_at timestamptz not null default now()
);

create table if not exists public.cme_routines (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  title text not null,
  cadence text not null check (cadence in ('weekly', 'monthly', 'quarterly')),
  usual_hours numeric(5, 2) not null,
  usual_allocations jsonb not null default '[]'::jsonb,
  next_due date,
  archived_at timestamptz,
  created_at timestamptz not null default now()
);

create table if not exists public.cme_entries (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  year_id uuid not null references public.cme_years (id) on delete cascade,
  -- A Perth calendar date, decided by the application. Never derived from a
  -- timestamp in the database, which would be UTC and would move an entry
  -- logged after 16:00 UTC on 31 December into the wrong year.
  activity_date date not null,
  title text not null,
  reflection text not null default '',
  cost_cents integer check (cost_cents is null or cost_cents >= 0),
  transcribed_at timestamptz,
  routine_id uuid references public.cme_routines (id) on delete set null,
  document_id uuid references public.documents (id) on delete set null,
  buckets text[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.cme_allocations (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  entry_id uuid not null references public.cme_entries (id) on delete cascade,
  category text not null check (category in ('educational', 'reviewing', 'measuring')),
  hours numeric(5, 2) not null check (hours > 0),
  unique (entry_id, category)
);

create index if not exists cme_entries_owner_year_date_idx
  on public.cme_entries (owner_id, year_id, activity_date desc);
create index if not exists cme_allocations_entry_idx
  on public.cme_allocations (entry_id);
create index if not exists cme_requirements_year_idx
  on public.cme_requirements (year_id, sort_order);

-- `cme_years` and `cme_entries` carry `updated_at`; keep it current the same
-- way every other mutable table in this schema does, rather than trusting
-- every future write path to set it by hand (on_call_entries, medication_records
-- and documents all follow this same before-update trigger pattern).
drop trigger if exists cme_years_updated_at on public.cme_years;
create trigger cme_years_updated_at
  before update on public.cme_years
  for each row execute function public.set_updated_at();

drop trigger if exists cme_entries_updated_at on public.cme_entries;
create trigger cme_entries_updated_at
  before update on public.cme_entries
  for each row execute function public.set_updated_at();

alter table public.cme_years enable row level security;
revoke all on table public.cme_years from public, anon, authenticated;
grant select, insert, update, delete on table public.cme_years to service_role;
drop policy if exists "cme_years service role all" on public.cme_years;
create policy "cme_years service role all" on public.cme_years
  for all to service_role using (true) with check (true);

alter table public.cme_requirements enable row level security;
revoke all on table public.cme_requirements from public, anon, authenticated;
grant select, insert, update, delete on table public.cme_requirements to service_role;
drop policy if exists "cme_requirements service role all" on public.cme_requirements;
create policy "cme_requirements service role all" on public.cme_requirements
  for all to service_role using (true) with check (true);

alter table public.cme_routines enable row level security;
revoke all on table public.cme_routines from public, anon, authenticated;
grant select, insert, update, delete on table public.cme_routines to service_role;
drop policy if exists "cme_routines service role all" on public.cme_routines;
create policy "cme_routines service role all" on public.cme_routines
  for all to service_role using (true) with check (true);

alter table public.cme_entries enable row level security;
revoke all on table public.cme_entries from public, anon, authenticated;
grant select, insert, update, delete on table public.cme_entries to service_role;
drop policy if exists "cme_entries service role all" on public.cme_entries;
create policy "cme_entries service role all" on public.cme_entries
  for all to service_role using (true) with check (true);

alter table public.cme_allocations enable row level security;
revoke all on table public.cme_allocations from public, anon, authenticated;
grant select, insert, update, delete on table public.cme_allocations to service_role;
drop policy if exists "cme_allocations service role all" on public.cme_allocations;
create policy "cme_allocations service role all" on public.cme_allocations
  for all to service_role using (true) with check (true);


-- CME core workflows: schema projection of 20260922163920.
-- Prepared locally only. Requires owner-approved deployment; do not apply from a task.
set search_path = public, pg_catalog, pg_temp;
set lock_timeout = '5s';
set statement_timeout = '60s';

alter table public.cme_entries add column formal_peer_review_hours numeric(5,2) not null default 0 check (formal_peer_review_hours >= 0);
alter table public.cme_entries add column request_id uuid;
alter table public.cme_entries add column request_payload jsonb;
create unique index cme_entries_owner_request on public.cme_entries(owner_id, request_id) where request_id is not null;
alter table public.cme_years add constraint cme_years_id_owner_unique unique(id, owner_id);
alter table public.cme_entries add constraint cme_entries_id_owner_unique unique(id, owner_id);
alter table public.cme_routines add constraint cme_routines_id_owner_unique unique(id, owner_id);
alter table public.cme_entries add constraint cme_entries_year_owner_fk foreign key(year_id, owner_id) references public.cme_years(id, owner_id) on delete cascade;
alter table public.cme_requirements add constraint cme_requirements_year_owner_fk foreign key(year_id, owner_id) references public.cme_years(id, owner_id) on delete cascade;
alter table public.cme_allocations add constraint cme_allocations_entry_owner_fk foreign key(entry_id, owner_id) references public.cme_entries(id, owner_id) on delete cascade;
alter table public.cme_entries add constraint cme_entries_routine_owner_fk foreign key(routine_id, owner_id) references public.cme_routines(id, owner_id);

-- Serialise mutations for one owner, including competing confirmation/create requests.
-- Caller identity is derived from the authenticated session by server code. These RPCs
-- are invoker functions with no privileges granted to anon/authenticated/public.
create function public.cme_confirm_year(p_owner_id uuid, p_set jsonb) returns uuid
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare
  v_year public.cme_years; v_req jsonb; v_id uuid; v_order integer := 0; v_keep uuid[] := '{}';
begin
  if p_owner_id is null or jsonb_typeof(p_set->'requirements') is distinct from 'array' or jsonb_array_length(p_set->'requirements') not between 1 and 30 then raise exception 'cme_invalid_request'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_owner_id::text, 23092026));
  select * into v_year from public.cme_years where owner_id=p_owner_id and year=(p_set->>'year')::smallint for update;
  if v_year.closed_at is not null then raise exception 'cme_year_closed'; end if;
  insert into public.cme_years(owner_id,year,total_hours,confirmed_on,confirmed_source)
  values(p_owner_id,(p_set->>'year')::smallint,(p_set->>'totalHours')::numeric,(p_set->>'confirmedOn')::date,p_set->>'confirmedSource')
  on conflict(owner_id,year) do update set total_hours=excluded.total_hours,confirmed_on=excluded.confirmed_on,confirmed_source=excluded.confirmed_source
  returning * into v_year;
  for v_req in select value from jsonb_array_elements(p_set->'requirements') loop
    v_id := null;
    -- Only reuse identities already owned by this exact year. Stable client names
    -- and foreign UUIDs are safely translated to new server-generated identities.
    select id into v_id from public.cme_requirements where owner_id=p_owner_id and year_id=v_year.id and id::text=v_req->>'id';
    if v_id is null then v_id:=gen_random_uuid(); end if;
    insert into public.cme_requirements(id,owner_id,year_id,label,source,spec,completed_on,sort_order)
    values(v_id,p_owner_id,v_year.id,v_req->>'label',v_req->>'source',v_req->'spec',(v_req->>'completedOn')::date,v_order)
    on conflict(id) do update set label=excluded.label,source=excluded.source,spec=excluded.spec,completed_on=excluded.completed_on,sort_order=excluded.sort_order;
    v_keep:=array_append(v_keep,v_id); v_order:=v_order+1;
  end loop;
  delete from public.cme_requirements where owner_id=p_owner_id and year_id=v_year.id and not(id=any(v_keep));
  return v_year.id;
end $$;

create function public.cme_save_entry(p_owner_id uuid,p_year_id uuid,p_entry_id uuid,p_entry jsonb,p_create boolean,p_request_id uuid default null) returns jsonb
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare
  v_year public.cme_years; v_existing public.cme_entries; v_saved public.cme_entries;
  v_routine public.cme_routines; v_alloc jsonb; v_review numeric; v_total numeric; v_count integer;
begin
  if p_owner_id is null then raise exception 'cme_invalid_request'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_owner_id::text, 23092026));
  if p_create and p_request_id is not null then
    select * into v_existing from public.cme_entries where owner_id=p_owner_id and request_id=p_request_id;
    if found then
      if v_existing.request_payload is distinct from p_entry then raise exception 'cme_retry_conflict'; end if;
      return to_jsonb(v_existing) || jsonb_build_object('cme_allocations',(select coalesce(jsonb_agg(jsonb_build_object('category',category,'hours',hours)),'[]') from public.cme_allocations where owner_id=p_owner_id and entry_id=v_existing.id));
    end if;
  end if;
  select * into v_year from public.cme_years where owner_id=p_owner_id and id=p_year_id for update;
  if not found then raise exception 'cme_year_not_confirmed'; end if;
  if v_year.closed_at is not null then raise exception 'cme_year_closed'; end if;
  if extract(year from (p_entry->>'date')::date) <> v_year.year then raise exception 'cme_invalid_request'; end if;
  if not p_create then
    select * into v_existing from public.cme_entries where owner_id=p_owner_id and id=p_entry_id for update;
    if not found then raise exception 'cme_entry_not_found'; end if;
    if exists(select 1 from public.cme_years where owner_id=p_owner_id and id=v_existing.year_id and closed_at is not null) then raise exception 'cme_year_closed'; end if;
  end if;
  if jsonb_typeof(p_entry->'allocations') is distinct from 'array' then raise exception 'cme_invalid_request'; end if;
  select count(*),coalesce(sum((a->>'hours')::numeric),0),coalesce(sum((a->>'hours')::numeric) filter(where a->>'category'='reviewing'),0)
    into v_count,v_total,v_review from jsonb_array_elements(p_entry->'allocations') a;
  if v_count not between 1 and 3 or v_total > 24 or coalesce((p_entry->>'formalPeerReviewHours')::numeric,0) not between 0 and v_review then raise exception 'cme_invalid_request'; end if;
  if p_entry->>'documentId' is not null and not exists(select 1 from public.documents where owner_id=p_owner_id and id=(p_entry->>'documentId')::uuid) then raise exception 'cme_invalid_link'; end if;
  if p_entry->>'routineId' is not null then
    select * into v_routine from public.cme_routines where owner_id=p_owner_id and id=(p_entry->>'routineId')::uuid for update;
    if not found or (p_create and v_routine.archived_at is not null) then raise exception 'cme_invalid_link'; end if;
  end if;
  if p_create then
    insert into public.cme_entries(id,owner_id,year_id,activity_date,title,reflection,cost_cents,routine_id,document_id,buckets,formal_peer_review_hours,request_id,request_payload)
    values(p_entry_id,p_owner_id,p_year_id,(p_entry->>'date')::date,p_entry->>'title',p_entry->>'reflection',(p_entry->>'costCents')::integer,(p_entry->>'routineId')::uuid,(p_entry->>'documentId')::uuid,array(select jsonb_array_elements_text(p_entry->'buckets')),coalesce((p_entry->>'formalPeerReviewHours')::numeric,0),p_request_id,p_entry)
    returning * into v_saved;
  else
    update public.cme_entries set year_id=p_year_id,activity_date=(p_entry->>'date')::date,title=p_entry->>'title',reflection=p_entry->>'reflection',cost_cents=(p_entry->>'costCents')::integer,routine_id=(p_entry->>'routineId')::uuid,document_id=(p_entry->>'documentId')::uuid,buckets=array(select jsonb_array_elements_text(p_entry->'buckets')),formal_peer_review_hours=coalesce((p_entry->>'formalPeerReviewHours')::numeric,0)
    where owner_id=p_owner_id and id=p_entry_id returning * into v_saved;
    delete from public.cme_allocations where owner_id=p_owner_id and entry_id=p_entry_id;
  end if;
  for v_alloc in select value from jsonb_array_elements(p_entry->'allocations') loop
    insert into public.cme_allocations(owner_id,entry_id,category,hours) values(p_owner_id,p_entry_id,v_alloc->>'category',(v_alloc->>'hours')::numeric);
  end loop;
  -- A routine advances only after the complete entry is saved, in this same
  -- transaction. An idempotent retry returns above and never advances twice.
  if p_create and v_routine.id is not null and v_routine.next_due is not null and v_routine.next_due <= (p_entry->>'date')::date then
    update public.cme_routines set next_due=((p_entry->>'date')::date + case v_routine.cadence when 'weekly' then interval '7 days' when 'monthly' then interval '1 month' else interval '3 months' end)::date where owner_id=p_owner_id and id=v_routine.id;
  end if;
  return to_jsonb(v_saved)||jsonb_build_object('cme_allocations',p_entry->'allocations');
end $$;

-- Guard other existing service-role entry mutations (copy stamp/delete), and
-- ensure stored dates remain in their owner-scoped year. Locking the year also
-- makes concurrent closure and entry mutation serial rather than check-then-write.
create function public.cme_guard_entry() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_year public.cme_years;
begin
  if tg_op <> 'INSERT' then
    select * into v_year from public.cme_years where id=old.year_id and owner_id=old.owner_id for update;
    if v_year.closed_at is not null then raise exception 'cme_year_closed'; end if;
  end if;
  if tg_op='DELETE' then return old; end if;
  select * into v_year from public.cme_years where id=new.year_id and owner_id=new.owner_id for update;
  if not found or extract(year from new.activity_date)<>v_year.year then raise exception 'cme_invalid_request'; end if;
  if v_year.closed_at is not null then raise exception 'cme_year_closed'; end if;
  if new.document_id is not null and not exists(select 1 from public.documents where id=new.document_id and owner_id=new.owner_id) then raise exception 'cme_invalid_link'; end if;
  return new;
end $$;
create trigger cme_guard_entry before insert or update or delete on public.cme_entries for each row execute function public.cme_guard_entry();

-- Deferred because replacing allocations has an intentionally incomplete
-- intermediate state inside a transaction. Commit cannot persist invalid credit.
create function public.cme_check_entry_allocations() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_id uuid; v_entry public.cme_entries; v_total numeric; v_review numeric; v_count integer;
begin
  if tg_table_name='cme_entries' then v_id:=coalesce(new.id,old.id); else v_id:=coalesce(new.entry_id,old.entry_id); end if;
  select * into v_entry from public.cme_entries where id=v_id;
  if not found then return null; end if;
  select count(*),coalesce(sum(hours),0),coalesce(sum(hours) filter(where category='reviewing'),0) into v_count,v_total,v_review from public.cme_allocations where entry_id=v_id and owner_id=v_entry.owner_id;
  if v_count not between 1 and 3 or v_total>24 or v_entry.formal_peer_review_hours>v_review then raise exception 'cme_invalid_allocations'; end if;
  return null;
end $$;
create constraint trigger cme_entry_allocations_valid after insert or update on public.cme_entries deferrable initially deferred for each row execute function public.cme_check_entry_allocations();
create constraint trigger cme_allocations_valid after insert or update or delete on public.cme_allocations deferrable initially deferred for each row execute function public.cme_check_entry_allocations();

revoke all on function public.cme_confirm_year(uuid,jsonb), public.cme_save_entry(uuid,uuid,uuid,jsonb,boolean,uuid), public.cme_guard_entry(), public.cme_check_entry_allocations() from public, anon, authenticated;
grant execute on function public.cme_confirm_year(uuid,jsonb), public.cme_save_entry(uuid,uuid,uuid,jsonb,boolean,uuid), public.cme_guard_entry(), public.cme_check_entry_allocations() to service_role;


-- Projection: 20260922174716_on_call_service_handbooks.sql
-- Local preparation. This is a new invited-service store, never a republication
-- of public on_call_entries, private compliance, CME, or patient records.
set search_path = public, pg_catalog, pg_temp;
set lock_timeout = '5s';
set statement_timeout = '60s';

create table public.on_call_services (
  id uuid primary key default gen_random_uuid(),
  name text not null check (length(btrim(name)) between 1 and 160),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);
create table public.on_call_service_sites (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services(id) on delete cascade,
  name text not null check (length(btrim(name)) between 1 and 160),
  unique (id, service_id), unique(service_id, name)
);
create table public.on_call_service_members (
  service_id uuid not null references public.on_call_services(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  role text not null check(role in ('member','editor','admin')),
  clinical_reviewer boolean not null default false,
  joined_at timestamptz not null default now(),
  revoked_at timestamptz,
  primary key(service_id,user_id)
);
create index on_call_service_members_actor on public.on_call_service_members(user_id,service_id) where revoked_at is null;
create table public.on_call_service_invitations (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services(id) on delete cascade,
  token_hash text not null unique check(token_hash ~ '^[a-f0-9]{64}$'),
  role text not null check(role in ('member','editor','admin')),
  issued_by uuid references auth.users(id) on delete set null,
  expires_at timestamptz not null,
  created_at timestamptz not null default now(),
  revoked_at timestamptz,
  used_at timestamptz,
  used_by uuid references auth.users(id) on delete set null,
  check(expires_at > created_at and expires_at <= created_at + interval '7 days')
);
create table public.on_call_service_entries (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services(id) on delete cascade,
  site_id uuid,
  revision integer not null default 1 check(revision > 0),
  content jsonb not null check(jsonb_typeof(content)='object'),
  author_id uuid references auth.users(id) on delete set null,
  status text not null check(status in ('draft','pending_review','published','withdrawn')),
  published_content jsonb,
  published_revision integer,
  published_author_id uuid references auth.users(id) on delete set null,
  published_reviewed_by uuid references auth.users(id) on delete set null,
  published_reviewed_at timestamptz,
  review_comment text not null default '',
  updated_at timestamptz not null default now(),
  unique(id,service_id),
  foreign key(site_id,service_id) references public.on_call_service_sites(id,service_id),
  check((published_content is null) = (published_revision is null)),
  check(published_revision is null or published_revision <= revision)
);
create index on_call_service_entries_service on public.on_call_service_entries(service_id,site_id);
create table public.on_call_service_reports (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services(id) on delete cascade,
  entry_id uuid not null,
  reported_by uuid references auth.users(id) on delete set null,
  reason text not null check(length(btrim(reason)) between 1 and 1500),
  status text not null default 'open' check(status in ('open','resolved')),
  resolution text not null default '',
  resolved_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  resolved_at timestamptz,
  foreign key(entry_id,service_id) references public.on_call_service_entries(id,service_id) on delete cascade
);
create table public.on_call_service_orientation (
  service_id uuid not null references public.on_call_services(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  site_id uuid not null,
  entry_id uuid not null,
  rotation text not null check(length(btrim(rotation)) between 1 and 100),
  revision integer not null check(revision > 0),
  completed_at timestamptz not null default now(),
  primary key(service_id,user_id,site_id,entry_id,rotation),
  foreign key(site_id,service_id) references public.on_call_service_sites(id,service_id),
  foreign key(entry_id,service_id) references public.on_call_service_entries(id,service_id) on delete cascade
);

-- Browser JWT roles have no direct table access. The invoker RPC is called only
-- by authenticated server routes using service_role and session-derived actor ID.
alter table public.on_call_services enable row level security;
alter table public.on_call_service_sites enable row level security;
alter table public.on_call_service_members enable row level security;
alter table public.on_call_service_invitations enable row level security;
alter table public.on_call_service_entries enable row level security;
alter table public.on_call_service_reports enable row level security;
alter table public.on_call_service_orientation enable row level security;
revoke all on public.on_call_services,public.on_call_service_sites,public.on_call_service_members,public.on_call_service_invitations,public.on_call_service_entries,public.on_call_service_reports,public.on_call_service_orientation from public,anon,authenticated;
grant select,insert,update,delete on public.on_call_services,public.on_call_service_sites,public.on_call_service_members,public.on_call_service_invitations,public.on_call_service_entries,public.on_call_service_reports,public.on_call_service_orientation to service_role;

create function public.on_call_service_command(p_actor_id uuid,p_service_id uuid,p_action text,p_payload jsonb default '{}') returns jsonb
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare
  v_service public.on_call_services;
  v_member public.on_call_service_members;
  v_target public.on_call_service_members;
  v_invite public.on_call_service_invitations;
  v_entry public.on_call_service_entries;
  v_report public.on_call_service_reports;
  v_content jsonb;
  v_result jsonb;
  v_id uuid;
  v_site uuid;
  v_revision integer;
  v_status text;
  v_can_edit boolean;
  v_can_draft boolean;
  v_source jsonb;
begin
  -- API authentication verifies the actor; do not require service_role access to
  -- auth.users. Membership checks below authorize every service operation.
  if p_actor_id is null then raise exception 'service_auth_required'; end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then raise exception 'service_invalid_request'; end if;

  if p_action='list' then
    select jsonb_build_object('services',coalesce(jsonb_agg(jsonb_build_object(
      'id',s.id,'name',s.name,'role',m.role,'clinicalReviewer',m.clinical_reviewer,
      'sites',(select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'name',t.name) order by t.name),'[]') from public.on_call_service_sites t where t.service_id=s.id)
    ) order by s.name),'[]')) into v_result
    from public.on_call_services s join public.on_call_service_members m on m.service_id=s.id
    where m.user_id=p_actor_id and m.revoked_at is null;
    return v_result;
  end if;

  if p_action='create' then
    perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text, 74816));
    if (select count(*) from public.on_call_service_members where user_id=p_actor_id and revoked_at is null) >= 50 then raise exception 'service_limit'; end if;
    insert into public.on_call_services(name,created_by) values(p_payload->>'name',p_actor_id) returning * into v_service;
    insert into public.on_call_service_sites(service_id,name) values(v_service.id,p_payload->>'siteName') returning id into v_site;
    insert into public.on_call_service_members(service_id,user_id,role) values(v_service.id,p_actor_id,'admin');
    return jsonb_build_object('serviceId',v_service.id,'siteId',v_site);
  end if;

  if p_action='join' then
    select service_id into p_service_id from public.on_call_service_invitations where token_hash=p_payload->>'tokenHash';
    if p_service_id is null then raise exception 'service_invitation_invalid'; end if;
  end if;
  -- Shared lock order for reads and writes: service, membership, then target.
  -- A read starting after revocation commits cannot return the removed service.
  select * into v_service from public.on_call_services where id=p_service_id for update;
  if not found then raise exception 'service_access_denied'; end if;

  if p_action='join' then
    select * into v_invite from public.on_call_service_invitations
      where service_id=p_service_id and token_hash=p_payload->>'tokenHash' for update;
    if not found or v_invite.revoked_at is not null or v_invite.used_at is not null or v_invite.expires_at <= now()
      or not exists(select 1 from public.on_call_service_members where service_id=p_service_id and user_id=v_invite.issued_by and role='admin' and revoked_at is null)
      then raise exception 'service_invitation_invalid'; end if;
    if exists(select 1 from public.on_call_service_members where service_id=p_service_id and user_id=p_actor_id and revoked_at is null) then
      raise exception 'service_already_member';
    end if;
    if (select count(*) from public.on_call_service_members where service_id=p_service_id and revoked_at is null) >= 500 then raise exception 'service_limit'; end if;
    insert into public.on_call_service_members(service_id,user_id,role) values(p_service_id,p_actor_id,v_invite.role)
      on conflict(service_id,user_id) do update set role=excluded.role,clinical_reviewer=false,revoked_at=null,joined_at=now();
    update public.on_call_service_invitations set used_at=now(),used_by=p_actor_id where id=v_invite.id;
    return jsonb_build_object('serviceId',p_service_id);
  end if;

  select * into v_member from public.on_call_service_members where service_id=p_service_id and user_id=p_actor_id and revoked_at is null;
  if not found then raise exception 'service_access_denied'; end if;
  v_can_edit := v_member.role in ('editor','admin');
  v_can_draft := v_can_edit or v_member.clinical_reviewer;
  v_site := nullif(p_payload->>'siteId','')::uuid;
