    if v_entry.id is not null and (v_entry.content->>'kind'<>'operational' or v_entry.published_content->>'kind'<>'operational') and v_content->>'kind'='operational' then raise exception 'service_review_required'; end if;
    if v_id is null then
      insert into public.on_call_service_entries(service_id,site_id,content,author_id,status)
        values(p_service_id,v_site,v_content,p_actor_id,v_status) returning id into v_id;
    else
      update public.on_call_service_entries set site_id=v_site,content=v_content,author_id=p_actor_id,status=v_status,revision=v_revision,review_comment='',updated_at=now() where id=v_id;
    end if;
    if v_status='published' then
      update public.on_call_service_entries set published_content=v_content,published_revision=v_revision,published_author_id=p_actor_id,published_reviewed_by=null,published_reviewed_at=null where id=v_id;
    end if;
    return jsonb_build_object('entryId',v_id,'revision',v_revision,'status',v_status);
  elsif p_action in ('entry.review','entry.withdraw','report.create','orientation.set') then
    select * into v_entry from public.on_call_service_entries where id=(p_payload->>'entryId')::uuid and service_id=p_service_id for update;
    if not found then raise exception 'service_not_found'; end if;
    if p_action in ('entry.review','entry.withdraw') then
      if v_entry.revision is distinct from (p_payload->>'expectedRevision')::integer then raise exception 'service_revision_conflict'; end if;
      if p_action='entry.withdraw' then
        update public.on_call_service_entries set status='withdrawn',revision=revision+1,published_content=null,published_revision=null,published_author_id=null,published_reviewed_by=null,published_reviewed_at=null,updated_at=now() where id=v_entry.id;
      else
        if not v_member.clinical_reviewer or v_entry.author_id=p_actor_id then raise exception 'service_review_denied'; end if;
        if v_entry.status<>'pending_review' or v_entry.content->>'kind'='operational' then raise exception 'service_review_required'; end if;
        if p_payload->>'decision'='approve' then
          update public.on_call_service_entries set status='published',revision=revision+1,published_content=content,published_revision=revision+1,published_author_id=author_id,published_reviewed_by=p_actor_id,published_reviewed_at=now(),review_comment=p_payload->>'comment',updated_at=now() where id=v_entry.id;
        elsif p_payload->>'decision'='return' then
          update public.on_call_service_entries set status='draft',revision=revision+1,review_comment=p_payload->>'comment',updated_at=now() where id=v_entry.id;
        else raise exception 'service_invalid_request'; end if;
      end if;
      return jsonb_build_object('ok',true);
    elsif p_action='report.create' then
      if v_entry.published_content is null then raise exception 'service_not_found'; end if;
      if (select count(*) from public.on_call_service_reports where service_id=p_service_id and status='open')>=1000 then raise exception 'service_limit'; end if;
      insert into public.on_call_service_reports(service_id,entry_id,reported_by,reason) values(p_service_id,v_entry.id,p_actor_id,p_payload->>'reason') returning id into v_id;
      return jsonb_build_object('reportId',v_id);
    else
      if v_site is null or v_entry.published_content is null or v_entry.published_content->>'section'<>'orientation'
        or (v_entry.published_content->>'siteId' is not null and v_entry.published_content->>'siteId'<>v_site::text) then raise exception 'service_invalid_orientation'; end if;
      if (p_payload->>'completed')::boolean then
        insert into public.on_call_service_orientation(service_id,user_id,site_id,entry_id,rotation,revision)
          values(p_service_id,p_actor_id,v_site,v_entry.id,p_payload->>'rotation',v_entry.published_revision)
          on conflict(service_id,user_id,site_id,entry_id,rotation) do update set revision=excluded.revision,completed_at=now();
      else
        delete from public.on_call_service_orientation where service_id=p_service_id and user_id=p_actor_id and site_id=v_site and entry_id=v_entry.id and rotation=p_payload->>'rotation';
      end if;
      return jsonb_build_object('ok',true);
    end if;
  elsif p_action='report.resolve' then
    update public.on_call_service_reports set status='resolved',resolution=p_payload->>'resolution',resolved_by=p_actor_id,resolved_at=now()
      where service_id=p_service_id and id=(p_payload->>'reportId')::uuid;
    if not found then raise exception 'service_not_found'; end if;
    return jsonb_build_object('ok',true);
  end if;
  raise exception 'service_invalid_request';
end $$;
revoke all on function public.on_call_service_command(uuid,uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.on_call_service_command(uuid,uuid,text,jsonb) to service_role;


-- Projection: 20260922174730_cme_archive_source.sql
-- Reversible CME archives and learning source links. No evidence or record deletion.
set local lock_timeout = '5s';
set local statement_timeout = '30s';
alter table public.cme_entries add column archived_at timestamptz, add column source_url text;
alter table public.cme_entries add constraint cme_entries_source_url_length check (source_url is null or char_length(source_url) between 1 and 2000);
comment on column public.cme_entries.source_url is 'Learning source reference only; not evidence of participation.';

create function public.cme_set_entry_archived(p_owner_id uuid,p_entry_id uuid,p_archived boolean) returns jsonb
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_entry public.cme_entries; v_year public.cme_years;
begin
  if p_owner_id is null or p_archived is null then raise exception 'cme_invalid_request'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_owner_id::text,23092026));
  select * into v_entry from public.cme_entries where owner_id=p_owner_id and id=p_entry_id for update;
  if not found then raise exception 'cme_entry_not_found'; end if;
  select * into v_year from public.cme_years where owner_id=p_owner_id and id=v_entry.year_id for update;
  if not found then raise exception 'cme_year_not_confirmed'; end if;
  if v_year.closed_at is not null then raise exception 'cme_year_closed'; end if;
  if (v_entry.archived_at is not null) is distinct from p_archived then
    update public.cme_entries set archived_at=case when p_archived then now() else null end
    where owner_id=p_owner_id and id=p_entry_id returning * into v_entry;
  end if;
  return to_jsonb(v_entry)||jsonb_build_object('cme_allocations',(select coalesce(jsonb_agg(jsonb_build_object('category',category,'hours',hours)),'[]') from public.cme_allocations where owner_id=p_owner_id and entry_id=p_entry_id));
end $$;
revoke all on function public.cme_set_entry_archived(uuid,uuid,boolean) from public,anon,authenticated;
grant execute on function public.cme_set_entry_archived(uuid,uuid,boolean) to service_role;

create function public.cme_guard_archived_entry() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  if old.archived_at is not null and new.archived_at is not null then raise exception 'cme_entry_archived'; end if;
  return new;
end $$;
revoke all on function public.cme_guard_archived_entry() from public,anon,authenticated;
grant execute on function public.cme_guard_archived_entry() to service_role;
create trigger cme_archived_entry_guard before update on public.cme_entries for each row execute function public.cme_guard_archived_entry();

create or replace function public.cme_save_entry(p_owner_id uuid,p_year_id uuid,p_entry_id uuid,p_entry jsonb,p_create boolean,p_request_id uuid default null) returns jsonb
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare
  v_year public.cme_years; v_existing public.cme_entries; v_saved public.cme_entries;
  v_routine public.cme_routines; v_alloc jsonb; v_review numeric; v_total numeric; v_count integer;
begin
  if p_owner_id is null then raise exception 'cme_invalid_request'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_owner_id::text, 23092026));
  if p_create and p_request_id is not null then
    select * into v_existing from public.cme_entries where owner_id=p_owner_id and request_id=p_request_id;
    if found then
      if v_existing.request_payload is distinct from p_entry then raise exception 'cme_retry_conflict'; end if;
      return to_jsonb(v_existing) || jsonb_build_object('cme_allocations',(select coalesce(jsonb_agg(jsonb_build_object('category',category,'hours',hours)),'[]') from public.cme_allocations where owner_id=p_owner_id and entry_id=v_existing.id));
    end if;
  end if;
  select * into v_year from public.cme_years where owner_id=p_owner_id and id=p_year_id for update;
  if not found then raise exception 'cme_year_not_confirmed'; end if;
  if v_year.closed_at is not null then raise exception 'cme_year_closed'; end if;
  if extract(year from (p_entry->>'date')::date) <> v_year.year then raise exception 'cme_invalid_request'; end if;
  if not p_create then
    select * into v_existing from public.cme_entries where owner_id=p_owner_id and id=p_entry_id for update;
    if not found then raise exception 'cme_entry_not_found'; end if;
    if v_existing.archived_at is not null then raise exception 'cme_entry_archived'; end if;
    if exists(select 1 from public.cme_years where owner_id=p_owner_id and id=v_existing.year_id and closed_at is not null) then raise exception 'cme_year_closed'; end if;
  end if;
  if jsonb_typeof(p_entry->'allocations') is distinct from 'array' then raise exception 'cme_invalid_request'; end if;
  select count(*),coalesce(sum((a->>'hours')::numeric),0),coalesce(sum((a->>'hours')::numeric) filter(where a->>'category'='reviewing'),0)
    into v_count,v_total,v_review from jsonb_array_elements(p_entry->'allocations') a;
  if v_count not between 1 and 3 or v_total > 24 or coalesce((p_entry->>'formalPeerReviewHours')::numeric,0) not between 0 and v_review then raise exception 'cme_invalid_request'; end if;
  if p_entry->>'documentId' is not null and not exists(select 1 from public.documents where owner_id=p_owner_id and id=(p_entry->>'documentId')::uuid) then raise exception 'cme_invalid_link'; end if;
  if p_entry->>'routineId' is not null then
    select * into v_routine from public.cme_routines where owner_id=p_owner_id and id=(p_entry->>'routineId')::uuid for update;
    if not found or (p_create and v_routine.archived_at is not null) then raise exception 'cme_invalid_link'; end if;
  end if;
  if p_create then
    insert into public.cme_entries(id,owner_id,year_id,activity_date,title,reflection,cost_cents,routine_id,document_id,buckets,formal_peer_review_hours,request_id,request_payload,source_url)
    values(p_entry_id,p_owner_id,p_year_id,(p_entry->>'date')::date,p_entry->>'title',p_entry->>'reflection',(p_entry->>'costCents')::integer,(p_entry->>'routineId')::uuid,(p_entry->>'documentId')::uuid,array(select jsonb_array_elements_text(p_entry->'buckets')),coalesce((p_entry->>'formalPeerReviewHours')::numeric,0),p_request_id,p_entry,p_entry->>'sourceUrl')
    returning * into v_saved;
  else
    update public.cme_entries set year_id=p_year_id,activity_date=(p_entry->>'date')::date,title=p_entry->>'title',reflection=p_entry->>'reflection',cost_cents=(p_entry->>'costCents')::integer,routine_id=(p_entry->>'routineId')::uuid,document_id=(p_entry->>'documentId')::uuid,buckets=array(select jsonb_array_elements_text(p_entry->'buckets')),formal_peer_review_hours=coalesce((p_entry->>'formalPeerReviewHours')::numeric,0),source_url=p_entry->>'sourceUrl'
    where owner_id=p_owner_id and id=p_entry_id returning * into v_saved;
    delete from public.cme_allocations where owner_id=p_owner_id and entry_id=p_entry_id;
  end if;
  for v_alloc in select value from jsonb_array_elements(p_entry->'allocations') loop
    insert into public.cme_allocations(owner_id,entry_id,category,hours) values(p_owner_id,p_entry_id,v_alloc->>'category',(v_alloc->>'hours')::numeric);
  end loop;
  -- A routine advances only after the complete entry is saved, in this same
  -- transaction. An idempotent retry returns above and never advances twice.
  if p_create and v_routine.id is not null and v_routine.next_due is not null and v_routine.next_due <= (p_entry->>'date')::date then
    update public.cme_routines set next_due=((p_entry->>'date')::date + case v_routine.cadence when 'weekly' then interval '7 days' when 'monthly' then interval '1 month' else interval '3 months' end)::date where owner_id=p_owner_id and id=v_routine.id;
  end if;
  return to_jsonb(v_saved)||jsonb_build_object('cme_allocations',p_entry->'allocations');
end $$;


-- Projection: 20260922175023_cme_private_evidence.sql
-- Private portfolio evidence is separate from clinical ingestion and service handbooks.
set local lock_timeout = '5s';
set local statement_timeout = '30s';

create table public.cme_evidence (
  id uuid primary key,
  owner_id uuid not null references auth.users(id) on delete cascade,
  entry_id uuid not null,
  file_name text not null check (length(file_name) between 1 and 180),
  content_type text not null check (content_type in ('application/pdf','image/jpeg','image/png')),
  byte_size integer not null check (byte_size between 1 and 10485760),
  sha256 text not null check (sha256 ~ '^[a-f0-9]{64}$'),
  storage_path text not null unique,
  kind text not null check (kind in ('certificate','receipt','assessment','other')),
  redaction_confirmed boolean not null check (redaction_confirmed),
  preview_confirmed boolean not null check (preview_confirmed),
  uploaded_at timestamptz not null default now(),
  unique (entry_id, sha256),
  foreign key (entry_id, owner_id) references public.cme_entries(id, owner_id) on delete restrict,
  check (storage_path = owner_id::text || '/' || entry_id::text || '/' || id::text)
);
create index cme_evidence_owner_entry_idx on public.cme_evidence(owner_id, entry_id);
alter table public.cme_evidence enable row level security;
revoke all on public.cme_evidence from public, anon, authenticated;
grant select, insert on public.cme_evidence to service_role;

create function public.cme_guard_evidence_insert() returns trigger
language plpgsql security invoker set search_path = public, pg_temp as $$
declare v_entry public.cme_entries%rowtype; v_closed timestamptz;
begin
  perform pg_advisory_xact_lock(hashtextextended(new.owner_id::text, 23092026));
  select * into v_entry from public.cme_entries where id=new.entry_id and owner_id=new.owner_id;
  if not found then raise exception 'cme_evidence_entry_not_found'; end if;
  select closed_at into v_closed from public.cme_years where id=v_entry.year_id and owner_id=new.owner_id for update;
  if not found or v_closed is not null or v_entry.archived_at is not null then
    raise exception 'cme_evidence_entry_not_writable';
  end if;
  if (select count(*) from public.cme_evidence where owner_id=new.owner_id and entry_id=new.entry_id) >= 20 then
    raise exception 'cme_evidence_limit';
  end if;
  return new;
end $$;
revoke execute on function public.cme_guard_evidence_insert() from public, anon, authenticated;
grant execute on function public.cme_guard_evidence_insert() to service_role;
create trigger cme_evidence_insert_guard before insert on public.cme_evidence
  for each row execute function public.cme_guard_evidence_insert();

create function public.cme_evidence_counts(p_owner_id uuid, p_year integer) returns jsonb
language sql stable security invoker set search_path = public, pg_temp as $$
  select coalesce(jsonb_object_agg(entry_id, evidence_count), '{}'::jsonb)
  from (
    select e.id as entry_id, count(a.id) as evidence_count
    from public.cme_entries e join public.cme_years y on y.id=e.year_id and y.owner_id=p_owner_id
    left join public.cme_evidence a on a.entry_id=e.id and a.owner_id=p_owner_id
    where e.owner_id=p_owner_id and y.year=p_year group by e.id
  ) counts
$$;
revoke execute on function public.cme_evidence_counts(uuid,integer) from public, anon, authenticated;
grant execute on function public.cme_evidence_counts(uuid,integer) to service_role;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values ('cme-private-evidence','cme-private-evidence',false,10485760,array['application/pdf','image/jpeg','image/png'])
on conflict (id) do update set public=false, file_size_limit=excluded.file_size_limit, allowed_mime_types=excluded.allowed_mime_types;
-- Even an unrelated permissive storage policy must not expose portfolio objects.
create policy cme_evidence_no_direct_access on storage.objects as restrictive
  for all to anon, authenticated
  using (bucket_id <> 'cme-private-evidence') with check (bucket_id <> 'cme-private-evidence');


-- Projection: 20260924130000_cme_evidence_removal.sql
-- Owner-requested removal of CME evidence, with a recorded reason.
-- A file uploaded by mistake (for example one still carrying a patient identifier) could not be
-- taken out of the private portfolio at all. Removal keeps a tombstone row — when, and the
-- owner's reason — and the API then deletes the stored object. It is allowed in a closed year
-- and on an archived entry, because the reason to remove a file is privacy, not bookkeeping.
set local lock_timeout = '5s';
set local statement_timeout = '30s';

alter table public.cme_evidence
  add column removed_at timestamptz,
  add column removal_reason text,
  add constraint cme_evidence_removal_recorded check (
    (removed_at is null and removal_reason is null)
    or (removed_at is not null and length(btrim(removal_reason)) between 3 and 500)
  );

-- A removed file must not stop the same file being attached again once it has been checked, so
-- uniqueness applies only to files still attached.
alter table public.cme_evidence drop constraint cme_evidence_entry_id_sha256_key;
create unique index cme_evidence_active_entry_sha256_key
  on public.cme_evidence(entry_id, sha256) where removed_at is null;

-- The server may record a removal on these three columns and nothing else.
grant update (removed_at, removal_reason, file_name) on public.cme_evidence to service_role;

-- The 20-file limit counts files still attached.
create or replace function public.cme_guard_evidence_insert() returns trigger
language plpgsql security invoker set search_path = public, pg_temp as $$
declare v_entry public.cme_entries%rowtype; v_closed timestamptz;
begin
  perform pg_advisory_xact_lock(hashtextextended(new.owner_id::text, 23092026));
  select * into v_entry from public.cme_entries where id=new.entry_id and owner_id=new.owner_id;
  if not found then raise exception 'cme_evidence_entry_not_found'; end if;
  select closed_at into v_closed from public.cme_years where id=v_entry.year_id and owner_id=new.owner_id for update;
  if not found or v_closed is not null or v_entry.archived_at is not null then
    raise exception 'cme_evidence_entry_not_writable';
  end if;
  if (select count(*) from public.cme_evidence
      where owner_id=new.owner_id and entry_id=new.entry_id and removed_at is null) >= 20 then
    raise exception 'cme_evidence_limit';
  end if;
  return new;
end $$;

-- Evidence counts on the log count files still attached.
create or replace function public.cme_evidence_counts(p_owner_id uuid, p_year integer) returns jsonb
language sql stable security invoker set search_path = public, pg_temp as $$
  select coalesce(jsonb_object_agg(entry_id, evidence_count), '{}'::jsonb)
  from (
    select e.id as entry_id, count(a.id) as evidence_count
    from public.cme_entries e join public.cme_years y on y.id=e.year_id and y.owner_id=p_owner_id
    left join public.cme_evidence a on a.entry_id=e.id and a.owner_id=p_owner_id and a.removed_at is null
    where e.owner_id=p_owner_id and y.year=p_year group by e.id
  ) counts
$$;

create function public.cme_remove_evidence(p_owner_id uuid, p_evidence_id uuid, p_reason text)
returns public.cme_evidence
language plpgsql security invoker set search_path = public, pg_temp as $$
declare v_row public.cme_evidence%rowtype;
begin
  if p_reason is null or length(btrim(p_reason)) not between 3 and 500 then
    raise exception 'cme_evidence_removal_reason_invalid';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_owner_id::text, 23092026));
  update public.cme_evidence
     set removed_at = now(), removal_reason = btrim(p_reason), file_name = 'Removed file'
   where id = p_evidence_id and owner_id = p_owner_id and removed_at is null
  returning * into v_row;
  if not found then raise exception 'cme_evidence_not_found'; end if;
  return v_row;
end $$;
revoke execute on function public.cme_remove_evidence(uuid,uuid,text) from public, anon, authenticated;
grant execute on function public.cme_remove_evidence(uuid,uuid,text) to service_role;


-- Projection: 20260925064000_cme_year_close.sql
-- CME year close: an immutable snapshot, dated amendments with a reason, and a shortfall note.
--
-- Design: docs/cme/design/cme-design-decisions.md section 9 (owner decision 23 September 2026).
-- Closing does not lock the record irreversibly. It freezes a snapshot of the year as it stood,
-- and every later change to one of that year's activities is an explicit, dated amendment that
-- keeps the original beside the revision. `cme_years.closed_at` and `cme_years.shortfall_note`
-- already exist (20260920145148); until now nothing could set them.
--
-- Tenancy is the same as every other CME table: RLS on, no grant to anon/authenticated,
-- service_role only, owner predicate on every statement. Functions are security invoker.
set local lock_timeout = '5s';
set local statement_timeout = '30s';

create table public.cme_year_snapshots (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null,
  year_id uuid not null unique,
  closed_at timestamptz not null default now(),
  shortfall_note text check (shortfall_note is null or char_length(btrim(shortfall_note)) between 1 and 2000),
  -- Built by the database from the rows themselves at the moment of closing: the confirmed
  -- targets, every requirement and every active activity with its allocations.
  record jsonb not null,
  -- The application's reading of that record (requirement statuses and summaries), checked
  -- against the database's own total and activity count before it is accepted.
  evaluation jsonb not null,
  total_hours numeric(8, 2) not null,
  target_hours numeric(6, 2) not null,
  -- No direct reference to auth.users: removal follows the year row, so deleting an
  -- account cascades here only after the year itself is gone.
  constraint cme_year_snapshots_year_owner_fk foreign key (year_id, owner_id)
    references public.cme_years (id, owner_id) on delete cascade
);

create table public.cme_year_amendments (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null,
  year_id uuid not null,
  entry_id uuid not null,
  amended_at timestamptz not null default now(),
  reason text not null check (char_length(btrim(reason)) between 3 and 1000),
  before jsonb not null,
  after jsonb not null,
  constraint cme_year_amendments_year_owner_fk foreign key (year_id, owner_id)
    references public.cme_years (id, owner_id) on delete cascade,
  constraint cme_year_amendments_entry_owner_fk foreign key (entry_id, owner_id)
    references public.cme_entries (id, owner_id) on delete cascade
);
create index cme_year_amendments_owner_year_idx on public.cme_year_amendments (owner_id, year_id, amended_at);
create index cme_year_amendments_entry_idx on public.cme_year_amendments (entry_id, owner_id);

do $$
declare
  t text;
begin
  foreach t in array array['cme_year_snapshots', 'cme_year_amendments']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from public, anon, authenticated', t);
    -- Written once and never edited: no update or delete grant, even to the server.
    execute format('grant select, insert on table public.%I to service_role', t);
    execute format(
      'create policy "%s service role all" on public.%I for all to service_role using (true) with check (true)',
      t, t
    );
  end loop;
end
$$;

-- The snapshot and the amendment history are append-only. A delete is allowed only when the
-- year it belongs to is already gone (an account deletion cascading through cme_years).
create function public.cme_guard_close_record() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  if tg_op = 'UPDATE' then raise exception 'cme_record_immutable'; end if;
  if exists(select 1 from public.cme_years where id = old.year_id and owner_id = old.owner_id) then
    raise exception 'cme_record_immutable';
  end if;
  return old;
end $$;
create trigger cme_year_snapshots_immutable before update or delete on public.cme_year_snapshots
  for each row execute function public.cme_guard_close_record();
create trigger cme_year_amendments_immutable before update or delete on public.cme_year_amendments
  for each row execute function public.cme_guard_close_record();

-- A year is closed only through cme_close_year, which writes its snapshot first in the same
-- transaction; once closed, nothing on the row changes and closed_at can never be cleared.
create function public.cme_guard_year() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  if tg_op = 'UPDATE' and old.closed_at is not null then
    if new.closed_at is distinct from old.closed_at
      or new.shortfall_note is distinct from old.shortfall_note
      or new.total_hours is distinct from old.total_hours
      or new.confirmed_on is distinct from old.confirmed_on
      or new.confirmed_source is distinct from old.confirmed_source
      or new.year is distinct from old.year
      or new.owner_id is distinct from old.owner_id then
      raise exception 'cme_year_closed';
    end if;
    return new;
  end if;
  if new.closed_at is not null and not exists(
    select 1 from public.cme_year_snapshots
    where year_id = new.id and owner_id = new.owner_id and closed_at = new.closed_at
  ) then
    raise exception 'cme_year_close_requires_snapshot';
  end if;
  if new.closed_at is null and new.shortfall_note is not null then raise exception 'cme_invalid_request'; end if;
  return new;
end $$;
create trigger cme_year_close_guard before insert or update on public.cme_years
  for each row execute function public.cme_guard_year();

-- Requirements of a closed year are frozen. (cme_confirm_year already refuses a closed year;
-- this also covers any other writer.) A cascade from a deleted year finds no year and passes.
create function public.cme_guard_requirement() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  if tg_op <> 'INSERT' and exists(
    select 1 from public.cme_years where id = old.year_id and owner_id = old.owner_id and closed_at is not null
  ) then raise exception 'cme_year_closed'; end if;
  if tg_op <> 'DELETE' and exists(
    select 1 from public.cme_years where id = new.year_id and owner_id = new.owner_id and closed_at is not null
  ) then raise exception 'cme_year_closed'; end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;
create trigger cme_requirement_closed_year_guard before insert or update or delete on public.cme_requirements
  for each row execute function public.cme_guard_requirement();

-- True only while cme_amend_closed_entry is running for this entry: the amendment row is
-- written first, and now() is the transaction's start time, so a matching row proves the
-- change being made is the one that amendment records.
create function public.cme_entry_amendment_in_progress(p_entry_id uuid, p_owner_id uuid) returns boolean
language sql stable security invoker set search_path = public, pg_catalog, pg_temp as $$
  select exists(
    select 1 from public.cme_year_amendments
    where entry_id = p_entry_id and owner_id = p_owner_id and amended_at = now()
  )
$$;

-- Replaces 20260922163920's guard: identical, except that an update recorded as an amendment
-- in the same transaction may change an activity in a closed year. It still may not move the
-- activity to another year, and a closed-year activity still cannot be deleted.
create or replace function public.cme_guard_entry() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_year public.cme_years; v_amending boolean := false;
begin
  if tg_op = 'UPDATE' then
    v_amending := new.year_id = old.year_id and public.cme_entry_amendment_in_progress(old.id, old.owner_id);
  end if;
  if tg_op <> 'INSERT' then
    select * into v_year from public.cme_years where id=old.year_id and owner_id=old.owner_id for update;
    if v_year.closed_at is not null and not v_amending then raise exception 'cme_year_closed'; end if;
  end if;
  if tg_op='DELETE' then return old; end if;
  select * into v_year from public.cme_years where id=new.year_id and owner_id=new.owner_id for update;
  if not found or extract(year from new.activity_date)<>v_year.year then raise exception 'cme_invalid_request'; end if;
  if v_year.closed_at is not null and not v_amending then raise exception 'cme_year_closed'; end if;
  if new.document_id is not null and not exists(select 1 from public.documents where id=new.document_id and owner_id=new.owner_id) then raise exception 'cme_invalid_link'; end if;
  return new;
end $$;

-- Allocations had no closed-year guard of their own; every writer went through cme_save_entry.
create function public.cme_guard_allocation() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_entry_id uuid; v_owner_id uuid;
begin
  if tg_op = 'DELETE' then v_entry_id := old.entry_id; v_owner_id := old.owner_id;
  else v_entry_id := new.entry_id; v_owner_id := new.owner_id; end if;
  if exists(
    select 1 from public.cme_entries e join public.cme_years y on y.id = e.year_id and y.owner_id = e.owner_id
    where e.id = v_entry_id and e.owner_id = v_owner_id and y.closed_at is not null
  ) and not public.cme_entry_amendment_in_progress(v_entry_id, v_owner_id) then
    raise exception 'cme_year_closed';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;
create trigger cme_allocation_closed_year_guard before insert or update or delete on public.cme_allocations
  for each row execute function public.cme_guard_allocation();

-- Close one CPD year. The record is read from the rows under the owner lock; the caller's
-- evaluation must agree with it on total hours and activity count, or nothing is written.
create function public.cme_close_year(p_owner_id uuid, p_year_id uuid, p_evaluation jsonb, p_shortfall_note text default null)
returns jsonb
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare
  v_year public.cme_years; v_snapshot public.cme_year_snapshots; v_record jsonb;
  v_total numeric; v_count integer; v_note text := nullif(btrim(coalesce(p_shortfall_note, '')), '');
begin
  if p_owner_id is null or p_year_id is null or jsonb_typeof(p_evaluation) is distinct from 'object' then
    raise exception 'cme_invalid_request';
  end if;
  if v_note is not null and char_length(v_note) > 2000 then raise exception 'cme_invalid_request'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_owner_id::text, 23092026));
  select * into v_year from public.cme_years where owner_id=p_owner_id and id=p_year_id for update;
  if not found then raise exception 'cme_year_not_confirmed'; end if;
  if v_year.closed_at is not null then raise exception 'cme_year_closed'; end if;

  select count(*), coalesce(sum(a.hours), 0) into v_count, v_total
  from public.cme_entries e
  left join lateral (
    select sum(hours) as hours from public.cme_allocations where owner_id=p_owner_id and entry_id=e.id
  ) a on true
  where e.owner_id=p_owner_id and e.year_id=p_year_id and e.archived_at is null;
  if round(v_total, 2) is distinct from round((p_evaluation->>'totalHours')::numeric, 2)
    or v_count is distinct from (p_evaluation->>'entryCount')::integer then
    raise exception 'cme_close_conflict';
  end if;

  v_record := jsonb_build_object(
    'year', v_year.year,
    'totalHours', v_year.total_hours,
    'confirmedOn', v_year.confirmed_on,
    'confirmedSource', v_year.confirmed_source,
    'requirements', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', r.id, 'label', r.label, 'source', r.source, 'spec', r.spec, 'completedOn', r.completed_on
      ) order by r.sort_order, r.id), '[]'::jsonb)
      from public.cme_requirements r where r.owner_id=p_owner_id and r.year_id=p_year_id
    ),
    'entries', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', e.id, 'date', e.activity_date, 'title', e.title, 'reflection', e.reflection,
        'costCents', e.cost_cents, 'routineId', e.routine_id, 'documentId', e.document_id,
        'sourceUrl', e.source_url, 'buckets', to_jsonb(e.buckets),
        'formalPeerReviewHours', e.formal_peer_review_hours,
        'allocations', (
          select coalesce(jsonb_agg(jsonb_build_object('category', a.category, 'hours', a.hours) order by a.category), '[]'::jsonb)
          from public.cme_allocations a where a.owner_id=p_owner_id and a.entry_id=e.id
        )
      ) order by e.activity_date, e.id), '[]'::jsonb)
      from public.cme_entries e where e.owner_id=p_owner_id and e.year_id=p_year_id and e.archived_at is null
    )
  );

  insert into public.cme_year_snapshots(owner_id, year_id, shortfall_note, record, evaluation, total_hours, target_hours)
  values (p_owner_id, p_year_id, v_note, v_record, p_evaluation, round(v_total, 2), v_year.total_hours)
  returning * into v_snapshot;
  update public.cme_years set closed_at = v_snapshot.closed_at, shortfall_note = v_note
  where owner_id=p_owner_id and id=p_year_id;
  return to_jsonb(v_snapshot);
end $$;

-- Amend one activity in a closed year. The previous version and the reason are recorded
-- first; the snapshot is never touched. Same validation as cme_save_entry, and the activity
-- stays in its year.
create function public.cme_amend_closed_entry(p_owner_id uuid, p_entry_id uuid, p_entry jsonb, p_reason text)
returns jsonb
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare
  v_year public.cme_years; v_existing public.cme_entries; v_saved public.cme_entries; v_routine public.cme_routines;
  v_alloc jsonb; v_review numeric; v_total numeric; v_count integer; v_before jsonb;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if p_owner_id is null or p_entry_id is null or jsonb_typeof(p_entry) is distinct from 'object' then
    raise exception 'cme_invalid_request';
  end if;
  if char_length(v_reason) not between 3 and 1000 then raise exception 'cme_amendment_reason_invalid'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_owner_id::text, 23092026));
  select * into v_existing from public.cme_entries where owner_id=p_owner_id and id=p_entry_id for update;
  if not found then raise exception 'cme_entry_not_found'; end if;
  if v_existing.archived_at is not null then raise exception 'cme_entry_archived'; end if;
  select * into v_year from public.cme_years where owner_id=p_owner_id and id=v_existing.year_id for update;
  if not found then raise exception 'cme_year_not_confirmed'; end if;
  if v_year.closed_at is null then raise exception 'cme_year_open'; end if;
  if extract(year from (p_entry->>'date')::date) <> v_year.year then raise exception 'cme_invalid_request'; end if;
  if jsonb_typeof(p_entry->'allocations') is distinct from 'array' then raise exception 'cme_invalid_request'; end if;
  select count(*),coalesce(sum((a->>'hours')::numeric),0),coalesce(sum((a->>'hours')::numeric) filter(where a->>'category'='reviewing'),0)
    into v_count,v_total,v_review from jsonb_array_elements(p_entry->'allocations') a;
  if v_count not between 1 and 3 or v_total > 24 or coalesce((p_entry->>'formalPeerReviewHours')::numeric,0) not between 0 and v_review then raise exception 'cme_invalid_request'; end if;
  if p_entry->>'documentId' is not null and not exists(select 1 from public.documents where owner_id=p_owner_id and id=(p_entry->>'documentId')::uuid) then raise exception 'cme_invalid_link'; end if;
  if p_entry->>'routineId' is not null then
    select * into v_routine from public.cme_routines where owner_id=p_owner_id and id=(p_entry->>'routineId')::uuid;
    if not found then raise exception 'cme_invalid_link'; end if;
  end if;

  v_before := jsonb_build_object(
    'date', v_existing.activity_date, 'title', v_existing.title, 'reflection', v_existing.reflection,
    'costCents', v_existing.cost_cents, 'routineId', v_existing.routine_id, 'documentId', v_existing.document_id,
    'sourceUrl', v_existing.source_url, 'buckets', to_jsonb(v_existing.buckets),
    'formalPeerReviewHours', v_existing.formal_peer_review_hours,
    'allocations', (
      select coalesce(jsonb_agg(jsonb_build_object('category', category, 'hours', hours) order by category), '[]'::jsonb)
      from public.cme_allocations where owner_id=p_owner_id and entry_id=p_entry_id
    )
  );
  insert into public.cme_year_amendments(owner_id, year_id, entry_id, reason, before, after)
  values (
    p_owner_id, v_year.id, p_entry_id, v_reason, v_before,
    jsonb_build_object(
      'date', p_entry->'date', 'title', p_entry->'title', 'reflection', p_entry->'reflection',
      'costCents', p_entry->'costCents', 'routineId', p_entry->'routineId', 'documentId', p_entry->'documentId',
      'sourceUrl', p_entry->'sourceUrl', 'buckets', p_entry->'buckets',
      'formalPeerReviewHours', coalesce(p_entry->'formalPeerReviewHours', '0'::jsonb),
      'allocations', p_entry->'allocations'
    )
  );

  update public.cme_entries set activity_date=(p_entry->>'date')::date,title=p_entry->>'title',reflection=p_entry->>'reflection',cost_cents=(p_entry->>'costCents')::integer,routine_id=(p_entry->>'routineId')::uuid,document_id=(p_entry->>'documentId')::uuid,buckets=array(select jsonb_array_elements_text(p_entry->'buckets')),formal_peer_review_hours=coalesce((p_entry->>'formalPeerReviewHours')::numeric,0),source_url=p_entry->>'sourceUrl'
  where owner_id=p_owner_id and id=p_entry_id returning * into v_saved;
  delete from public.cme_allocations where owner_id=p_owner_id and entry_id=p_entry_id;
  for v_alloc in select value from jsonb_array_elements(p_entry->'allocations') loop
    insert into public.cme_allocations(owner_id,entry_id,category,hours) values(p_owner_id,p_entry_id,v_alloc->>'category',(v_alloc->>'hours')::numeric);
  end loop;
  return to_jsonb(v_saved)||jsonb_build_object('cme_allocations',p_entry->'allocations');
end $$;

revoke all on function
  public.cme_guard_close_record(), public.cme_guard_year(), public.cme_guard_requirement(),
  public.cme_entry_amendment_in_progress(uuid, uuid), public.cme_guard_allocation(),
  public.cme_close_year(uuid, uuid, jsonb, text), public.cme_amend_closed_entry(uuid, uuid, jsonb, text)
  from public, anon, authenticated;
grant execute on function
  public.cme_guard_close_record(), public.cme_guard_year(), public.cme_guard_requirement(),
  public.cme_entry_amendment_in_progress(uuid, uuid), public.cme_guard_allocation(),
  public.cme_close_year(uuid, uuid, jsonb, text), public.cme_amend_closed_entry(uuid, uuid, jsonb, text)
  to service_role;

-- 20260925102600_cme_plan_goals.sql
-- CME development-plan goals, and which goal each activity served.
--
-- Two new tables, nothing changed in an existing one: `cme_entries` and `cme_save_entry` are
-- untouched, so every existing write path and guard behaves exactly as before. The link from an
-- activity to a goal lives in its own table and is set by its own function.
--
-- Same tenancy as every other CME table: RLS on, no grant to anon/authenticated, service_role
-- only, owner predicate in application code. Both are frozen with the year once it is closed.

create table public.cme_plan_goals (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  year_id uuid not null,
  goal text not null check (char_length(btrim(goal)) between 3 and 300),
  sort_order smallint not null default 0 check (sort_order between 0 and 9),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint cme_plan_goals_id_owner_key unique (id, owner_id),
  constraint cme_plan_goals_year_owner_fk foreign key (year_id, owner_id)
    references public.cme_years (id, owner_id) on delete cascade
);
create index cme_plan_goals_owner_year_idx on public.cme_plan_goals (owner_id, year_id, sort_order);

create table public.cme_entry_goals (
  entry_id uuid primary key,
  owner_id uuid not null references auth.users (id) on delete cascade,
  goal_id uuid not null,
  created_at timestamptz not null default now(),
  constraint cme_entry_goals_entry_owner_fk foreign key (entry_id, owner_id)
    references public.cme_entries (id, owner_id) on delete cascade,
  constraint cme_entry_goals_goal_owner_fk foreign key (goal_id, owner_id)
    references public.cme_plan_goals (id, owner_id) on delete cascade
);
create index cme_entry_goals_goal_idx on public.cme_entry_goals (goal_id);
create index cme_entry_goals_owner_idx on public.cme_entry_goals (owner_id);

create trigger cme_plan_goals_updated_at before update on public.cme_plan_goals
  for each row execute function public.set_updated_at();

do $$
declare
  t text;
begin
  foreach t in array array['cme_plan_goals', 'cme_entry_goals']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from public, anon, authenticated', t);
    execute format('grant select, insert, update, delete on table public.%I to service_role', t);
    execute format(
      'create policy "%s service role all" on public.%I for all to service_role using (true) with check (true)',
      t, t
    );
  end loop;
end
$$;

-- Goals of a closed year are frozen, like its requirements. A cascade from a deleted year
-- finds no year and passes.
create function public.cme_guard_plan_goal() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  if tg_op <> 'INSERT' and exists(
    select 1 from public.cme_years where id = old.year_id and owner_id = old.owner_id and closed_at is not null
  ) then raise exception 'cme_year_closed'; end if;
  if tg_op <> 'DELETE' and exists(
    select 1 from public.cme_years where id = new.year_id and owner_id = new.owner_id and closed_at is not null
  ) then raise exception 'cme_year_closed'; end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;
revoke all on function public.cme_guard_plan_goal() from public, anon, authenticated;
grant execute on function public.cme_guard_plan_goal() to service_role;
create trigger cme_plan_goal_closed_year_guard before insert or update or delete on public.cme_plan_goals
  for each row execute function public.cme_guard_plan_goal();

-- An activity's goal link is frozen with the activity's year, and the goal must belong to the
-- same owner and the same year as the activity.
create function public.cme_guard_entry_goal() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_entry_id uuid; v_owner_id uuid;
begin
  if tg_op = 'DELETE' then v_entry_id := old.entry_id; v_owner_id := old.owner_id;
  else v_entry_id := new.entry_id; v_owner_id := new.owner_id; end if;
  if exists(
    select 1 from public.cme_entries e join public.cme_years y on y.id = e.year_id and y.owner_id = e.owner_id
    where e.id = v_entry_id and e.owner_id = v_owner_id and y.closed_at is not null
  ) then raise exception 'cme_year_closed'; end if;
  if tg_op = 'DELETE' then return old; end if;
  if not exists(
    select 1 from public.cme_entries e join public.cme_plan_goals g on g.year_id = e.year_id and g.owner_id = e.owner_id
    where e.id = new.entry_id and e.owner_id = new.owner_id and g.id = new.goal_id
  ) then raise exception 'cme_invalid_link'; end if;
  return new;
end $$;
revoke all on function public.cme_guard_entry_goal() from public, anon, authenticated;
grant execute on function public.cme_guard_entry_goal() to service_role;
create trigger cme_entry_goal_guard before insert or update or delete on public.cme_entry_goals
  for each row execute function public.cme_guard_entry_goal();

-- Replace one year's goals in one step. Goals sent with an id are kept (their links survive);
-- goals sent without one are added; goals not sent are removed, and with them their links.
create function public.cme_save_plan_goals(p_owner_id uuid, p_year_id uuid, p_goals jsonb) returns jsonb
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_year public.cme_years; v_goal jsonb; v_index integer := 0; v_keep uuid[] := '{}'; v_id uuid;
begin
  if p_owner_id is null or p_year_id is null or jsonb_typeof(p_goals) is distinct from 'array'
    or jsonb_array_length(p_goals) > 10 then raise exception 'cme_invalid_request'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_owner_id::text, 23092026));
  select * into v_year from public.cme_years where owner_id = p_owner_id and id = p_year_id for update;
  if not found then raise exception 'cme_year_not_confirmed'; end if;
  if v_year.closed_at is not null then raise exception 'cme_year_closed'; end if;
  for v_goal in select value from jsonb_array_elements(p_goals) loop
    if jsonb_typeof(v_goal->'goal') is distinct from 'string' then raise exception 'cme_invalid_request'; end if;
    if v_goal ? 'id' and v_goal->>'id' is not null then
      update public.cme_plan_goals set goal = btrim(v_goal->>'goal'), sort_order = v_index
      where owner_id = p_owner_id and year_id = p_year_id and id = (v_goal->>'id')::uuid
      returning id into v_id;
      if not found then raise exception 'cme_invalid_request'; end if;
    else
      insert into public.cme_plan_goals (owner_id, year_id, goal, sort_order)
      values (p_owner_id, p_year_id, btrim(v_goal->>'goal'), v_index) returning id into v_id;
    end if;
    v_keep := v_keep || v_id;
    v_index := v_index + 1;
  end loop;
  delete from public.cme_plan_goals where owner_id = p_owner_id and year_id = p_year_id and not (id = any(v_keep));
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', id, 'goal', goal, 'sortOrder', sort_order) order by sort_order)
    from public.cme_plan_goals where owner_id = p_owner_id and year_id = p_year_id
  ), '[]'::jsonb);
end $$;
revoke all on function public.cme_save_plan_goals(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.cme_save_plan_goals(uuid, uuid, jsonb) to service_role;

-- Set, change or clear which goal one activity served. An archived activity is frozen, as it is
-- for every other CME write, so its link is refused until it is restored.
create function public.cme_set_entry_goal(p_owner_id uuid, p_entry_id uuid, p_goal_id uuid) returns jsonb
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_archived_at timestamptz;
begin
  if p_owner_id is null or p_entry_id is null then raise exception 'cme_invalid_request'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_owner_id::text, 23092026));
  select archived_at into v_archived_at from public.cme_entries where owner_id = p_owner_id and id = p_entry_id;
  if not found then raise exception 'cme_entry_not_found'; end if;
  if v_archived_at is not null then raise exception 'cme_entry_archived'; end if;
  delete from public.cme_entry_goals where owner_id = p_owner_id and entry_id = p_entry_id;
  if p_goal_id is not null then
    insert into public.cme_entry_goals (entry_id, owner_id, goal_id) values (p_entry_id, p_owner_id, p_goal_id);
  end if;
  return jsonb_build_object('entryId', p_entry_id, 'goalId', p_goal_id);
end $$;
revoke all on function public.cme_set_entry_goal(uuid, uuid, uuid) from public, anon, authenticated;
grant execute on function public.cme_set_entry_goal(uuid, uuid, uuid) to service_role;

-- 20260925160000_calendar_feed_tokens.sql
-- Private calendar subscription links (CME deadlines and routines, On Call teaching).
--
-- One new table and three functions; nothing existing changes. A link is a long random
-- token held only by its owner: this table stores a SHA-256 of it, never the token, so a
-- database reader cannot rebuild anyone's link. One live link per owner; making a new one
-- replaces the old, and deleting the row turns the link off at once.
--
-- Same tenancy as the CME tables: RLS on, no grant to anon/authenticated, service_role only.

create table public.calendar_feed_tokens (
  owner_id uuid primary key references auth.users (id) on delete cascade,
  token_hash text not null check (token_hash ~ '^[0-9a-f]{64}$'),
  created_at timestamptz not null default now(),
  last_used_at timestamptz,
  constraint calendar_feed_tokens_token_hash_key unique (token_hash)
);

alter table public.calendar_feed_tokens enable row level security;
revoke all on table public.calendar_feed_tokens from public, anon, authenticated;
grant select, insert, update, delete on table public.calendar_feed_tokens to service_role;
create policy "calendar_feed_tokens service role all" on public.calendar_feed_tokens
  for all to service_role using (true) with check (true);

-- Make (or replace) the owner's one link. The caller passes only the hash.
create function public.calendar_feed_rotate(p_owner_id uuid, p_token_hash text) returns void
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  if p_owner_id is null or p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'calendar_feed_invalid_request';
  end if;
  insert into public.calendar_feed_tokens (owner_id, token_hash)
  values (p_owner_id, p_token_hash)
  on conflict (owner_id) do update
    set token_hash = excluded.token_hash, created_at = now(), last_used_at = null;
end $$;
revoke all on function public.calendar_feed_rotate(uuid, text) from public, anon, authenticated;
grant execute on function public.calendar_feed_rotate(uuid, text) to service_role;

-- Turn the owner's link off.
create function public.calendar_feed_revoke(p_owner_id uuid) returns void
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  if p_owner_id is null then raise exception 'calendar_feed_invalid_request'; end if;
  delete from public.calendar_feed_tokens where owner_id = p_owner_id;
end $$;
revoke all on function public.calendar_feed_revoke(uuid) from public, anon, authenticated;
grant execute on function public.calendar_feed_revoke(uuid) to service_role;

-- Resolve a presented link to its owner, recording when it was last read. Returns null for
-- an unknown or turned-off link, so the two are indistinguishable to the caller.
create function public.calendar_feed_owner(p_token_hash text) returns uuid
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_owner uuid;
begin
  if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then return null; end if;
  update public.calendar_feed_tokens set last_used_at = now()
  where token_hash = p_token_hash
  returning owner_id into v_owner;
  return v_owner;
end $$;
revoke all on function public.calendar_feed_owner(text) from public, anon, authenticated;
grant execute on function public.calendar_feed_owner(text) to service_role;

-- 20260926051500_on_call_shifts.sql
-- My shifts: a doctor's own roster, private to them.
--
-- Two new tables and one function; nothing existing changes. On Call entries are shared
-- between accounts unless marked personal, so a roster must not live there: these rows are
-- only ever read or written for their owner. Only the parsed fields of an imported roster
-- are kept (start, end, title, location, the calendar's own ID); the file itself is never
-- uploaded.
--
-- Same tenancy as the CME and calendar-feed tables: RLS on, no grant to anon/authenticated,
-- service_role only. Every API query filters by owner_id.

create table public.on_call_shifts (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  title text not null check (btrim(title) <> '' and char_length(title) <= 200),
  location text check (location is null or char_length(location) <= 200),
  source_uid text check (source_uid is null or char_length(source_uid) <= 300),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint on_call_shifts_ends_after_start check (ends_at > starts_at),
  constraint on_call_shifts_max_length check (ends_at - starts_at <= interval '36 hours')
);

create index on_call_shifts_owner_starts_idx on public.on_call_shifts (owner_id, starts_at);

create trigger on_call_shifts_updated_at
  before update on public.on_call_shifts
  for each row execute function public.set_updated_at();

alter table public.on_call_shifts enable row level security;
revoke all on table public.on_call_shifts from public, anon, authenticated;
grant select, insert, update, delete on table public.on_call_shifts to service_role;
create policy "on call shifts service role all" on public.on_call_shifts
  for all to service_role using (true) with check (true);

-- One row per roster import: what the file covered and what it changed, so the owner can
-- see "2 added, 1 moved, 1 removed" until they dismiss it.
create table public.on_call_shift_imports (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  imported_at timestamptz not null default now(),
  format text not null check (format in ('ics', 'csv')),
  window_start date not null,
  window_end date not null,
  added integer not null default 0 check (added >= 0),
  changed integer not null default 0 check (changed >= 0),
  removed integer not null default 0 check (removed >= 0),
  changes jsonb not null default '[]'::jsonb check (jsonb_typeof(changes) = 'array' and jsonb_array_length(changes) <= 200),
  seen_at timestamptz,
  constraint on_call_shift_imports_window check (window_end >= window_start)
);

create index on_call_shift_imports_owner_imported_idx on public.on_call_shift_imports (owner_id, imported_at desc);

alter table public.on_call_shift_imports enable row level security;
revoke all on table public.on_call_shift_imports from public, anon, authenticated;
grant select, insert, update, delete on table public.on_call_shift_imports to service_role;
create policy "on call shift imports service role all" on public.on_call_shift_imports
  for all to service_role using (true) with check (true);

-- Replace the owner's shifts inside the imported window and record the import, in one
-- transaction, so a failed save never leaves half a roster. Shifts outside the window stay.
-- Keeps the ten most recent imports per owner.
create function public.on_call_shifts_replace(
  p_owner_id uuid,
  p_window_start date,
  p_window_end date,
  p_format text,
  p_shifts jsonb,
  p_changes jsonb,
  p_added integer,
  p_changed integer,
  p_removed integer
) returns uuid
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_import uuid;
begin
  if p_owner_id is null or p_window_start is null or p_window_end is null
    or p_window_end < p_window_start
    or p_shifts is null or jsonb_typeof(p_shifts) <> 'array' or jsonb_array_length(p_shifts) > 1000
    or p_changes is null or jsonb_typeof(p_changes) <> 'array' then
    raise exception 'on_call_shifts_invalid_request';
  end if;

  delete from public.on_call_shifts
  where owner_id = p_owner_id
    and (starts_at at time zone 'Australia/Perth')::date between p_window_start and p_window_end;

  insert into public.on_call_shifts (owner_id, starts_at, ends_at, title, location, source_uid)
  select p_owner_id,
         (shift ->> 'startsAt')::timestamptz,
         (shift ->> 'endsAt')::timestamptz,
         shift ->> 'title',
         nullif(shift ->> 'location', ''),
         nullif(shift ->> 'sourceUid', '')
  from jsonb_array_elements(p_shifts) as shift;

  if (select count(*) from public.on_call_shifts where owner_id = p_owner_id) > 2000 then
    raise exception 'on_call_shifts_limit';
  end if;

  insert into public.on_call_shift_imports
    (owner_id, format, window_start, window_end, added, changed, removed, changes)
  values
    (p_owner_id, p_format, p_window_start, p_window_end, p_added, p_changed, p_removed, p_changes)
  returning id into v_import;

  delete from public.on_call_shift_imports
  where owner_id = p_owner_id
    and id not in (
      select id from public.on_call_shift_imports
      where owner_id = p_owner_id
      order by imported_at desc, id desc
      limit 10
    );

  return v_import;
end $$;
revoke all on function public.on_call_shifts_replace(uuid, date, date, text, jsonb, jsonb, integer, integer, integer)
  from public, anon, authenticated;
grant execute on function public.on_call_shifts_replace(uuid, date, date, text, jsonb, jsonb, integer, integer, integer)
  to service_role;
-- 20260926060000_cme_cpd_records.sql
-- CPD records: trainee timeline, missed teaching, and saved drafts.
--
-- Four new tables, nothing changed in an existing one. None is tied to a CPD year, and none is
-- read by the requirement evaluation, year close, the export or the annual summary: nothing
-- here can add hours or change a requirement status. A missed session earns no credit; its
-- replacement is an ordinary activity in `cme_entries`, logged through the normal save path.
--
-- Same tenancy as every other CME table: RLS on, no grant to anon/authenticated, service_role
-- only, owner predicate in application code.

-- A trainee's own record of their stages, rotations and breaks. Not the college's record.
create table public.cme_training_periods (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  kind text not null check (kind in ('stage', 'rotation', 'break')),
  label text not null check (char_length(btrim(label)) between 1 and 120),
  starts_on date not null,
  ends_on date check (ends_on is null or ends_on >= starts_on),
  fte numeric(3, 2) not null default 1 check (fte between 0 and 1),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint cme_training_periods_id_owner_key unique (id, owner_id),
  constraint cme_training_periods_fte_kind_check check (
    (kind = 'break' and fte = 0) or (kind = 'rotation' and fte > 0) or kind = 'stage'
  )
);
create index cme_training_periods_owner_idx on public.cme_training_periods (owner_id, starts_on);

create table public.cme_training_milestones (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  label text not null check (char_length(btrim(label)) between 3 and 200),
  due_kind text not null check (due_kind in ('fte-months', 'date')),
  due_fte_months numeric(5, 2) check (due_fte_months is null or due_fte_months between 0 and 600),
  due_on date,
  completed_on date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint cme_training_milestones_id_owner_key unique (id, owner_id),
  constraint cme_training_milestones_due_check check (
    (due_kind = 'fte-months' and due_fte_months is not null and due_on is null)
    or (due_kind = 'date' and due_on is not null and due_fte_months is null)
  )
);
create index cme_training_milestones_owner_idx on public.cme_training_milestones (owner_id);

-- A teaching or supervision session lost to clinical work. It never counts toward hours; the
-- session that replaced it is an ordinary activity linked here. Deleting that activity clears
-- only the link, never the record of the missed session.
create table public.cme_missed_sessions (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  occurred_on date not null,
  kind text not null check (kind in ('teaching', 'supervision')),
  title text not null check (char_length(btrim(title)) between 3 and 200),
  minutes_lost integer not null check (minutes_lost between 1 and 600),
  reason text check (reason is null or char_length(reason) <= 200),
  replacement_entry_id uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint cme_missed_sessions_id_owner_key unique (id, owner_id),
  constraint cme_missed_sessions_replacement_owner_fk foreign key (replacement_entry_id, owner_id)
    references public.cme_entries (id, owner_id) on delete set null (replacement_entry_id)
);
create index cme_missed_sessions_owner_idx on public.cme_missed_sessions (owner_id, occurred_on desc);
create index cme_missed_sessions_replacement_idx on public.cme_missed_sessions (replacement_entry_id)
  where replacement_entry_id is not null;

-- A half-finished activity saved to the account. It is only the form's own fields; it never
-- counts toward hours, and "waiting on" someone never turns into approved by itself.
create table public.cme_entry_drafts (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  payload jsonb not null check (jsonb_typeof(payload) = 'object' and octet_length(payload::text) <= 16384),
  waiting_on text check (waiting_on is null or waiting_on in ('supervisor', 'workforce')),
  waiting_note text check (waiting_note is null or char_length(waiting_note) <= 200),
  follow_up_on date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint cme_entry_drafts_id_owner_key unique (id, owner_id)
);
create index cme_entry_drafts_owner_idx on public.cme_entry_drafts (owner_id, updated_at desc);

do $$
declare
  t text;
begin
  foreach t in array array['cme_training_periods', 'cme_training_milestones', 'cme_missed_sessions', 'cme_entry_drafts']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from public, anon, authenticated', t);
    execute format('grant select, insert, update, delete on table public.%I to service_role', t);
    execute format(
      'create policy "%s service role all" on public.%I for all to service_role using (true) with check (true)',
      t, t
    );
    execute format(
      'create trigger %I before update on public.%I for each row execute function public.set_updated_at()',
      t || '_updated_at', t
    );
  end loop;
end
$$;

-- 20260926225209_roster_shared_services_hardening.sql
-- Shared team system hardening: file 1 of the combined Roster DB PR (shared-db-contract.md v6).
--
-- MERGING THIS PR APPLIES IT TO THE LIVE CLINICAL DATABASE WITHIN SECONDS. Josh merges it himself.
--
-- What this file does, and nothing else:
--   1. on_call_services gains verified_at / verified_by / is_demo. Only a platform path sets them
--      (on_call_service_set_verified below, service_role only). The command RPC never does.
--   2. on_call_service_invitations gains invited_email, stored lower-case and trimmed.
--   3. on_call_service_members gains display_name, shared by every mode.
--   4. on_call_service_member_events: one audit row per join, revoke, rejoin and role change.
--   5. service_member_active(): the one permission helper every mode's command RPC calls first.
-- It never touches on_call_service_command: On Call's file (position 2) is its only replacement,
-- and it adds issued_via_mode. Nothing here reads auth.users.

-- 1. Verified and demo flags. Health-service features switch on only when
--    verified_at is not null or is_demo.
alter table public.on_call_services
  add column verified_at timestamptz,
  add column verified_by uuid references auth.users (id) on delete set null,
  add column is_demo boolean not null default false;

-- 2. Invitations are tied to the invited email. Rows made before this file stay null and
--    expire within 7 days anyway; On Call's command requires the email on every new invite.
alter table public.on_call_service_invitations
  add column invited_email text,
  add constraint on_call_service_invitations_invited_email_normalised check (
    invited_email is null
    or (invited_email = lower(btrim(invited_email)) and char_length(invited_email) between 3 and 320)
  );

-- 3. The name colleagues see, set by the member or a service admin.
alter table public.on_call_service_members
  add column display_name text,
  add constraint on_call_service_members_display_name_length check (
    display_name is null or char_length(btrim(display_name)) between 1 and 80
  );

-- 4. Membership audit. Ids set null on account deletion so "delete my data" still works.
--    Rows older than 12 months are purged by roster_retention_purge() (file 3).
create table public.on_call_service_member_events (
  id bigint generated always as identity primary key,
  service_id uuid not null references public.on_call_services (id) on delete cascade,
  user_id uuid references auth.users (id) on delete set null,
  event text not null check (event in ('joined', 'revoked', 'rejoined', 'role_changed')),
  mode text check (mode is null or mode in ('roster', 'teaching', 'admin')),
  actor_id uuid references auth.users (id) on delete set null,
  at timestamptz not null default now()
);
create index on_call_service_member_events_service_at_idx on public.on_call_service_member_events (service_id, at desc);
create index on_call_service_member_events_user_idx on public.on_call_service_member_events (user_id) where user_id is not null;
create index on_call_service_member_events_at_idx on public.on_call_service_member_events (at);

alter table public.on_call_service_member_events enable row level security;
revoke all on table public.on_call_service_member_events from public, anon, authenticated;
grant select, insert, update, delete on table public.on_call_service_member_events to service_role;

-- 5. The shared permission helper. Each mode's command RPC calls it first, then checks its
--    own role table with revoked_at is null.
create function public.service_member_active(p_service_id uuid, p_user_id uuid)
returns boolean
language sql stable security invoker
set search_path = public, pg_catalog, pg_temp as $$
  select exists (
    select 1 from public.on_call_service_members
    where service_id = p_service_id and user_id = p_user_id and revoked_at is null
  )
$$;
revoke all on function public.service_member_active(uuid, uuid) from public, anon, authenticated;
grant execute on function public.service_member_active(uuid, uuid) to service_role;

-- The platform path for the verified and demo flags: Josh's owner panel button, service_role only.
-- Takes the service row lock so it orders with every command that reads the flags.
create function public.on_call_service_set_verified(
  p_service_id uuid,
  p_actor_id uuid,
  p_verified boolean,
  p_is_demo boolean
) returns jsonb
language plpgsql security invoker
set search_path = public, pg_catalog, pg_temp as $$
declare v_service public.on_call_services%rowtype;
begin
  if p_service_id is null or p_actor_id is null or p_verified is null or p_is_demo is null then
    raise exception 'service_invalid_request';
  end if;
  select * into v_service from public.on_call_services where id = p_service_id for update;
  if not found then raise exception 'service_not_found'; end if;
  update public.on_call_services
     set verified_at = case when p_verified then coalesce(v_service.verified_at, now()) else null end,
         verified_by = case when p_verified then coalesce(v_service.verified_by, p_actor_id) else null end,
         is_demo = p_is_demo
   where id = p_service_id
  returning * into v_service;
  return jsonb_build_object('serviceId', v_service.id, 'verifiedAt', v_service.verified_at, 'isDemo', v_service.is_demo);
end $$;
revoke all on function public.on_call_service_set_verified(uuid, uuid, boolean, boolean) from public, anon, authenticated;
grant execute on function public.on_call_service_set_verified(uuid, uuid, boolean, boolean) to service_role;

-- 20260926225309_on_call_service_items.sql
-- =====================================================================================
-- On Call's service items: file 2 of the combined Roster DB PR.
-- Contract slot #2, `on_call_service_items` (shared-db-contract.md v3, "Rulings on On
-- Call's draft"). Order: 1 roster_shared_services_hardening, 2 THIS FILE, 3 roster_mode,
-- 4 admin_mode, 5 teaching_mode. The Roster coordinator stamps the filename at assembly.
-- This file relies only on file #1:
--   service_member_active(), on_call_services.verified_at / is_demo (unused here),
--   on_call_service_invitations.invited_email, on_call_service_members.display_name,
--   on_call_service_member_events.
-- It calls roster_can_invite() / teaching_can_invite() from files #3 and #5 only at run
-- time, inside a guarded CASE, so it does not depend on them existing yet.
-- Merging the combined PR applies this to the live clinical database within seconds.
-- Replayed from scratch with files 1-5 and tests/sql/roster-behaviour.sql before the PR
-- opened; CI's migration replay runs the whole chain again.
--
-- THE ONLY REPLACEMENT OF on_call_service_command (contract ruling 1). It carries every
-- command-level rule in the contract, each marked [contract §n] or [ruling n]: email
-- binding, audit rows, caps, invite rights, mode-manager invites, display name, locking.
-- No later file may replace this function; a mode needing new actions adds its own.
-- Kept unchanged: the join fix (already-member check before the invite is consumed),
-- every existing content-key and section check, the security-invoker model, and the
-- revoke/grant lines at the end.
--
-- WHAT THIS DOES
--   A. Handbook sections `playbook` and `cover`. Both are forced to kind clinical|legal,
--      so the existing rules apply: at least one https source, and publish goes to
--      pending_review for a second-person clinical reviewer. New content keys:
--        steps  (playbook only, required): [{order, whoToCall, when, phone?, hours?, waitMinutes?}], the
--               exact shape of entry-model.ts playbookDetails.escalationSteps. No
--               `trigger` key: a trigger is a clinical criterion, and this carries none.
--        cover  (cover only, required): {grade, team?, window:{start "HH:MM", end "HH:MM"}}.
--               `grade` uses the values of roster_member_roles.grade (literal list, no
--               join). Roster's shift table is roster_assignments (file #3); cover does
--               not join to it (ruling 5).
--   B. Columns published_at, last_confirmed_at, last_confirmed_by on entries, and an
--      `entry.confirm` action that stamps last_confirmed_* without a revision bump.
--   Contract rulings carried: invitations.issued_via_mode (ruling 2), member.display_name
--   (ruling 3), FOR SHARE for read-only actions (ruling 4).
--   The team link (former part C) is NOT here; it is deferred to a later PR (ruling 6).
--
-- NON-SQL FOLLOW-UPS THE COMBINED PR MUST CARRY
--   1. supabase/schema.sql: append this file verbatim as
--      "-- Projection: <stamp>_on_call_service_items.sql", straight after file #1's
--      projection and before roster_mode's.
--   2. supabase/drift-manifest.json: run `npm run drift:manifest` (local Docker replay).
--      Expect a new def_hash for public.on_call_service_command(uuid,uuid,text,jsonb)
--      (today 43d45363f916c32f4848000c43602ee8), plus entries for the three entry columns,
--      the publish-dates check, issued_via_mode and its check. Then
--      `npm run check:drift-manifest-freshness`.
--   3. supabase/applied-migration-hashes.json: `npm run migrations:seal` after the final
--      filename is stamped (append-only; never reseal).
--   4. src/lib/supabase/database.types.ts: regenerate for the new columns.
--   5. Zod, strict (src/lib/on-call/):
--      - entry-model.ts: export the step object as `onCallEscalationStepSchema`, unchanged.
--      - service-model.ts: serviceSections += "playbook","cover"; serviceContentSchema
--        gains optional `steps` (z.array(onCallEscalationStepSchema).min(1).max(20), plus
--        lengths whoToCall/when 1-160, phone 1-80 and distinct `order`, to match the SQL)
--        and optional strict `cover`; superRefine: playbook/cover => kind clinical|legal,
--        steps iff playbook, cover iff section cover. ServiceEntry += publishedAt,
--        lastConfirmedAt. Actions += entry.confirm {entryId, publishedRevision},
--        member.display_name {memberId?, displayName: string 1-80 trimmed | null}.
--        invitation.create += invitedEmail [contract §3]. ServiceMembership and
--        ServiceMember += displayName; ServiceInvitation += invitedEmail, issuedViaMode.
--   6. service-repository.ts error map: service_invite_email_mismatch (contract). No
--      other new error codes.
--   7. API routes: `actorEmail` for join must come from the signed-in session's CONFIRMED
--      email, never from the request body. The route, not this RPC, is what makes the
--      email trustworthy.
--   8. Tests to re-point or extend:
--      - tests/on-call-service-contract.test.ts lines 117 and 132 read the old migration
--        filename; point them at this file. The join-fix regex still matches here.
--        Add: entry.confirm never writes `revision`; playbook/cover reject kind
--        operational; a mode invite with a missing or unknown mode function is rejected.
--      - tests/on-call-service-api.test.ts (new actions, error codes).
--      - tests/cross-tenant-oncall-content-probe.test.ts and
--        scripts/lib/cross-tenant-oncall-content-probe.ts: comments name the old file;
--        add entry.confirm and member.display_name to the non-member refusal set.
--      - tests/retrieval-owner-filter-guard.test.ts: comment names the old file. (File
--        #1's member_events table has user_id and will change the exact userKeyed list.)
--      - tests/on-call-service-governance.dom.test.tsx with the app follow-up.
--   9. Gates: check:migration-role, check:migration-immutability, check:function-grants,
--      check:pr-policy (timestamp no more than 2 days ahead), CI migration replay.
-- =====================================================================================


-- ---------- B. Dates readers can trust ----------
alter table public.on_call_service_entries
  add column published_at timestamptz,
  add column last_confirmed_at timestamptz,
  add column last_confirmed_by uuid references auth.users(id) on delete set null;

-- Conservative backfill. When the latest revision is the published one, the last write
-- was the publish, so updated_at is the publish time. Otherwise only a review approval
-- time is trustworthy; an operational entry edited after publishing stays null
-- ("date not known") rather than showing a draft-save time as a publish time.
update public.on_call_service_entries
   set published_at = case when revision = published_revision then updated_at else published_reviewed_at end
 where published_content is not null;

alter table public.on_call_service_entries
  add constraint on_call_service_entries_publish_dates
  check (published_content is not null or (published_at is null and last_confirmed_at is null and last_confirmed_by is null));

comment on column public.on_call_service_entries.published_at is
  'When the currently published revision was published. Null if nothing is published, or if a pre-existing publish time is unknown.';
comment on column public.on_call_service_entries.last_confirmed_at is
  'When an editor (or, for clinical/legal, a clinical reviewer) last said the published revision is still correct. Reset on every publish and withdraw.';

-- ---------- C. After-hours times per site (Josh card 2026-09-26 19:06Z) ----------
-- Set by the hospital, never guessed: while either is null, Now does not adapt to after hours.
-- A window that crosses midnight (17:30 to 08:00) is stored as start > end.
alter table public.on_call_service_sites
  add column after_hours_start time null,
  add column after_hours_end time null,
  add constraint on_call_service_sites_after_hours
    check ((after_hours_start is null) = (after_hours_end is null) and (after_hours_start is null or after_hours_start <> after_hours_end));
comment on column public.on_call_service_sites.after_hours_start is
  'Start of this hospital''s after-hours period, set by an editor. Null means not set; Now then does not adapt.';

-- ---------- [ruling 2] Invites issued through another mode ----------
alter table public.on_call_service_invitations
  add column issued_via_mode text null,
  add constraint on_call_service_invitations_issued_via_mode
    check (issued_via_mode is null or (issued_via_mode in ('roster','teaching') and role = 'member'));
comment on column public.on_call_service_invitations.issued_via_mode is
  'Null for invites issued by On Call editors/admins; otherwise the mode whose <mode>_can_invite() re-checks the issuer at join. Mode invites are member-only.';

-- ---------- The command RPC, replaced in full ----------
create or replace function public.on_call_service_command(p_actor_id uuid,p_service_id uuid,p_action text,p_payload jsonb default '{}') returns jsonb
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare
  v_service public.on_call_services;
  v_member public.on_call_service_members;
  v_target public.on_call_service_members;
  v_invite public.on_call_service_invitations;
  v_entry public.on_call_service_entries;
  v_report public.on_call_service_reports;
  v_content jsonb;
  v_result jsonb;
  v_id uuid;
  v_site uuid;
  v_revision integer;
  v_status text;
  v_can_edit boolean;
  v_can_draft boolean;
  v_source jsonb;
  v_step jsonb;
  v_email text;
  v_via text;
  v_rejoin boolean;
  v_confirmed_at timestamptz;
  v_issuer_ok boolean;
  v_name text;
begin
  -- API authentication verifies the actor; do not require service_role access to
  -- auth.users. Membership checks below authorize every service operation.
  if p_actor_id is null then raise exception 'service_auth_required'; end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then raise exception 'service_invalid_request'; end if;

  if p_action='list' then
    select jsonb_build_object('services',coalesce(jsonb_agg(jsonb_build_object(
      'id',s.id,'name',s.name,'role',m.role,'clinicalReviewer',m.clinical_reviewer,
      'sites',(select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'name',t.name) order by t.name),'[]') from public.on_call_service_sites t where t.service_id=s.id)
    ) order by s.name),'[]')) into v_result
    from public.on_call_services s join public.on_call_service_members m on m.service_id=s.id
    where m.user_id=p_actor_id and m.revoked_at is null;
    return v_result;
  end if;

  if p_action='create' then
    perform pg_advisory_xact_lock(hashtextextended(p_actor_id::text, 74816));
    if (select count(*) from public.on_call_service_members where user_id=p_actor_id and revoked_at is null) >= 50 then raise exception 'service_limit'; end if;
    insert into public.on_call_services(name,created_by) values(p_payload->>'name',p_actor_id) returning * into v_service;
    insert into public.on_call_service_sites(service_id,name) values(v_service.id,p_payload->>'siteName') returning id into v_site;
    insert into public.on_call_service_members(service_id,user_id,role) values(v_service.id,p_actor_id,'admin');
    -- [contract §4] one audit row per join; creating a service is the creator's join.
    insert into public.on_call_service_member_events(service_id,user_id,event,mode,actor_id) values(v_service.id,p_actor_id,'joined',null,p_actor_id);
    return jsonb_build_object('serviceId',v_service.id,'siteId',v_site);
  end if;

  if p_action='join' then
    select service_id into p_service_id from public.on_call_service_invitations where token_hash=p_payload->>'tokenHash';
    if p_service_id is null then raise exception 'service_invitation_invalid'; end if;
  end if;
  -- Shared lock order for reads and writes: service, membership, then target.
  -- A read starting after revocation commits cannot return the removed service.
  -- [contract §7, ruling 4] Read-only actions and the personal orientation check-in take
  -- FOR SHARE; anything changing membership, invitations or content keeps FOR UPDATE.
  -- One call takes exactly one of the two, so there is no lock upgrade.
  if p_action in ('read','orientation.set') then
    select * into v_service from public.on_call_services where id=p_service_id for share;
  else
    select * into v_service from public.on_call_services where id=p_service_id for update;
  end if;
  if not found then raise exception 'service_access_denied'; end if;

  if p_action='join' then
    select * into v_invite from public.on_call_service_invitations
      where service_id=p_service_id and token_hash=p_payload->>'tokenHash' for update;
    if not found or v_invite.revoked_at is not null or v_invite.used_at is not null or v_invite.expires_at <= now()
      then raise exception 'service_invitation_invalid'; end if;
    -- [contract §8, ruling 2] Re-check that the issuer is still entitled to this invite.
    -- A null issuer, an inactive issuer, an unknown mode or a missing mode function all
    -- fail closed. Mode functions are created by later files, so they are called only
    -- here, at run time; plpgsql plans each statement when it first runs.
    v_issuer_ok := false;
    if public.service_member_active(p_service_id, v_invite.issued_by) then
      if v_invite.issued_via_mode is null then
        -- On Call's own rule: an admin may issue any role, an editor a member invite only.
        v_issuer_ok := exists(select 1 from public.on_call_service_members where service_id=p_service_id and user_id=v_invite.issued_by and revoked_at is null
                              and (role='admin' or (role='editor' and v_invite.role='member')));
      else
        begin
          case v_invite.issued_via_mode
            when 'roster' then
              v_issuer_ok := v_invite.role='member' and coalesce(public.roster_can_invite(p_service_id, v_invite.issued_by), false);
            when 'teaching' then
              v_issuer_ok := v_invite.role='member' and coalesce(public.teaching_can_invite(p_service_id, v_invite.issued_by), false);
            else
              v_issuer_ok := false;
          end case;
        exception when undefined_function then
          v_issuer_ok := false;
        end;
      end if;
    end if;
    if not v_issuer_ok then raise exception 'service_invitation_invalid'; end if;
    -- [contract §3] Email-bound invites. The route supplies the session's confirmed email;
    -- a missing email never matches. Legacy rows (invited_email null) expire within 7 days.
    if v_invite.invited_email is not null
      and lower(btrim(coalesce(p_payload->>'actorEmail',''))) is distinct from v_invite.invited_email then
      raise exception 'service_invite_email_mismatch';
    end if;
    -- An already-active member consumes nothing: the invitation stays usable for whoever it
    -- was actually issued to reach, and no membership row changes. Reject before the invite
    -- is marked used, not after — marking it used unconditionally here was Codex P2 (a
    -- redeemable invite silently being burned by a no-op join).
    if exists(select 1 from public.on_call_service_members where service_id=p_service_id and user_id=p_actor_id and revoked_at is null) then
      raise exception 'service_already_member';
    end if;
    -- [contract §6] member cap raised from 500 to 5,000.
    if (select count(*) from public.on_call_service_members where service_id=p_service_id and revoked_at is null) >= 5000 then raise exception 'service_limit'; end if;
    v_rejoin := exists(select 1 from public.on_call_service_members where service_id=p_service_id and user_id=p_actor_id);
    insert into public.on_call_service_members(service_id,user_id,role) values(p_service_id,p_actor_id,v_invite.role)
      on conflict(service_id,user_id) do update set role=excluded.role,clinical_reviewer=false,revoked_at=null,joined_at=now();
    update public.on_call_service_invitations set used_at=now(),used_by=p_actor_id where id=v_invite.id;
    insert into public.on_call_service_member_events(service_id,user_id,event,mode,actor_id)
      values(p_service_id,p_actor_id,case when v_rejoin then 'rejoined' else 'joined' end,null,p_actor_id);
    return jsonb_build_object('serviceId',p_service_id);
  end if;

  -- [contract, shared permission helper] Every mode's command RPC checks this first.
  if not public.service_member_active(p_service_id,p_actor_id) then raise exception 'service_access_denied'; end if;
  select * into v_member from public.on_call_service_members where service_id=p_service_id and user_id=p_actor_id and revoked_at is null;
  if not found then raise exception 'service_access_denied'; end if;
  v_can_edit := v_member.role in ('editor','admin');
  v_can_draft := v_can_edit or v_member.clinical_reviewer;
  v_site := nullif(p_payload->>'siteId','')::uuid;
  if v_site is not null and not exists(select 1 from public.on_call_service_sites where id=v_site and service_id=p_service_id) then raise exception 'service_invalid_site'; end if;

  if p_action='read' then
    return jsonb_build_object(
      'service',jsonb_build_object('id',v_service.id,'name',v_service.name),
      'membership',jsonb_build_object('role',v_member.role,'clinicalReviewer',v_member.clinical_reviewer,'displayName',v_member.display_name),
      'sites',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'name',s.name,'afterHoursStart',to_char(s.after_hours_start,'HH24:MI'),'afterHoursEnd',to_char(s.after_hours_end,'HH24:MI')) order by s.name),'[]') from public.on_call_service_sites s where service_id=p_service_id),
      'entries',(select coalesce(jsonb_agg(jsonb_build_object(
        'id',e.id,'revision',case when v_can_draft then e.revision else e.published_revision end,
        'publishedRevision',e.published_revision,
        'content',case when v_can_draft then e.content else e.published_content end,
        'publishedContent',e.published_content,
        'status',case when v_can_draft then e.status else 'published' end,
        'authorId',case when v_can_draft then e.author_id else e.published_author_id end,
        'reviewedBy',e.published_reviewed_by,'reviewedAt',e.published_reviewed_at,'reviewComment',case when v_can_draft then e.review_comment else '' end,
        'updatedAt',e.updated_at,
        'publishedAt',e.published_at,'lastConfirmedAt',e.last_confirmed_at
      ) order by e.updated_at desc),'[]') from public.on_call_service_entries e
        where e.service_id=p_service_id and (v_can_draft or e.published_content is not null)
        and (v_site is null or (case when v_can_draft then e.content else e.published_content end)->>'siteId' is null or (case when v_can_draft then e.content else e.published_content end)->>'siteId'=v_site::text)),
      'members',case when v_member.role='admin' then (select coalesce(jsonb_agg(jsonb_build_object('id',m.user_id,'role',m.role,'clinicalReviewer',m.clinical_reviewer,'joinedAt',m.joined_at,'displayName',m.display_name) order by m.joined_at),'[]') from public.on_call_service_members m where m.service_id=p_service_id and m.revoked_at is null) else '[]'::jsonb end,
      'invitations',case when v_member.role='admin' then (select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'role',i.role,'expiresAt',i.expires_at,'revokedAt',i.revoked_at,'usedAt',i.used_at,'invitedEmail',i.invited_email,'issuedViaMode',i.issued_via_mode) order by i.created_at desc),'[]') from public.on_call_service_invitations i where i.service_id=p_service_id) else '[]'::jsonb end,
      'reports',case when v_can_edit then (select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'entryId',r.entry_id,'reason',r.reason,'status',r.status,'resolution',r.resolution,'createdAt',r.created_at) order by r.created_at desc),'[]') from public.on_call_service_reports r where r.service_id=p_service_id) else '[]'::jsonb end,
      'orientation',(select coalesce(jsonb_agg(jsonb_build_object('entryId',o.entry_id,'siteId',o.site_id,'rotation',o.rotation,'revision',o.revision,'completedAt',o.completed_at)),'[]') from public.on_call_service_orientation o where o.service_id=p_service_id and o.user_id=p_actor_id and o.site_id=v_site and o.rotation=p_payload->>'rotation')
    );
  end if;

  if p_action in ('site.create','invitation.revoke','member.update','member.revoke') and v_member.role <> 'admin' then raise exception 'service_role_denied'; end if;
  -- [contract §8] Editors may invite as member only; only an admin invites editors/admins.
  -- [contract v6, Roster replay] Mode invites: a Roster or Teaching manager is an ordinary
  -- service member, so the mode's own can-invite function decides, never the On Call role.
  -- Mode invites are member-only and record issued_via_mode. The mode functions are created
  -- by later files and are called only here, at run time; a missing one fails closed.
  if p_action='invitation.create' then
    v_via := nullif(p_payload->>'issuedViaMode','');
    if v_via is null then
      if not (v_member.role='admin' or (v_member.role='editor' and p_payload->>'role'='member')) then raise exception 'service_role_denied'; end if;
    else
      v_issuer_ok := false;
      if p_payload->>'role' = 'member' then
        begin
          case v_via
            when 'roster' then
              v_issuer_ok := coalesce(public.roster_can_invite(p_service_id, p_actor_id), false);
            when 'teaching' then
              v_issuer_ok := coalesce(public.teaching_can_invite(p_service_id, p_actor_id), false);
            else
              v_issuer_ok := false;
          end case;
        exception when undefined_function then
          v_issuer_ok := false;
        end;
      end if;
      if not v_issuer_ok then raise exception 'service_role_denied'; end if;
    end if;
  end if;
  if p_action='site.create' then
    if (select count(*) from public.on_call_service_sites where service_id=p_service_id) >= 100 then raise exception 'service_limit'; end if;
    insert into public.on_call_service_sites(service_id,name) values(p_service_id,p_payload->>'name') returning id into v_id;
    return jsonb_build_object('siteId',v_id);
  elsif p_action='site.update' then
    -- After-hours times only; editors and admins. Both "HH:MM", or both null to clear.
    if not v_can_edit then raise exception 'service_role_denied'; end if;
    -- Both keys must be present (explicit JSON null clears), so a partial payload never wipes the times.
    if v_site is null or not (p_payload ?& array['afterHoursStart','afterHoursEnd']) then raise exception 'service_invalid_request'; end if;
    if (jsonb_typeof(p_payload->'afterHoursStart') = 'null') <> (jsonb_typeof(p_payload->'afterHoursEnd') = 'null') then raise exception 'service_invalid_request'; end if;
    if jsonb_typeof(p_payload->'afterHoursStart') <> 'null' and (
         jsonb_typeof(p_payload->'afterHoursStart') is distinct from 'string' or jsonb_typeof(p_payload->'afterHoursEnd') is distinct from 'string'
      or p_payload->>'afterHoursStart' !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
      or p_payload->>'afterHoursEnd' !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
      or p_payload->>'afterHoursStart' = p_payload->>'afterHoursEnd') then raise exception 'service_invalid_request'; end if;
    update public.on_call_service_sites
       set after_hours_start = (p_payload->>'afterHoursStart')::time,
           after_hours_end = (p_payload->>'afterHoursEnd')::time
     where id = v_site and service_id = p_service_id;
    return jsonb_build_object('siteId',v_site);
  elsif p_action='invitation.create' then
    if (p_payload->>'expiresInDays')::integer not between 1 and 7 then raise exception 'service_invalid_request'; end if;
    -- [contract §3] invited_email is required on every new invite, stored normalised.
    v_email := lower(btrim(coalesce(p_payload->>'invitedEmail','')));
    if jsonb_typeof(p_payload->'invitedEmail') is distinct from 'string' or length(v_email) > 320
      or v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then raise exception 'service_invalid_request'; end if;
    -- [contract §6] open-invite cap raised from 100 to 1,000.
    if (select count(*) from public.on_call_service_invitations where service_id=p_service_id and used_at is null and revoked_at is null and expires_at>now()) >= 1000 then raise exception 'service_limit'; end if;
    insert into public.on_call_service_invitations(service_id,token_hash,role,issued_by,expires_at,invited_email,issued_via_mode)
      values(p_service_id,p_payload->>'tokenHash',case when v_via is null then p_payload->>'role' else 'member' end,p_actor_id,now()+make_interval(days=>(p_payload->>'expiresInDays')::integer),v_email,v_via) returning * into v_invite;
    return jsonb_build_object('invitationId',v_invite.id,'expiresAt',v_invite.expires_at);
  elsif p_action='invitation.revoke' then
    update public.on_call_service_invitations set revoked_at=now() where service_id=p_service_id and id=(p_payload->>'invitationId')::uuid;
    if not found then raise exception 'service_not_found'; end if;
    return jsonb_build_object('ok',true);
  elsif p_action='member.display_name' then
    -- [contract §5, ruling 3] The member themselves or a service admin. Trimmed, 1-80
    -- characters, or JSON null to clear. Not an audit event (not in the event list).
    v_id := coalesce(nullif(p_payload->>'memberId','')::uuid, p_actor_id);
    if v_id <> p_actor_id and v_member.role <> 'admin' then raise exception 'service_role_denied'; end if;
    if not (p_payload ? 'displayName') then raise exception 'service_invalid_request'; end if;
    if jsonb_typeof(p_payload->'displayName') = 'null' then
      v_name := null;
    elsif jsonb_typeof(p_payload->'displayName') = 'string' and length(btrim(p_payload->>'displayName')) between 1 and 80 then
      v_name := btrim(p_payload->>'displayName');
    else
      raise exception 'service_invalid_request';
    end if;
    update public.on_call_service_members set display_name=v_name where service_id=p_service_id and user_id=v_id and revoked_at is null;
    if not found then raise exception 'service_not_found'; end if;
    return jsonb_build_object('ok',true,'displayName',v_name);
  elsif p_action in ('member.update','member.revoke') then
    select * into v_target from public.on_call_service_members where service_id=p_service_id and user_id=(p_payload->>'memberId')::uuid and revoked_at is null for update;
    if not found then raise exception 'service_not_found'; end if;
    if v_target.role='admin' and (p_action='member.revoke' or p_payload->>'role'<>'admin')
      and (select count(*) from public.on_call_service_members where service_id=p_service_id and role='admin' and revoked_at is null)<=1 then raise exception 'service_last_admin'; end if;
    if p_action='member.revoke' then
      update public.on_call_service_members set revoked_at=now(),clinical_reviewer=false where service_id=p_service_id and user_id=v_target.user_id;
      update public.on_call_service_invitations set revoked_at=now() where service_id=p_service_id and issued_by=v_target.user_id and used_at is null;
      insert into public.on_call_service_member_events(service_id,user_id,event,mode,actor_id) values(p_service_id,v_target.user_id,'revoked',null,p_actor_id);
    else
      update public.on_call_service_members set role=p_payload->>'role',clinical_reviewer=(p_payload->>'clinicalReviewer')::boolean where service_id=p_service_id and user_id=v_target.user_id;
      if v_target.role is distinct from p_payload->>'role' then
        insert into public.on_call_service_member_events(service_id,user_id,event,mode,actor_id) values(p_service_id,v_target.user_id,'role_changed',null,p_actor_id);
      end if;
    end if;
    return jsonb_build_object('ok',true);
  end if;

  if p_action in ('entry.save','entry.withdraw','report.resolve') and not v_can_edit then raise exception 'service_role_denied'; end if;
  if p_action='entry.save' then
    v_content := p_payload - array['action','entryId','expectedRevision','publish'];
    if v_content - array['siteId','section','kind','title','body','phone','sources','orientationPhase','steps','cover'] <> '{}'::jsonb
      or not (v_content ?& array['siteId','section','kind','title','body','phone','sources','orientationPhase'])
      or coalesce(v_content->>'section','') not in ('contacts','referrals','resources','documentation','orientation','teaching','admin','playbook','cover')
      or coalesce(v_content->>'kind','') not in ('operational','clinical','legal')
      or coalesce(v_content->>'orientationPhase','') not in ('before_start','first_shift','first_week','ongoing','leaving')
      or jsonb_typeof(v_content->'title') is distinct from 'string' or length(btrim(v_content->>'title')) not between 1 and 160
      or jsonb_typeof(v_content->'body') is distinct from 'string' or length(v_content->>'body')>6000
      or jsonb_typeof(v_content->'phone') is distinct from 'string' or length(v_content->>'phone')>80
      or jsonb_typeof(v_content->'sources') is distinct from 'array'
      or jsonb_typeof(p_payload->'publish') is distinct from 'boolean' then raise exception 'service_invalid_request'; end if;
    if jsonb_array_length(v_content->'sources')>12 then raise exception 'service_invalid_request'; end if;
    for v_source in select value from jsonb_array_elements(v_content->'sources') loop
      if jsonb_typeof(v_source) is distinct from 'object' or v_source - array['label','url'] <> '{}'::jsonb
        or jsonb_typeof(v_source->'label') is distinct from 'string' or length(btrim(v_source->>'label')) not between 1 and 160
        or jsonb_typeof(v_source->'url') is distinct from 'string' or length(v_source->>'url')>2000
        or coalesce(v_source->>'url','') !~ '^https://[^/@[:space:]]+(/|$)' then raise exception 'service_invalid_request'; end if;
    end loop;
    if v_content->>'kind'<>'operational' and jsonb_array_length(v_content->'sources')=0 then raise exception 'service_source_required'; end if;
    -- A. Playbook and cover are always clinical or legal: source link plus second-person review.
    if v_content->>'section' in ('playbook','cover') and v_content->>'kind' not in ('clinical','legal') then raise exception 'service_review_required'; end if;
    -- `steps` belongs to playbook and is required there; `cover` likewise for cover.
    if (v_content ? 'steps') is distinct from (v_content->>'section'='playbook')
      or (v_content ? 'cover') is distinct from (v_content->>'section'='cover') then raise exception 'service_invalid_request'; end if;
    if v_content ? 'steps' then
      -- Shape of entry-model.ts playbookDetails.escalationSteps: who, number, when; no criteria.
      if jsonb_typeof(v_content->'steps') is distinct from 'array' then raise exception 'service_invalid_request'; end if;
      if jsonb_array_length(v_content->'steps') not between 1 and 20 then raise exception 'service_invalid_request'; end if;
      for v_step in select value from jsonb_array_elements(v_content->'steps') loop
        if jsonb_typeof(v_step) is distinct from 'object' then raise exception 'service_invalid_request'; end if;
        if v_step - array['order','whoToCall','when','phone','hours','waitMinutes'] <> '{}'::jsonb
          or not (v_step ?& array['order','whoToCall','when'])
          or jsonb_typeof(v_step->'order') is distinct from 'number' or coalesce(v_step->>'order','') !~ '^([1-9]|1[0-9]|20)$'
          or jsonb_typeof(v_step->'whoToCall') is distinct from 'string' or length(btrim(v_step->>'whoToCall')) not between 1 and 160
          or jsonb_typeof(v_step->'when') is distinct from 'string' or length(btrim(v_step->>'when')) not between 1 and 160
          or (v_step ? 'phone' and (jsonb_typeof(v_step->'phone') is distinct from 'string' or length(btrim(v_step->>'phone')) not between 1 and 80))
          or (v_step ? 'hours' and (jsonb_typeof(v_step->'hours') is distinct from 'string' or v_step->>'hours' not in ('any','in-hours','after-hours')))
          -- Optional hospital-set wait before the next step (Josh card 2026-09-26 19:06Z).
          or (v_step ? 'waitMinutes' and (jsonb_typeof(v_step->'waitMinutes') is distinct from 'number' or coalesce(v_step->>'waitMinutes','') !~ '^([1-9]|[1-9][0-9]|1[01][0-9]|120)$'))
          then raise exception 'service_invalid_request'; end if;
      end loop;
      if (select count(distinct value->>'order') from jsonb_array_elements(v_content->'steps')) <> jsonb_array_length(v_content->'steps') then raise exception 'service_invalid_request'; end if;
    end if;
    if v_content ? 'cover' then
      -- Role and shift window only. `grade` uses the contract's roster_member_roles.grade
      -- values; times are local wall-clock "HH:MM", and end < start means overnight.
      if jsonb_typeof(v_content->'cover') is distinct from 'object' then raise exception 'service_invalid_request'; end if;
      if (v_content->'cover') - array['grade','team','window'] <> '{}'::jsonb
        or not (v_content->'cover' ?& array['grade','window'])
        or jsonb_typeof(v_content->'cover'->'grade') is distinct from 'string'
        or v_content->'cover'->>'grade' not in ('intern','resident','registrar','fellow','consultant','other')
        or (v_content->'cover' ? 'team' and (jsonb_typeof(v_content->'cover'->'team') is distinct from 'string' or length(btrim(v_content->'cover'->>'team')) not between 1 and 80))
        or jsonb_typeof(v_content->'cover'->'window') is distinct from 'object' then raise exception 'service_invalid_request'; end if;
      if (v_content->'cover'->'window') - array['start','end'] <> '{}'::jsonb
        or not (v_content->'cover'->'window' ?& array['start','end'])
        or jsonb_typeof(v_content->'cover'->'window'->'start') is distinct from 'string'
        or jsonb_typeof(v_content->'cover'->'window'->'end') is distinct from 'string'
        or v_content->'cover'->'window'->>'start' !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
        or v_content->'cover'->'window'->>'end' !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
        or v_content->'cover'->'window'->>'start' = v_content->'cover'->'window'->>'end' then raise exception 'service_invalid_request'; end if;
    end if;
    v_id := nullif(p_payload->>'entryId','')::uuid;
    if v_id is null then
      if (select count(*) from public.on_call_service_entries where service_id=p_service_id)>=1000 then raise exception 'service_limit'; end if;
      if p_payload ? 'expectedRevision' then raise exception 'service_revision_conflict'; end if;
      v_revision := 1;
    else
      select * into v_entry from public.on_call_service_entries where id=v_id and service_id=p_service_id for update;
      if not found then raise exception 'service_not_found'; end if;
      if v_entry.revision is distinct from (p_payload->>'expectedRevision')::integer then raise exception 'service_revision_conflict'; end if;
      v_revision := v_entry.revision+1;
    end if;
    v_status := case when (p_payload->>'publish')::boolean then case when v_content->>'kind'='operational' then 'published' else 'pending_review' end else 'draft' end;
    -- Reclassification cannot evade independent review of an existing clinical/legal entry.
    if v_entry.id is not null and (v_entry.content->>'kind'<>'operational' or v_entry.published_content->>'kind'<>'operational') and v_content->>'kind'='operational' then raise exception 'service_review_required'; end if;
    if v_id is null then
      insert into public.on_call_service_entries(service_id,site_id,content,author_id,status)
        values(p_service_id,v_site,v_content,p_actor_id,v_status) returning id into v_id;
    else
      update public.on_call_service_entries set site_id=v_site,content=v_content,author_id=p_actor_id,status=v_status,revision=v_revision,review_comment='',updated_at=now() where id=v_id;
    end if;
    if v_status='published' then
      update public.on_call_service_entries set published_content=v_content,published_revision=v_revision,published_author_id=p_actor_id,published_reviewed_by=null,published_reviewed_at=null,
        published_at=now(),last_confirmed_at=null,last_confirmed_by=null where id=v_id;
    end if;
    return jsonb_build_object('entryId',v_id,'revision',v_revision,'status',v_status);
  elsif p_action in ('entry.review','entry.withdraw','entry.confirm','report.create','orientation.set') then
    select * into v_entry from public.on_call_service_entries where id=(p_payload->>'entryId')::uuid and service_id=p_service_id for update;
    if not found then raise exception 'service_not_found'; end if;
    if p_action in ('entry.review','entry.withdraw') then
      if v_entry.revision is distinct from (p_payload->>'expectedRevision')::integer then raise exception 'service_revision_conflict'; end if;
      if p_action='entry.withdraw' then
        update public.on_call_service_entries set status='withdrawn',revision=revision+1,published_content=null,published_revision=null,published_author_id=null,published_reviewed_by=null,published_reviewed_at=null,
          published_at=null,last_confirmed_at=null,last_confirmed_by=null,updated_at=now() where id=v_entry.id;
      else
        if not v_member.clinical_reviewer or v_entry.author_id=p_actor_id then raise exception 'service_review_denied'; end if;
        if v_entry.status<>'pending_review' or v_entry.content->>'kind'='operational' then raise exception 'service_review_required'; end if;
        if p_payload->>'decision'='approve' then
          update public.on_call_service_entries set status='published',revision=revision+1,published_content=content,published_revision=revision+1,published_author_id=author_id,published_reviewed_by=p_actor_id,published_reviewed_at=now(),
            published_at=now(),last_confirmed_at=null,last_confirmed_by=null,review_comment=p_payload->>'comment',updated_at=now() where id=v_entry.id;
        elsif p_payload->>'decision'='return' then
          update public.on_call_service_entries set status='draft',revision=revision+1,review_comment=p_payload->>'comment',updated_at=now() where id=v_entry.id;
        else raise exception 'service_invalid_request'; end if;
      end if;
      return jsonb_build_object('ok',true);
    elsif p_action='entry.confirm' then
      -- B. "Still correct" for the published revision the caller actually saw. Stamps
      -- last_confirmed_* only: no revision, status, content or updated_at change.
      if v_entry.published_content is null then raise exception 'service_not_found'; end if;
      if v_entry.published_content->>'kind'='operational' then
        if not v_can_edit then raise exception 'service_role_denied'; end if;
      elsif not v_member.clinical_reviewer then
        raise exception 'service_review_denied';
      end if;
      if jsonb_typeof(p_payload->'publishedRevision') is distinct from 'number'
        or (p_payload->>'publishedRevision') is distinct from v_entry.published_revision::text then raise exception 'service_revision_conflict'; end if;
      update public.on_call_service_entries set last_confirmed_at=now(),last_confirmed_by=p_actor_id where id=v_entry.id
        returning last_confirmed_at into v_confirmed_at;
      return jsonb_build_object('ok',true,'lastConfirmedAt',v_confirmed_at);
    elsif p_action='report.create' then
      if v_entry.published_content is null then raise exception 'service_not_found'; end if;
      if (select count(*) from public.on_call_service_reports where service_id=p_service_id and status='open')>=1000 then raise exception 'service_limit'; end if;
      insert into public.on_call_service_reports(service_id,entry_id,reported_by,reason) values(p_service_id,v_entry.id,p_actor_id,p_payload->>'reason') returning id into v_id;
      return jsonb_build_object('reportId',v_id);
    else
      if v_site is null or v_entry.published_content is null or v_entry.published_content->>'section'<>'orientation'
        or (v_entry.published_content->>'siteId' is not null and v_entry.published_content->>'siteId'<>v_site::text) then raise exception 'service_invalid_orientation'; end if;
      if (p_payload->>'completed')::boolean then
        insert into public.on_call_service_orientation(service_id,user_id,site_id,entry_id,rotation,revision)
          values(p_service_id,p_actor_id,v_site,v_entry.id,p_payload->>'rotation',v_entry.published_revision)
          on conflict(service_id,user_id,site_id,entry_id,rotation) do update set revision=excluded.revision,completed_at=now();
      else
        delete from public.on_call_service_orientation where service_id=p_service_id and user_id=p_actor_id and site_id=v_site and entry_id=v_entry.id and rotation=p_payload->>'rotation';
      end if;
      return jsonb_build_object('ok',true);
    end if;
  elsif p_action='report.resolve' then
    update public.on_call_service_reports set status='resolved',resolution=p_payload->>'resolution',resolved_by=p_actor_id,resolved_at=now()
      where service_id=p_service_id and id=(p_payload->>'reportId')::uuid;
    if not found then raise exception 'service_not_found'; end if;
    return jsonb_build_object('ok',true);
  end if;
  raise exception 'service_invalid_request';
end $$;
revoke all on function public.on_call_service_command(uuid,uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.on_call_service_command(uuid,uuid,text,jsonb) to service_role;

-- 20260926225409_roster_mode.sql
-- Roster mode: file 3 of the combined Roster DB PR (shared-db-contract.md v6).
--
-- MERGING THIS PR APPLIES IT TO THE LIVE CLINICAL DATABASE WITHIN SECONDS. Josh merges it himself.
--
-- Relies on file 1 (roster_shared_services_hardening) and file 2 (on_call_service_items).
-- It never replaces on_call_service_command and never writes on_call_service_invitations.
--
-- Tenancy, the same as every service table: RLS on, no policies, no grant to anon or
-- authenticated, service_role only. Owner tables (own shifts, calendar links, leave, push
-- subscriptions) are read and written by owner_id from the validated session. Team tables are
-- read and written ONLY through roster_read() and roster_command(), which check the actor's
-- active membership (service_member_active) and Roster role in SQL on every call.
--
-- Roster data holds staff names and shift times, never patient data. There are no leave
-- reasons, no free-text notes and no sick or carer's leave kinds anywhere in this file.
--
-- Parts:
--   A. Own shifts: import fix (hand-added shifts survive), kinds, workplaces, more formats.
--   B. Calendar links (a doctor's live roster link) and phone-alert subscriptions.
--   C. Team: Roster roles, team settings, publications, the live roster, swaps, open shifts,
--      dates people can't work, planned leave, seen receipts.
--   D. Roster maker (Release 3): shift codes, staffing needs, drafts, the change log with undo,
--      and change agreements.
--   E. Functions: roster_can_invite, the revoke cascade, the own-shift replace, roster_read,
--      roster_command, the platform manager switch, and the 12-month retention purge.

-- =============================================================================================
-- A. Own shifts
-- =============================================================================================

-- source: 'import' rows are replaced by the next import of the same workplace; 'manual' rows
-- (added by hand in Roster) are never touched by an import. Existing rows are all imports.
alter table public.on_call_shifts
  add column source text not null default 'import',
  add column kind text,
  add column workplace text,
  add column series_id uuid,
  add constraint on_call_shifts_source check (source in ('import', 'manual')),
  add constraint on_call_shifts_kind check (kind is null or kind in ('day', 'evening', 'night', 'on_call', 'leave', 'other')),
  add constraint on_call_shifts_workplace check (workplace is null or (btrim(workplace) <> '' and char_length(workplace) <= 80)),
  add constraint on_call_shifts_series_manual check (series_id is null or source = 'manual');

create index on_call_shifts_owner_series_idx on public.on_call_shifts (owner_id, series_id) where series_id is not null;

alter table public.on_call_shift_imports
  drop constraint on_call_shift_imports_format_check,
  add constraint on_call_shift_imports_format_check check (format in ('ics', 'csv', 'xlsx', 'pdf', 'link')),
  add column workplace text,
  add column file_name text,
  add constraint on_call_shift_imports_workplace check (workplace is null or (btrim(workplace) <> '' and char_length(workplace) <= 80)),
  add constraint on_call_shift_imports_file_name check (file_name is null or (btrim(file_name) <> '' and char_length(file_name) <= 120));

-- The original function keeps its signature (the live app calls it until Release 1 ships) but
-- now removes imported shifts only, so a hand-added shift is never deleted by an import.
create or replace function public.on_call_shifts_replace(
  p_owner_id uuid,
  p_window_start date,
  p_window_end date,
  p_format text,
  p_shifts jsonb,
  p_changes jsonb,
  p_added integer,
  p_changed integer,
  p_removed integer
) returns uuid
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  return public.roster_own_shifts_replace(
    p_owner_id, p_window_start, p_window_end, p_format, null, null,
    p_shifts, p_changes, p_added, p_changed, p_removed
  );
end $$;

-- =============================================================================================
-- B. Calendar links and phone-alert subscriptions (owner tables)
-- =============================================================================================

-- A doctor's live roster link (an .ics address from their rostering system). The address is a
-- secret: it is returned only to its owner, never logged, and fetched only over https by the
-- app's guarded fetcher. At most 3 per owner (one per workplace).
create table public.roster_calendar_links (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  url text not null check (url ~ '^https://' and char_length(url) <= 2000),
  workplace text check (workplace is null or (btrim(workplace) <> '' and char_length(workplace) <= 80)),
  last_fetched_at timestamptz,
  last_error text check (last_error is null or last_error in ('unreachable', 'not_calendar', 'too_large', 'too_many_shifts', 'blocked_address')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint roster_calendar_links_one_per_workplace unique nulls not distinct (owner_id, workplace)
);
create index roster_calendar_links_owner_idx on public.roster_calendar_links (owner_id);
create trigger roster_calendar_links_updated_at before update on public.roster_calendar_links
  for each row execute function public.set_updated_at();

create function public.roster_calendar_links_cap() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  perform pg_advisory_xact_lock(hashtextextended(new.owner_id::text, 74817));
  if (select count(*) from public.roster_calendar_links where owner_id = new.owner_id) >= 3 then
    raise exception 'roster_limit';
  end if;
  return new;
end $$;
create trigger roster_calendar_links_cap before insert on public.roster_calendar_links
  for each row execute function public.roster_calendar_links_cap();

-- Web push endpoints for phone alerts (Release 2). One row per phone or browser. The lock
-- screen text is always generic; nothing about a shift is stored here.
create table public.web_push_subscriptions (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  endpoint text not null unique check (endpoint ~ '^https://' and char_length(endpoint) <= 1000),
  p256dh text not null check (char_length(p256dh) between 1 and 200),
  auth text not null check (char_length(auth) between 1 and 100),
  created_at timestamptz not null default now(),
  last_used_at timestamptz
);
create index web_push_subscriptions_owner_idx on public.web_push_subscriptions (owner_id);

create function public.web_push_subscriptions_cap() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  perform pg_advisory_xact_lock(hashtextextended(new.owner_id::text, 74817));
  if (select count(*) from public.web_push_subscriptions where owner_id = new.owner_id) >= 10 then
    raise exception 'roster_limit';
  end if;
  return new;
end $$;
create trigger web_push_subscriptions_cap before insert on public.web_push_subscriptions
  for each row execute function public.web_push_subscriptions_cap();

-- =============================================================================================
-- C. Team tables
-- =============================================================================================

-- Roster role per member. role 'member' carries grade and the name the roster file prints;
-- 'manager' is granted only by the platform (Josh's confirm button), never by a manager.
create table public.roster_member_roles (
  service_id uuid not null,
  user_id uuid not null,
  role text not null default 'member' check (role in ('member', 'manager')),
  grade text check (grade is null or grade in ('intern', 'resident', 'registrar', 'fellow', 'consultant', 'other')),
  roster_name text check (roster_name is null or (btrim(roster_name) <> '' and char_length(roster_name) <= 80)),
  rotation_ends_on date,
  granted_by uuid references auth.users (id) on delete set null,
  granted_at timestamptz not null default now(),
  revoked_at timestamptz,
  primary key (service_id, user_id),
  foreign key (service_id, user_id) references public.on_call_service_members (service_id, user_id) on delete cascade
);
create unique index roster_member_roles_roster_name_idx on public.roster_member_roles (service_id, lower(roster_name))
  where revoked_at is null and roster_name is not null;

-- One row per team. Swap approval default follows Josh's round-6 answer: clean same-grade
-- swaps approve themselves and the manager is told. Rules are the team's own, never "the law".
create table public.roster_team_settings (
  service_id uuid primary key references public.on_call_services (id) on delete cascade,
  swap_approval text not null default 'auto_same_grade' check (swap_approval in ('manager', 'auto_same_grade')),
  rules jsonb not null default '{}'::jsonb check (
    jsonb_typeof(rules) = 'object'
    and (rules - array['minBreakHours', 'maxNightsInRow', 'maxDaysInRow', 'maxHours7d', 'maxHours14d']) = '{}'::jsonb
  ),
  rules_source text check (rules_source is null or (btrim(rules_source) <> '' and char_length(rules_source) <= 200)),
  pay_fortnight_anchor date,
  ai_helper_consented_at timestamptz,
  ai_helper_consented_by uuid references auth.users (id) on delete set null,
  updated_by uuid references auth.users (id) on delete set null,
  updated_at timestamptz not null default now()
);
create trigger roster_team_settings_updated_at before update on public.roster_team_settings
  for each row execute function public.set_updated_at();

-- A published roster version. 'full' replaces every live shift in its dates; 'single_change'
-- replaces only the shifts it names (an urgent fix without re-publishing everything).
create table public.roster_publications (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services (id) on delete cascade,
  version integer not null check (version > 0),
  kind text not null default 'full' check (kind in ('full', 'single_change')),
  period_start date not null,
  period_end date not null,
  source_name text check (source_name is null or (btrim(source_name) <> '' and char_length(source_name) <= 120)),
  published_by uuid references auth.users (id) on delete set null,
  published_at timestamptz not null default now(),
  unique (service_id, version),
  constraint roster_publications_period check (period_end >= period_start and period_end - period_start <= 186)
);
create index roster_publications_service_idx on public.roster_publications (service_id, published_at desc);

-- The live roster: every shift row still in force has superseded_at null. A person not on the
-- app is an ordinary row with user_id null and the printed name; that name is cleared 90 days
-- after the shift ends.
create table public.roster_assignments (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services (id) on delete cascade,
  publication_id uuid not null references public.roster_publications (id) on delete cascade,
  user_id uuid references auth.users (id) on delete set null,
  roster_name text check (roster_name is null or (btrim(roster_name) <> '' and char_length(roster_name) <= 80)),
  site_id uuid,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  shift_code text not null check (char_length(btrim(shift_code)) between 1 and 12),
  kind text not null check (kind in ('day', 'evening', 'night', 'on_call', 'leave', 'other')),
  grade text check (grade is null or grade in ('intern', 'resident', 'registrar', 'fellow', 'consultant', 'other')),
  superseded_at timestamptz,
  foreign key (site_id, service_id) references public.on_call_service_sites (id, service_id) on delete set null (site_id),
  constraint roster_assignments_ends_after_start check (ends_at > starts_at),
  constraint roster_assignments_max_length check (ends_at - starts_at <= interval '36 hours')
);
create index roster_assignments_live_service_idx on public.roster_assignments (service_id, starts_at) where superseded_at is null;
create index roster_assignments_live_user_idx on public.roster_assignments (user_id, starts_at) where superseded_at is null and user_id is not null;
create index roster_assignments_publication_idx on public.roster_assignments (publication_id);

-- A swap between two members. take_assignment_id null means a one-way give to a named colleague.
create table public.roster_swaps (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services (id) on delete cascade,
  requester_id uuid not null references auth.users (id) on delete cascade,
  counterparty_id uuid not null references auth.users (id) on delete cascade,
  give_assignment_id uuid not null references public.roster_assignments (id) on delete cascade,
  take_assignment_id uuid references public.roster_assignments (id) on delete cascade,
  status text not null default 'requested' check (status in ('requested', 'accepted', 'approved', 'declined', 'cancelled', 'expired', 'undone')),
  needs_manager_because text check (needs_manager_because is null or needs_manager_because in ('team_setting', 'within_7_days', 'different_grade', 'team_rule')),
  auto_approved boolean not null default false,
  cancel_reason text check (cancel_reason is null or cancel_reason in ('withdrawn', 'roster_changed', 'member_left', 'no_longer_fits')),
  expires_at timestamptz not null,
  created_at timestamptz not null default now(),
  accepted_at timestamptz,
  decided_at timestamptz,
  decided_by uuid references auth.users (id) on delete set null,
  constraint roster_swaps_two_people check (requester_id <> counterparty_id),
  constraint roster_swaps_two_shifts check (take_assignment_id is null or take_assignment_id <> give_assignment_id)
);
create unique index roster_swaps_live_give_idx on public.roster_swaps (give_assignment_id) where status in ('requested', 'accepted');
create unique index roster_swaps_live_take_idx on public.roster_swaps (take_assignment_id) where status in ('requested', 'accepted') and take_assignment_id is not null;
create index roster_swaps_service_idx on public.roster_swaps (service_id, status);
create index roster_swaps_requester_idx on public.roster_swaps (requester_id);
create index roster_swaps_counterparty_idx on public.roster_swaps (counterparty_id);

-- An open shift: a shift given away, a gap a manager posts, or "I can't make my shift"
-- (status 'reported' until the manager releases it). First eligible member to claim gets it.
create table public.roster_open_shifts (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services (id) on delete cascade,
  assignment_id uuid references public.roster_assignments (id) on delete cascade,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  shift_code text not null check (char_length(btrim(shift_code)) between 1 and 12),
  kind text not null check (kind in ('day', 'evening', 'night', 'on_call', 'other')),
  site_id uuid,
  min_grade text check (min_grade is null or min_grade in ('intern', 'resident', 'registrar', 'fellow', 'consultant')),
  urgent boolean not null default false,
  status text not null default 'open' check (status in ('reported', 'open', 'claimed', 'approved', 'cancelled', 'expired')),
  posted_by uuid references auth.users (id) on delete set null,
  claimed_by uuid references auth.users (id) on delete set null,
  claimed_at timestamptz,
  decided_by uuid references auth.users (id) on delete set null,
  decided_at timestamptz,
  created_at timestamptz not null default now(),
  foreign key (site_id, service_id) references public.on_call_service_sites (id, service_id) on delete set null (site_id),
  constraint roster_open_shifts_ends_after_start check (ends_at > starts_at),
  constraint roster_open_shifts_max_length check (ends_at - starts_at <= interval '36 hours')
);
create unique index roster_open_shifts_live_assignment_idx on public.roster_open_shifts (assignment_id)
  where status in ('reported', 'open', 'claimed') and assignment_id is not null;
create index roster_open_shifts_service_idx on public.roster_open_shifts (service_id, status, starts_at);

-- "Dates I can't work" for the next roster. No reason is ever stored.
create table public.roster_unavailability (
  service_id uuid not null,
  user_id uuid not null,
  on_date date not null,
  kind text not null check (kind in ('cant', 'prefer_off')),
  created_at timestamptz not null default now(),
  primary key (service_id, user_id, on_date),
  foreign key (service_id, user_id) references public.on_call_service_members (service_id, user_id) on delete cascade
);

-- The one planned-leave record (Admin reads it; leave is approved in the HR system).
-- Owner table: a doctor on their own can plan leave too. No reason is ever stored, only the kind.
create table public.roster_leave (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  service_id uuid references public.on_call_services (id) on delete set null,
  kind text not null check (kind in ('annual', 'pd_leave', 'exam', 'personal')),
  starts_on date not null,
  ends_on date not null,
  status text not null default 'planned' check (status in ('planned', 'applied', 'approved')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint roster_leave_dates check (ends_on >= starts_on and ends_on - starts_on <= 366)
);
create index roster_leave_owner_idx on public.roster_leave (owner_id, starts_on);
create index roster_leave_service_idx on public.roster_leave (service_id, starts_on) where service_id is not null;
create trigger roster_leave_updated_at before update on public.roster_leave
  for each row execute function public.set_updated_at();

-- Seen receipts (Josh, 18:44Z): written once when a doctor first opens a published roster,
-- readable only by that team's roster managers, deleted with the publication at 12 months.
create table public.roster_publication_seen (
  publication_id uuid not null references public.roster_publications (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  seen_at timestamptz not null default now(),
  primary key (publication_id, user_id)
);

-- =============================================================================================
-- D. Roster maker (Release 3)
-- =============================================================================================

create table public.roster_shift_codes (
  service_id uuid not null references public.on_call_services (id) on delete cascade,
  code text not null check (char_length(btrim(code)) between 1 and 12),
  kind text not null check (kind in ('day', 'evening', 'night', 'on_call', 'leave', 'other')),
  starts time,
  ends time,
  label text check (label is null or (btrim(label) <> '' and char_length(label) <= 40)),
  primary key (service_id, code),
  constraint roster_shift_codes_times check ((starts is null) = (ends is null))
);

create table public.roster_staffing_needs (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services (id) on delete cascade,
  weekday smallint check (weekday is null or weekday between 1 and 7),
  on_date date,
  kind text not null check (kind in ('day', 'evening', 'night', 'on_call', 'other')),
  grade text check (grade is null or grade in ('intern', 'resident', 'registrar', 'fellow', 'consultant')),
  site_id uuid,
  needed smallint not null check (needed between 0 and 200),
  foreign key (site_id, service_id) references public.on_call_service_sites (id, service_id) on delete cascade,
  constraint roster_staffing_needs_day check ((weekday is null) <> (on_date is null))
);
create index roster_staffing_needs_service_idx on public.roster_staffing_needs (service_id);

-- One draft per team and period, sitting beside the published roster.
create table public.roster_drafts (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services (id) on delete cascade,
  period_start date not null,
  period_end date not null,
  based_on_publication_id uuid references public.roster_publications (id) on delete set null,
  created_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (service_id, period_start, period_end),
  constraint roster_drafts_period check (period_end >= period_start and period_end - period_start <= 186)
);
create trigger roster_drafts_updated_at before update on public.roster_drafts
  for each row execute function public.set_updated_at();

create table public.roster_draft_assignments (
  id uuid primary key default gen_random_uuid(),
  draft_id uuid not null references public.roster_drafts (id) on delete cascade,
  user_id uuid references auth.users (id) on delete set null,
  roster_name text check (roster_name is null or (btrim(roster_name) <> '' and char_length(roster_name) <= 80)),
  site_id uuid,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  shift_code text not null check (char_length(btrim(shift_code)) between 1 and 12),
  kind text not null check (kind in ('day', 'evening', 'night', 'on_call', 'leave', 'other')),
  grade text check (grade is null or grade in ('intern', 'resident', 'registrar', 'fellow', 'consultant', 'other')),
  constraint roster_draft_assignments_ends_after_start check (ends_at > starts_at),
  constraint roster_draft_assignments_max_length check (ends_at - starts_at <= interval '36 hours')
);
create index roster_draft_assignments_draft_idx on public.roster_draft_assignments (draft_id, starts_at);

-- Every change to a draft or the live roster, saved with its undo in the same statement.
-- Typed text is never stored: only the resulting change is.
create table public.roster_changes (
  id bigint generated always as identity primary key,
  service_id uuid not null references public.on_call_services (id) on delete cascade,
  draft_id uuid references public.roster_drafts (id) on delete cascade,
  target text not null check (target in ('draft', 'live')),
  source text not null check (source in ('typed', 'grid', 'upload', 'swap', 'open_shift', 'publish')),
  change jsonb not null check (jsonb_typeof(change) = 'object'),
  undo jsonb check (undo is null or jsonb_typeof(undo) = 'object'),
  actor_id uuid references auth.users (id) on delete set null,
  at timestamptz not null default now(),
  undone_at timestamptz,
  undone_by uuid references auth.users (id) on delete set null,
  agreement_required boolean not null default false,
  constraint roster_changes_draft_target check ((target = 'draft') = (draft_id is not null))
);
create index roster_changes_service_at_idx on public.roster_changes (service_id, at desc);
create index roster_changes_draft_idx on public.roster_changes (draft_id) where draft_id is not null;

-- A doctor's agreement to a change made after publishing (the award expects it; payroll needs it).
create table public.roster_change_agreements (
  change_id bigint not null references public.roster_changes (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade,
  agreed_at timestamptz not null default now(),
  primary key (change_id, user_id)
);

-- Tenancy for every table in this file.
do $tenancy$
declare t text;
begin
  foreach t in array array[
    'roster_calendar_links', 'web_push_subscriptions', 'roster_member_roles', 'roster_team_settings',
    'roster_publications', 'roster_assignments', 'roster_swaps', 'roster_open_shifts',
    'roster_unavailability', 'roster_leave', 'roster_publication_seen', 'roster_shift_codes',
    'roster_staffing_needs', 'roster_drafts', 'roster_draft_assignments', 'roster_changes',
    'roster_change_agreements'
  ] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from public, anon, authenticated', t);
    execute format('grant select, insert, update, delete on table public.%I to service_role', t);
  end loop;
end
$tenancy$;

-- =============================================================================================
-- E. Functions
-- =============================================================================================

-- A manager may invite, as member only (On Call's command enforces the member role and calls
-- this at join, through its run-time case statement).
create function public.roster_can_invite(p_service_id uuid, p_user_id uuid) returns boolean
language plpgsql stable security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  return public.service_member_active(p_service_id, p_user_id)
    and exists (
      select 1 from public.roster_member_roles
      where service_id = p_service_id and user_id = p_user_id and role = 'manager' and revoked_at is null
    );
end $$;

-- Revoke cascade (contract §10). The WHEN clause is required: a rejoin clears revoked_at and
-- must not re-revoke anything. Roles are not restored on rejoin; they are granted again.
create function public.roster_on_membership_revoked() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  update public.roster_member_roles set revoked_at = now()
   where service_id = new.service_id and user_id = new.user_id and revoked_at is null;
  if found then
    insert into public.on_call_service_member_events (service_id, user_id, event, mode, actor_id)
    values (new.service_id, new.user_id, 'revoked', 'roster', null);
  end if;
  update public.roster_swaps
     set status = 'cancelled', cancel_reason = 'member_left', decided_at = now()
   where service_id = new.service_id and status in ('requested', 'accepted')
     and (requester_id = new.user_id or counterparty_id = new.user_id);
  update public.roster_open_shifts
     set status = 'open', claimed_by = null, claimed_at = null
   where service_id = new.service_id and status = 'claimed' and claimed_by = new.user_id;
  delete from public.roster_unavailability where service_id = new.service_id and user_id = new.user_id;
  return null;
end $$;
create trigger roster_on_membership_revoked
  after update of revoked_at on public.on_call_service_members
  for each row when (old.revoked_at is null and new.revoked_at is not null)
  execute function public.roster_on_membership_revoked();

-- Own-shift import. Replaces only imported shifts of the same workplace inside the window
-- (Perth dates), records the import, keeps the 10 newest imports, all in one transaction.
create function public.roster_own_shifts_replace(
  p_owner_id uuid,
  p_window_start date,
  p_window_end date,
  p_format text,
  p_workplace text,
  p_file_name text,
  p_shifts jsonb,
  p_changes jsonb,
  p_added integer,
  p_changed integer,
  p_removed integer
) returns uuid
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_import uuid;
begin
  if p_owner_id is null or p_window_start is null or p_window_end is null
    or p_window_end < p_window_start or p_window_end - p_window_start > 400
    or p_shifts is null or jsonb_typeof(p_shifts) <> 'array' or jsonb_array_length(p_shifts) > 1000
    or p_changes is null or jsonb_typeof(p_changes) <> 'array' then
    raise exception 'on_call_shifts_invalid_request';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_owner_id::text, 74817));

  delete from public.on_call_shifts
  where owner_id = p_owner_id
    and source = 'import'
    and workplace is not distinct from p_workplace
    and (starts_at at time zone 'Australia/Perth')::date between p_window_start and p_window_end;

  insert into public.on_call_shifts (owner_id, starts_at, ends_at, title, location, source_uid, source, kind, workplace)
  select p_owner_id,
         (shift ->> 'startsAt')::timestamptz,
         (shift ->> 'endsAt')::timestamptz,
         shift ->> 'title',
         nullif(shift ->> 'location', ''),
         nullif(shift ->> 'sourceUid', ''),
         'import',
         nullif(shift ->> 'kind', ''),
         p_workplace
  from jsonb_array_elements(p_shifts) as shift;

  if (select count(*) from public.on_call_shifts where owner_id = p_owner_id) > 2000 then
    raise exception 'on_call_shifts_limit';
  end if;

  insert into public.on_call_shift_imports
    (owner_id, format, window_start, window_end, added, changed, removed, changes, workplace, file_name)
  values
    (p_owner_id, p_format, p_window_start, p_window_end, p_added, p_changed, p_removed, p_changes, p_workplace, p_file_name)
  returning id into v_import;

  delete from public.on_call_shift_imports
  where owner_id = p_owner_id
    and id not in (
      select id from public.on_call_shift_imports
      where owner_id = p_owner_id
      order by imported_at desc, id desc
      limit 10
    );

  return v_import;
end $$;

-- Grade order for swap and open-shift eligibility: a more senior doctor may take a junior's
-- shift, never the other way round. 'other' and unknown grades are left out of matching.
create function public.roster_grade_rank(p_grade text) returns integer
language sql immutable security invoker set search_path = public, pg_catalog, pg_temp as $$
  select case p_grade
    when 'intern' then 1 when 'resident' then 2 when 'registrar' then 3
    when 'fellow' then 4 when 'consultant' then 5 else null end
$$;

-- Would putting p_user_id on [p_starts, p_ends) clash with their other live shifts in this
-- team, or leave a break shorter than the team's rule? Team roster only: a colleague's other
-- job or personal shifts are never read. Returns null, 'clash' or 'short_break'.
create function public.roster_placement_problem(
  p_service_id uuid,
  p_user_id uuid,
  p_starts timestamptz,
  p_ends timestamptz,
  p_exclude uuid[],
  p_min_break_hours numeric
) returns text
language plpgsql stable security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  if exists (
    select 1 from public.roster_assignments a
    where a.service_id = p_service_id and a.user_id = p_user_id and a.superseded_at is null
      and a.kind <> 'leave' and not (a.id = any (coalesce(array_remove(p_exclude, null), '{}')))
      and a.starts_at < p_ends and a.ends_at > p_starts
  ) or exists (
    select 1 from public.roster_assignments a
    where a.service_id = p_service_id and a.user_id = p_user_id and a.superseded_at is null
      and a.kind = 'leave' and a.starts_at < p_ends and a.ends_at > p_starts
  ) then
    return 'clash';
  end if;
  if p_min_break_hours is not null and exists (
    select 1 from public.roster_assignments a
    where a.service_id = p_service_id and a.user_id = p_user_id and a.superseded_at is null
      and a.kind not in ('leave', 'on_call') and not (a.id = any (coalesce(array_remove(p_exclude, null), '{}')))
      and (
        (a.ends_at <= p_starts and p_starts - a.ends_at < make_interval(secs => p_min_break_hours * 3600))
        or (a.starts_at >= p_ends and a.starts_at - p_ends < make_interval(secs => p_min_break_hours * 3600))
      )
  ) then
    return 'short_break';
  end if;
  return null;
end $$;

-- The name colleagues see: the member's own display name, else the printed roster name.
create function public.roster_person_name(p_service_id uuid, p_user_id uuid, p_roster_name text) returns text
language sql stable security invoker set search_path = public, pg_catalog, pg_temp as $$
  select coalesce(
    (select m.display_name from public.on_call_service_members m
      where m.service_id = p_service_id and m.user_id = p_user_id),
    (select r.roster_name from public.roster_member_roles r
      where r.service_id = p_service_id and r.user_id = p_user_id and r.revoked_at is null),
    p_roster_name
  )
$$;

-- One assignment as members see it. No other personal field is ever returned.
create function public.roster_assignment_json(a public.roster_assignments) returns jsonb
language sql stable security invoker set search_path = public, pg_catalog, pg_temp as $$
  select jsonb_build_object(
    'id', a.id, 'userId', a.user_id,
    'name', public.roster_person_name(a.service_id, a.user_id, a.roster_name),
    'grade', coalesce(a.grade, (select r.grade from public.roster_member_roles r
                                where r.service_id = a.service_id and r.user_id = a.user_id and r.revoked_at is null)),
    'siteId', a.site_id,
    'siteName', (select s.name from public.on_call_service_sites s where s.id = a.site_id),
    'startsAt', a.starts_at, 'endsAt', a.ends_at, 'shiftCode', a.shift_code, 'kind', a.kind
  )
$$;

-- Everything a team page reads, checked in SQL against the actor's membership and role.
create function public.roster_read(p_actor_id uuid, p_service_id uuid, p_what text, p_payload jsonb default '{}')
returns jsonb
language plpgsql stable security invoker set search_path = public, pg_catalog, pg_temp as $$
declare
  v_service public.on_call_services;
  v_role public.roster_member_roles;
  v_is_manager boolean;
  v_from date;
  v_to date;
  v_latest public.roster_publications;
  v_result jsonb;
begin
  if p_actor_id is null then raise exception 'roster_auth_required'; end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then raise exception 'roster_invalid_request'; end if;

  if p_what = 'teams' then
    select coalesce(jsonb_agg(jsonb_build_object(
      'serviceId', s.id, 'name', s.name,
      'enabled', (s.verified_at is not null or s.is_demo),
      'role', coalesce(r.role, 'member'), 'grade', r.grade
    ) order by s.name), '[]') into v_result
    from public.on_call_services s
    join public.on_call_service_members m on m.service_id = s.id and m.user_id = p_actor_id and m.revoked_at is null
    left join public.roster_member_roles r on r.service_id = s.id and r.user_id = p_actor_id and r.revoked_at is null;
    return jsonb_build_object('teams', v_result);
  end if;

  select * into v_service from public.on_call_services where id = p_service_id;
  if not found or not public.service_member_active(p_service_id, p_actor_id) then
    raise exception 'roster_access_denied';
  end if;
  if v_service.verified_at is null and not v_service.is_demo then raise exception 'roster_team_not_verified'; end if;
  select * into v_role from public.roster_member_roles
   where service_id = p_service_id and user_id = p_actor_id and revoked_at is null;
  v_is_manager := found and v_role.role = 'manager';
  select * into v_latest from public.roster_publications
   where service_id = p_service_id order by version desc limit 1;

  if p_what in ('assignments', 'unavailability', 'leave_overlap', 'changes') then
    begin
      v_from := (p_payload ->> 'from')::date;
      v_to := (p_payload ->> 'to')::date;
    exception when others then raise exception 'roster_invalid_request';
    end;
    if v_from is null or v_to is null or v_to < v_from or v_to - v_from > 62 then
      raise exception 'roster_invalid_request';
    end if;
  end if;

  if p_what = 'overview' then
    return jsonb_build_object(
      'service', jsonb_build_object('id', v_service.id, 'name', v_service.name),
      'me', jsonb_build_object('role', coalesce(v_role.role, 'member'), 'grade', v_role.grade,
                               'rotationEndsOn', v_role.rotation_ends_on),
      'latestPublication', case when v_latest.id is null then null else jsonb_build_object(
        'id', v_latest.id, 'version', v_latest.version, 'publishedAt', v_latest.published_at,
        'periodStart', v_latest.period_start, 'periodEnd', v_latest.period_end) end,
      'seenLatest', v_latest.id is not null and exists (
        select 1 from public.roster_publication_seen where publication_id = v_latest.id and user_id = p_actor_id),
      'settings', coalesce((select jsonb_build_object('swapApproval', t.swap_approval, 'rules', t.rules,
        'rulesSource', t.rules_source, 'payFortnightAnchor', t.pay_fortnight_anchor)
        from public.roster_team_settings t where t.service_id = p_service_id),
        jsonb_build_object('swapApproval', 'auto_same_grade', 'rules', '{}'::jsonb, 'rulesSource', null, 'payFortnightAnchor', null)),
      'sites', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'name', s.name) order by s.name), '[]')
                from public.on_call_service_sites s where s.service_id = p_service_id)
    );

  elsif p_what = 'assignments' then
    select coalesce(jsonb_agg(public.roster_assignment_json(a) order by a.starts_at, a.id), '[]') into v_result
    from public.roster_assignments a
    where a.service_id = p_service_id and a.superseded_at is null
      and (a.starts_at at time zone 'Australia/Perth')::date between v_from and v_to;
    return jsonb_build_object('assignments', v_result);

  elsif p_what = 'requests' then
    return jsonb_build_object(
      'swaps', (select coalesce(jsonb_agg(jsonb_build_object(
          'id', w.id, 'status', w.status, 'autoApproved', w.auto_approved,
          'needsManagerBecause', w.needs_manager_because, 'cancelReason', w.cancel_reason,
          'requesterId', w.requester_id, 'counterpartyId', w.counterparty_id,
          'give', (select public.roster_assignment_json(a) from public.roster_assignments a where a.id = w.give_assignment_id),
          'take', (select public.roster_assignment_json(a) from public.roster_assignments a where a.id = w.take_assignment_id),
          'expiresAt', w.expires_at, 'createdAt', w.created_at, 'decidedAt', w.decided_at
        ) order by w.created_at desc), '[]')
        from public.roster_swaps w
        where w.service_id = p_service_id and (w.requester_id = p_actor_id or w.counterparty_id = p_actor_id)
          and w.created_at > now() - interval '60 days'),
      'openShifts', (select coalesce(jsonb_agg(jsonb_build_object(
          'id', o.id, 'status', o.status, 'urgent', o.urgent, 'startsAt', o.starts_at, 'endsAt', o.ends_at,
          'shiftCode', o.shift_code, 'kind', o.kind, 'minGrade', o.min_grade, 'siteId', o.site_id,
          'mine', o.posted_by = p_actor_id, 'claimedByMe', o.claimed_by = p_actor_id
        ) order by o.starts_at), '[]')
        from public.roster_open_shifts o
        where o.service_id = p_service_id and o.ends_at > now()
          and (o.posted_by = p_actor_id or o.claimed_by = p_actor_id
               or (o.status = 'open' and (o.min_grade is null
                   or public.roster_grade_rank(v_role.grade) >= public.roster_grade_rank(o.min_grade)))))
    );

  elsif p_what = 'unavailability' then
    select coalesce(jsonb_agg(jsonb_build_object('userId', u.user_id, 'date', u.on_date, 'kind', u.kind)
           order by u.on_date, u.user_id), '[]') into v_result
    from public.roster_unavailability u
    where u.service_id = p_service_id and u.on_date between v_from and v_to
      and (v_is_manager or u.user_id = p_actor_id);
    return jsonb_build_object('unavailability', v_result);

  elsif p_what = 'leave_overlap' then
    -- A number only, never names.
    return jsonb_build_object('alreadyOff', (
      select count(distinct l.owner_id) from public.roster_leave l
      where l.service_id = p_service_id and l.owner_id <> p_actor_id
        and public.service_member_active(p_service_id, l.owner_id)
        and l.starts_on <= v_to and l.ends_on >= v_from));

  elsif p_what = 'manage' then
    if not v_is_manager then raise exception 'roster_role_denied'; end if;
    return jsonb_build_object(
      'swaps', (select coalesce(jsonb_agg(jsonb_build_object(
          'id', w.id, 'status', w.status, 'autoApproved', w.auto_approved,
          'needsManagerBecause', w.needs_manager_because,
          'requesterId', w.requester_id, 'counterpartyId', w.counterparty_id,
          'give', (select public.roster_assignment_json(a) from public.roster_assignments a where a.id = w.give_assignment_id),
          'take', (select public.roster_assignment_json(a) from public.roster_assignments a where a.id = w.take_assignment_id),
          'decidedAt', w.decided_at
        ) order by w.created_at), '[]')
        from public.roster_swaps w
        where w.service_id = p_service_id
          and (w.status = 'accepted' or (w.auto_approved and w.decided_at > now() - interval '14 days'))),
      'openShifts', (select coalesce(jsonb_agg(jsonb_build_object(
          'id', o.id, 'status', o.status, 'urgent', o.urgent, 'startsAt', o.starts_at, 'endsAt', o.ends_at,
          'shiftCode', o.shift_code, 'kind', o.kind, 'minGrade', o.min_grade, 'siteId', o.site_id,
          'postedBy', o.posted_by, 'claimedBy', o.claimed_by, 'claimedAt', o.claimed_at
        ) order by o.starts_at), '[]')
        from public.roster_open_shifts o
        where o.service_id = p_service_id and o.status in ('reported', 'open', 'claimed') and o.ends_at > now()),
      'seen', case when v_latest.id is null then null else jsonb_build_object(
          'publicationId', v_latest.id, 'version', v_latest.version,
          'seen', (select count(*) from public.roster_publication_seen x
                   where x.publication_id = v_latest.id and public.service_member_active(p_service_id, x.user_id)),
          'members', (select count(*) from public.on_call_service_members m
                      where m.service_id = p_service_id and m.revoked_at is null),
          'notSeen', (select coalesce(jsonb_agg(m.user_id), '[]') from public.on_call_service_members m
                      where m.service_id = p_service_id and m.revoked_at is null
                        and not exists (select 1 from public.roster_publication_seen x
                                        where x.publication_id = v_latest.id and x.user_id = m.user_id))) end
    );

  elsif p_what = 'people' then
    if not v_is_manager then raise exception 'roster_role_denied'; end if;
    select coalesce(jsonb_agg(jsonb_build_object(
      'userId', m.user_id, 'displayName', m.display_name, 'joinedAt', m.joined_at, 'serviceRole', m.role,
      'role', coalesce(r.role, 'member'), 'grade', r.grade, 'rosterName', r.roster_name,
      'rotationEndsOn', r.rotation_ends_on
    ) order by coalesce(m.display_name, r.roster_name), m.joined_at), '[]') into v_result
    from public.on_call_service_members m
    left join public.roster_member_roles r on r.service_id = m.service_id and r.user_id = m.user_id and r.revoked_at is null
    where m.service_id = p_service_id and m.revoked_at is null;
    return jsonb_build_object('people', v_result);

  elsif p_what = 'publications' then
    if not v_is_manager then raise exception 'roster_role_denied'; end if;
    select coalesce(jsonb_agg(jsonb_build_object(
      'id', p.id, 'version', p.version, 'kind', p.kind, 'periodStart', p.period_start, 'periodEnd', p.period_end,
      'sourceName', p.source_name, 'publishedAt', p.published_at
    ) order by p.version desc), '[]') into v_result
    from (select * from public.roster_publications where service_id = p_service_id order by version desc limit 50) p;
    return jsonb_build_object('publications', v_result);

  elsif p_what = 'maker' then
    if not v_is_manager then raise exception 'roster_role_denied'; end if;
    return jsonb_build_object(
      'codes', (select coalesce(jsonb_agg(jsonb_build_object('code', c.code, 'kind', c.kind, 'starts', c.starts,
                'ends', c.ends, 'label', c.label) order by c.code), '[]')
                from public.roster_shift_codes c where c.service_id = p_service_id),
      'needs', (select coalesce(jsonb_agg(jsonb_build_object('id', n.id, 'weekday', n.weekday, 'date', n.on_date,
                'kind', n.kind, 'grade', n.grade, 'siteId', n.site_id, 'needed', n.needed)), '[]')
                from public.roster_staffing_needs n where n.service_id = p_service_id),
      'drafts', (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'periodStart', d.period_start,
                'periodEnd', d.period_end, 'basedOnPublicationId', d.based_on_publication_id, 'updatedAt', d.updated_at)
                order by d.period_start), '[]')
                from public.roster_drafts d where d.service_id = p_service_id)
    );

  elsif p_what = 'draft' then
    if not v_is_manager then raise exception 'roster_role_denied'; end if;
    if not exists (select 1 from public.roster_drafts d
                   where d.id = (p_payload ->> 'draftId')::uuid and d.service_id = p_service_id) then
      raise exception 'roster_not_found';
    end if;
    return jsonb_build_object(
      'assignments', (select coalesce(jsonb_agg(jsonb_build_object(
          'id', a.id, 'userId', a.user_id, 'name', public.roster_person_name(p_service_id, a.user_id, a.roster_name),
          'siteId', a.site_id, 'startsAt', a.starts_at, 'endsAt', a.ends_at, 'shiftCode', a.shift_code,
          'kind', a.kind, 'grade', a.grade) order by a.starts_at, a.id), '[]')
        from public.roster_draft_assignments a where a.draft_id = (p_payload ->> 'draftId')::uuid),
      'changes', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'source', c.source, 'change', c.change,
          'at', c.at, 'actorId', c.actor_id, 'undoneAt', c.undone_at) order by c.id desc), '[]')
        from (select * from public.roster_changes where draft_id = (p_payload ->> 'draftId')::uuid
              order by id desc limit 100) c)
    );
  end if;

  raise exception 'roster_invalid_request';
end $$;

-- Every team write. Lock order, the same for every mode: the service row FOR SHARE, then this
-- mode's per-service advisory lock (74817), then target rows FOR UPDATE.
create function public.roster_command(p_actor_id uuid, p_service_id uuid, p_action text, p_payload jsonb default '{}')
returns jsonb
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare
  v_service public.on_call_services;
  v_role public.roster_member_roles;
  v_is_manager boolean;
  v_settings public.roster_team_settings;
  v_min_break numeric;
  v_pub public.roster_publications;
  v_swap public.roster_swaps;
  v_open public.roster_open_shifts;
  v_give public.roster_assignments;
  v_take public.roster_assignments;
  v_draft public.roster_drafts;
  v_row jsonb;
  v_id uuid;
  v_change_id bigint;
  v_count integer;
  v_ids uuid[];
  v_problem text;
  v_reason text;
  v_giver_rank integer;
  v_taker_rank integer;
  v_result jsonb;
  v_from date;
  v_to date;
begin
  if p_actor_id is null then raise exception 'roster_auth_required'; end if;
  if p_service_id is null or p_action is null then raise exception 'roster_invalid_request'; end if;
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then raise exception 'roster_invalid_request'; end if;

  -- Removing a member changes membership, so it takes the service row FOR UPDATE, as On Call
  -- does; every other action takes it FOR SHARE. Never upgrade a lock mid-call.
  if p_action = 'member.remove' then
    select * into v_service from public.on_call_services where id = p_service_id for update;
  else
    select * into v_service from public.on_call_services where id = p_service_id for share;
  end if;
  if not found or not public.service_member_active(p_service_id, p_actor_id) then
    raise exception 'roster_access_denied';
  end if;
  if v_service.verified_at is null and not v_service.is_demo then raise exception 'roster_team_not_verified'; end if;

  -- Seen receipts are a check-in: the share lock is enough, and they never wait on other writes.
  if p_action = 'seen.mark' then
    select * into v_pub from public.roster_publications
     where service_id = p_service_id and id = (p_payload ->> 'publicationId')::uuid;
    if not found then raise exception 'roster_not_found'; end if;
    insert into public.roster_publication_seen (publication_id, user_id) values (v_pub.id, p_actor_id)
      on conflict do nothing;
    return jsonb_build_object('ok', true);
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_service_id::text, 74817));

  select * into v_role from public.roster_member_roles
   where service_id = p_service_id and user_id = p_actor_id and revoked_at is null;
  v_is_manager := found and v_role.role = 'manager';
  select * into v_settings from public.roster_team_settings where service_id = p_service_id;
  v_min_break := nullif(v_settings.rules ->> 'minBreakHours', '')::numeric;

  -- ---------------------------------------------------------------- people and settings
  if p_action = 'role.set' then
    if not v_is_manager then raise exception 'roster_role_denied'; end if;
    v_id := (p_payload ->> 'userId')::uuid;
    if v_id is null or not public.service_member_active(p_service_id, v_id) then raise exception 'roster_not_found'; end if;
    if p_payload ? 'grade' and p_payload ->> 'grade' is not null
       and p_payload ->> 'grade' not in ('intern', 'resident', 'registrar', 'fellow', 'consultant', 'other') then
      raise exception 'roster_invalid_request';
    end if;
    insert into public.roster_member_roles (service_id, user_id, role, grade, roster_name, rotation_ends_on, granted_by)
    values (p_service_id, v_id, 'member', p_payload ->> 'grade', nullif(btrim(p_payload ->> 'rosterName'), ''),
            (p_payload ->> 'rotationEndsOn')::date, p_actor_id)
    on conflict (service_id, user_id) do update set
      grade = case when p_payload ? 'grade' then excluded.grade else public.roster_member_roles.grade end,
      roster_name = case when p_payload ? 'rosterName' then excluded.roster_name else public.roster_member_roles.roster_name end,
      rotation_ends_on = case when p_payload ? 'rotationEndsOn' then excluded.rotation_ends_on else public.roster_member_roles.rotation_ends_on end,
      role = case when public.roster_member_roles.revoked_at is null then public.roster_member_roles.role else 'member' end,
      revoked_at = null;
    return jsonb_build_object('ok', true);

  elsif p_action = 'member.remove' then
    -- Someone who leaves the team. Only ordinary service members; editors and admins are
    -- removed in On Call by a service admin. Revoking fires every mode's cascade trigger.
    if not v_is_manager then raise exception 'roster_role_denied'; end if;
    v_id := (p_payload ->> 'userId')::uuid;
    if v_id is null or v_id = p_actor_id then raise exception 'roster_invalid_request'; end if;
    update public.on_call_service_members set revoked_at = now(), clinical_reviewer = false
     where service_id = p_service_id and user_id = v_id and revoked_at is null and role = 'member';
    if not found then raise exception 'roster_not_found'; end if;
    insert into public.on_call_service_member_events (service_id, user_id, event, mode, actor_id)
    values (p_service_id, v_id, 'revoked', null, p_actor_id);
    return jsonb_build_object('ok', true);

  elsif p_action = 'settings.set' then
    if not v_is_manager then raise exception 'roster_role_denied'; end if;
    insert into public.roster_team_settings (service_id, swap_approval, rules, rules_source, pay_fortnight_anchor, updated_by)
    values (p_service_id,
            coalesce(p_payload ->> 'swapApproval', 'auto_same_grade'),
            coalesce(p_payload -> 'rules', '{}'::jsonb),
            nullif(btrim(p_payload ->> 'rulesSource'), ''),
            (p_payload ->> 'payFortnightAnchor')::date,
            p_actor_id)
    on conflict (service_id) do update set
      swap_approval = excluded.swap_approval, rules = excluded.rules, rules_source = excluded.rules_source,
      pay_fortnight_anchor = excluded.pay_fortnight_anchor, updated_by = excluded.updated_by;
    return jsonb_build_object('ok', true);

  elsif p_action = 'unavailability.set' then
    -- payload {set: [{date, kind}], clear: [date]} for the actor only, future dates only.
    delete from public.roster_unavailability
     where service_id = p_service_id and user_id = p_actor_id
       and on_date in (select (value #>> '{}')::date from jsonb_array_elements(coalesce(p_payload -> 'clear', '[]')));
    insert into public.roster_unavailability (service_id, user_id, on_date, kind)
    select p_service_id, p_actor_id, (value ->> 'date')::date, value ->> 'kind'
    from jsonb_array_elements(coalesce(p_payload -> 'set', '[]'))
    where (value ->> 'date')::date > (now() at time zone 'Australia/Perth')::date
    on conflict (service_id, user_id, on_date) do update set kind = excluded.kind;
    if (select count(*) from public.roster_unavailability where service_id = p_service_id and user_id = p_actor_id) > 120 then
      raise exception 'roster_limit';
    end if;
    return jsonb_build_object('ok', true);

  -- ---------------------------------------------------------------- publishing
  elsif p_action = 'publish' then
    -- payload {kind, periodStart, periodEnd, sourceName?, replaceAssignmentIds?[], assignments[], draftId?}
    -- The app has already settled rows it couldn't match and approved swaps the file would undo;
    -- this step is all or nothing.
    if not v_is_manager then raise exception 'roster_role_denied'; end if;
    v_from := (p_payload ->> 'periodStart')::date;
    v_to := (p_payload ->> 'periodEnd')::date;
    if v_from is null or v_to is null or jsonb_typeof(p_payload -> 'assignments') is distinct from 'array'
       or jsonb_array_length(p_payload -> 'assignments') > 5000
       or coalesce(p_payload ->> 'kind', 'full') not in ('full', 'single_change') then
      raise exception 'roster_invalid_request';
    end if;
    if exists (
      select 1 from jsonb_array_elements(p_payload -> 'assignments') x
      where (x ->> 'userId') is not null
        and not public.service_member_active(p_service_id, (x ->> 'userId')::uuid)
    ) or exists (
      select 1 from jsonb_array_elements(p_payload -> 'assignments') x
      where (x ->> 'userId') is null and nullif(btrim(x ->> 'rosterName'), '') is null
    ) or exists (
      select 1 from jsonb_array_elements(p_payload -> 'assignments') x
      where ((x ->> 'startsAt')::timestamptz at time zone 'Australia/Perth')::date not between v_from and v_to
    ) then
      raise exception 'roster_invalid_request';
    end if;

    insert into public.roster_publications (service_id, version, kind, period_start, period_end, source_name, published_by)
    values (p_service_id,
            coalesce((select max(version) from public.roster_publications where service_id = p_service_id), 0) + 1,
            coalesce(p_payload ->> 'kind', 'full'), v_from, v_to, nullif(btrim(p_payload ->> 'sourceName'), ''), p_actor_id)
    returning * into v_pub;

    if v_pub.kind = 'full' then
      with replaced as (
        update public.roster_assignments set superseded_at = now()
         where service_id = p_service_id and superseded_at is null
           and (starts_at at time zone 'Australia/Perth')::date between v_from and v_to
        returning id
      )
      select coalesce(array_agg(id), '{}') into v_ids from replaced;
    else
      select coalesce(array_agg((value #>> '{}')::uuid), '{}') into v_ids
        from jsonb_array_elements(coalesce(p_payload -> 'replaceAssignmentIds', '[]'));
      update public.roster_assignments set superseded_at = now()
       where service_id = p_service_id and superseded_at is null and id = any (v_ids);
      get diagnostics v_count = row_count;
      if v_count <> coalesce(array_length(v_ids, 1), 0) then raise exception 'roster_conflict'; end if;
    end if;

    insert into public.roster_assignments (service_id, publication_id, user_id, roster_name, site_id, starts_at, ends_at, shift_code, kind, grade)
    select p_service_id, v_pub.id, (x ->> 'userId')::uuid, nullif(btrim(x ->> 'rosterName'), ''), (x ->> 'siteId')::uuid,
           (x ->> 'startsAt')::timestamptz, (x ->> 'endsAt')::timestamptz, btrim(x ->> 'shiftCode'), x ->> 'kind', x ->> 'grade'
    from jsonb_array_elements(p_payload -> 'assignments') x;

    -- Pending requests on replaced shifts cancel themselves and say why.
    with cancelled as (
      update public.roster_swaps set status = 'cancelled', cancel_reason = 'roster_changed', decided_at = now()
       where service_id = p_service_id and status in ('requested', 'accepted')
         and (give_assignment_id = any (v_ids) or take_assignment_id = any (v_ids))
      returning id, requester_id, counterparty_id
    )
    select jsonb_build_object('swapsCancelled', coalesce(jsonb_agg(jsonb_build_object(
      'id', id, 'requesterId', requester_id, 'counterpartyId', counterparty_id)), '[]')) into v_result from cancelled;
    update public.roster_open_shifts set status = 'cancelled', decided_at = now()
     where service_id = p_service_id and status in ('reported', 'open', 'claimed') and assignment_id = any (v_ids);

    insert into public.roster_changes (service_id, target, source, change, actor_id)
    values (p_service_id, 'live', 'publish',
            jsonb_build_object('kind', 'publish', 'publicationId', v_pub.id, 'version', v_pub.version,
                               'replaced', coalesce(array_length(v_ids, 1), 0),
                               'rows', jsonb_array_length(p_payload -> 'assignments')),
            p_actor_id);
    -- The manager has seen their own roster.
    insert into public.roster_publication_seen (publication_id, user_id) values (v_pub.id, p_actor_id);
    if p_payload ? 'draftId' then
      delete from public.roster_drafts where id = (p_payload ->> 'draftId')::uuid and service_id = p_service_id;
    end if;
    return v_result || jsonb_build_object('publicationId', v_pub.id, 'version', v_pub.version);

  -- ---------------------------------------------------------------- swaps
  elsif p_action in ('swap.create', 'swap.accept', 'swap.approve') then
    if p_action = 'swap.create' then
      select * into v_give from public.roster_assignments
       where id = (p_payload ->> 'giveAssignmentId')::uuid and service_id = p_service_id and superseded_at is null for update;
      if not found or v_give.user_id is distinct from p_actor_id or v_give.starts_at <= now() or v_give.kind = 'leave' then
        raise exception 'roster_not_found';
      end if;
      v_id := (p_payload ->> 'counterpartyId')::uuid;
      if v_id is null or v_id = p_actor_id or not public.service_member_active(p_service_id, v_id) then
        raise exception 'roster_not_found';
      end if;
      if p_payload ->> 'takeAssignmentId' is not null then
        select * into v_take from public.roster_assignments
         where id = (p_payload ->> 'takeAssignmentId')::uuid and service_id = p_service_id and superseded_at is null for update;
        if not found or v_take.user_id is distinct from v_id or v_take.starts_at <= now() or v_take.kind = 'leave' then
          raise exception 'roster_not_found';
        end if;
      end if;
      if exists (select 1 from public.roster_swaps w where w.status in ('requested', 'accepted')
                 and (w.give_assignment_id in (v_give.id, v_take.id) or w.take_assignment_id in (v_give.id, v_take.id)))
         or exists (select 1 from public.roster_open_shifts o where o.status in ('reported', 'open', 'claimed')
                 and o.assignment_id in (v_give.id, v_take.id)) then
        raise exception 'roster_request_exists';
      end if;
      insert into public.roster_swaps (service_id, requester_id, counterparty_id, give_assignment_id, take_assignment_id, expires_at)
      values (p_service_id, p_actor_id, v_id, v_give.id, v_take.id,
              least(v_give.starts_at, coalesce(v_take.starts_at, v_give.starts_at), now() + interval '7 days'))
      returning * into v_swap;
    else
      select * into v_swap from public.roster_swaps
       where id = (p_payload ->> 'swapId')::uuid and service_id = p_service_id for update;
      if not found then raise exception 'roster_not_found'; end if;
      if p_action = 'swap.accept' and (v_swap.counterparty_id <> p_actor_id or v_swap.status <> 'requested') then
        raise exception 'roster_not_found';
      end if;
      if p_action = 'swap.approve' and (not v_is_manager or v_swap.status <> 'accepted') then
        raise exception 'roster_role_denied';
      end if;
      -- A manager never approves a swap they are part of.
      if p_action = 'swap.approve' and p_actor_id in (v_swap.requester_id, v_swap.counterparty_id) then
        raise exception 'roster_role_denied';
      end if;
      if v_swap.expires_at <= now() then
        update public.roster_swaps set status = 'expired', decided_at = now() where id = v_swap.id;
        return jsonb_build_object('swapId', v_swap.id, 'status', 'expired');
      end if;
      select * into v_give from public.roster_assignments where id = v_swap.give_assignment_id for update;
      select * into v_take from public.roster_assignments where id = v_swap.take_assignment_id for update;
    end if;

    -- Recheck at every step: still live, still theirs, still eligible, still fits.
    v_reason := null;
    if v_give.superseded_at is not null or v_give.user_id is distinct from v_swap.requester_id
       or (v_swap.take_assignment_id is not null
           and (v_take.superseded_at is not null or v_take.user_id is distinct from v_swap.counterparty_id)) then
      v_reason := 'roster_changed';
    else
      v_giver_rank := public.roster_grade_rank(coalesce(v_give.grade,
        (select grade from public.roster_member_roles where service_id = p_service_id and user_id = v_swap.requester_id and revoked_at is null)));
      v_taker_rank := public.roster_grade_rank(
        (select grade from public.roster_member_roles where service_id = p_service_id and user_id = v_swap.counterparty_id and revoked_at is null));
      if v_giver_rank is null or v_taker_rank is null or v_taker_rank < v_giver_rank then
        v_reason := 'no_longer_fits';
      elsif v_swap.take_assignment_id is not null and (
          public.roster_grade_rank(coalesce(v_take.grade,
            (select grade from public.roster_member_roles where service_id = p_service_id and user_id = v_swap.counterparty_id and revoked_at is null)))
          > public.roster_grade_rank(
            (select grade from public.roster_member_roles where service_id = p_service_id and user_id = v_swap.requester_id and revoked_at is null))
          or public.roster_grade_rank(
            (select grade from public.roster_member_roles where service_id = p_service_id and user_id = v_swap.requester_id and revoked_at is null)) is null) then
        v_reason := 'no_longer_fits';
      elsif public.roster_placement_problem(p_service_id, v_swap.counterparty_id, v_give.starts_at, v_give.ends_at,
              array[v_take.id], null) = 'clash'
         or (v_swap.take_assignment_id is not null and public.roster_placement_problem(p_service_id, v_swap.requester_id,
              v_take.starts_at, v_take.ends_at, array[v_give.id], null) = 'clash') then
        v_reason := 'no_longer_fits';
      end if;
    end if;
    if v_reason is not null then
      if p_action = 'swap.create' then raise exception 'roster_swap_not_eligible'; end if;
      update public.roster_swaps set status = 'cancelled', cancel_reason = v_reason, decided_at = now() where id = v_swap.id;
      return jsonb_build_object('swapId', v_swap.id, 'status', 'cancelled', 'cancelReason', v_reason);
    end if;
    if p_action = 'swap.create' then
      return jsonb_build_object('swapId', v_swap.id, 'status', 'requested');
    end if;

    if p_action = 'swap.accept' then
      -- Does it need the manager? Team setting, then within 7 days, then grade, then team rule.
      v_reason := case
        when coalesce(v_settings.swap_approval, 'auto_same_grade') = 'manager' then 'team_setting'
        when least(v_give.starts_at, coalesce(v_take.starts_at, v_give.starts_at)) < now() + interval '7 days' then 'within_7_days'
        when v_taker_rank <> v_giver_rank then 'different_grade'
        when public.roster_placement_problem(p_service_id, v_swap.counterparty_id, v_give.starts_at, v_give.ends_at, array[v_take.id], v_min_break) is not null
          or (v_swap.take_assignment_id is not null and public.roster_placement_problem(p_service_id, v_swap.requester_id,
                v_take.starts_at, v_take.ends_at, array[v_give.id], v_min_break) is not null) then 'team_rule'
        else null end;
      if v_reason is not null then
        update public.roster_swaps set status = 'accepted', accepted_at = now(), needs_manager_because = v_reason
         where id = v_swap.id;
        return jsonb_build_object('swapId', v_swap.id, 'status', 'accepted', 'needsManagerBecause', v_reason);
      end if;
    end if;

    -- Apply: both shifts change hands together, with the undo saved in the same step.
    update public.roster_assignments set user_id = v_swap.counterparty_id, roster_name = null where id = v_give.id;
    if v_swap.take_assignment_id is not null then
      update public.roster_assignments set user_id = v_swap.requester_id, roster_name = null where id = v_take.id;
    end if;
    update public.roster_swaps
       set status = 'approved', auto_approved = (p_action = 'swap.accept'),
           accepted_at = coalesce(accepted_at, now()), decided_at = now(),
           decided_by = case when p_action = 'swap.approve' then p_actor_id else null end
     where id = v_swap.id;
    insert into public.roster_changes (service_id, target, source, change, undo, actor_id)
    values (p_service_id, 'live', 'swap',
            jsonb_build_object('kind', 'swap', 'swapId', v_swap.id),
            jsonb_build_object('assignments', jsonb_build_array(
              jsonb_build_object('id', v_give.id, 'userId', v_give.user_id, 'rosterName', v_give.roster_name))
              || case when v_take.id is null then '[]'::jsonb else jsonb_build_array(
              jsonb_build_object('id', v_take.id, 'userId', v_take.user_id, 'rosterName', v_take.roster_name)) end),
            p_actor_id);
    -- Any other request that relied on these shifts no longer fits.
    update public.roster_swaps set status = 'cancelled', cancel_reason = 'roster_changed', decided_at = now()
     where service_id = p_service_id and id <> v_swap.id and status in ('requested', 'accepted')
       and (give_assignment_id in (v_give.id, v_take.id) or take_assignment_id in (v_give.id, v_take.id));
    return jsonb_build_object('swapId', v_swap.id, 'status', 'approved', 'autoApproved', p_action = 'swap.accept');

  elsif p_action in ('swap.decline', 'swap.cancel', 'swap.undo') then
    select * into v_swap from public.roster_swaps
     where id = (p_payload ->> 'swapId')::uuid and service_id = p_service_id for update;
    if not found then raise exception 'roster_not_found'; end if;
    if p_action = 'swap.decline' then
      if not ((v_swap.status = 'requested' and v_swap.counterparty_id = p_actor_id)
              or (v_swap.status = 'accepted' and v_is_manager and p_actor_id not in (v_swap.requester_id, v_swap.counterparty_id))) then
        raise exception 'roster_role_denied';
      end if;
      update public.roster_swaps set status = 'declined', decided_at = now(),
             decided_by = case when v_swap.status = 'accepted' then p_actor_id else null end
       where id = v_swap.id;
      return jsonb_build_object('swapId', v_swap.id, 'status', 'declined');
    elsif p_action = 'swap.cancel' then
      if v_swap.requester_id <> p_actor_id or v_swap.status not in ('requested', 'accepted') then
        raise exception 'roster_role_denied';
      end if;
      update public.roster_swaps set status = 'cancelled', cancel_reason = 'withdrawn', decided_at = now() where id = v_swap.id;
      return jsonb_build_object('swapId', v_swap.id, 'status', 'cancelled');
    else
      -- "Undo for 10 min" after a swap approved itself, by either doctor, if nothing moved since.
      if not v_swap.auto_approved or v_swap.status <> 'approved' or v_swap.decided_at < now() - interval '10 minutes'
         or p_actor_id not in (v_swap.requester_id, v_swap.counterparty_id) then
        raise exception 'roster_role_denied';
      end if;
      select * into v_give from public.roster_assignments where id = v_swap.give_assignment_id for update;
      select * into v_take from public.roster_assignments where id = v_swap.take_assignment_id for update;
      if v_give.superseded_at is not null or v_give.user_id is distinct from v_swap.counterparty_id
         or (v_take.id is not null and (v_take.superseded_at is not null or v_take.user_id is distinct from v_swap.requester_id)) then
        raise exception 'roster_conflict';
      end if;
      update public.roster_assignments set user_id = v_swap.requester_id where id = v_give.id;
      if v_take.id is not null then
        update public.roster_assignments set user_id = v_swap.counterparty_id where id = v_take.id;
      end if;
      update public.roster_swaps set status = 'undone', decided_at = now() where id = v_swap.id;
      update public.roster_changes set undone_at = now(), undone_by = p_actor_id
       where service_id = p_service_id and source = 'swap' and change ->> 'swapId' = v_swap.id::text and undone_at is null;
      return jsonb_build_object('swapId', v_swap.id, 'status', 'undone');
    end if;

  -- ---------------------------------------------------------------- open shifts
  elsif p_action in ('open.post', 'open.report') then
    -- open.post: a member gives away their own shift, or a manager posts any live shift or a gap.
    -- open.report: "I can't make my shift": waits as 'reported' for the manager to release it.
    if p_payload ->> 'assignmentId' is not null then
      select * into v_give from public.roster_assignments
       where id = (p_payload ->> 'assignmentId')::uuid and service_id = p_service_id and superseded_at is null for update;
      if not found or v_give.ends_at <= now() or v_give.kind = 'leave'
         or (not v_is_manager and v_give.user_id is distinct from p_actor_id) then
        raise exception 'roster_not_found';
      end if;
      if exists (select 1 from public.roster_swaps w where w.status in ('requested', 'accepted')
                 and (w.give_assignment_id = v_give.id or w.take_assignment_id = v_give.id)) then
        raise exception 'roster_request_exists';
      end if;
      insert into public.roster_open_shifts (service_id, assignment_id, starts_at, ends_at, shift_code, kind, site_id,
                                             min_grade, urgent, status, posted_by)
      values (p_service_id, v_give.id, v_give.starts_at, v_give.ends_at, v_give.shift_code, v_give.kind, v_give.site_id,
              coalesce(nullif(v_give.grade, 'other'),
                       nullif((select grade from public.roster_member_roles where service_id = p_service_id
                               and user_id = v_give.user_id and revoked_at is null), 'other')),
              case when p_action = 'open.report' then true else coalesce((p_payload ->> 'urgent')::boolean, false) and v_is_manager end,
              case when p_action = 'open.report' then 'reported' else 'open' end, p_actor_id)
      returning * into v_open;
    else
      if p_action = 'open.report' or not v_is_manager then raise exception 'roster_role_denied'; end if;
      insert into public.roster_open_shifts (service_id, starts_at, ends_at, shift_code, kind, site_id, min_grade, urgent, posted_by)
      values (p_service_id, (p_payload ->> 'startsAt')::timestamptz, (p_payload ->> 'endsAt')::timestamptz,
              btrim(p_payload ->> 'shiftCode'), p_payload ->> 'kind', (p_payload ->> 'siteId')::uuid,
              p_payload ->> 'minGrade', coalesce((p_payload ->> 'urgent')::boolean, false), p_actor_id)
      returning * into v_open;
      if v_open.starts_at <= now() then raise exception 'roster_invalid_request'; end if;
    end if;
    if (select count(*) from public.roster_open_shifts where service_id = p_service_id and status in ('reported', 'open', 'claimed')) > 1000 then
      raise exception 'roster_limit';
    end if;
    return jsonb_build_object('openShiftId', v_open.id, 'status', v_open.status);

  elsif p_action in ('open.claim', 'open.approve', 'open.decline', 'open.cancel', 'open.release') then
    select * into v_open from public.roster_open_shifts
     where id = (p_payload ->> 'openShiftId')::uuid and service_id = p_service_id for update;
    if not found then raise exception 'roster_not_found'; end if;

    if p_action = 'open.release' then
      if not v_is_manager or v_open.status <> 'reported' then raise exception 'roster_role_denied'; end if;
      update public.roster_open_shifts set status = 'open', urgent = coalesce((p_payload ->> 'urgent')::boolean, true)
       where id = v_open.id;
      return jsonb_build_object('openShiftId', v_open.id, 'status', 'open');
    elsif p_action = 'open.cancel' then
      if v_open.status not in ('reported', 'open', 'claimed') or not (v_is_manager or v_open.posted_by = p_actor_id) then
        raise exception 'roster_role_denied';
      end if;
      update public.roster_open_shifts set status = 'cancelled', decided_at = now(), decided_by = p_actor_id where id = v_open.id;
      return jsonb_build_object('openShiftId', v_open.id, 'status', 'cancelled');
    elsif p_action = 'open.decline' then
      if not v_is_manager or v_open.status <> 'claimed' or v_open.claimed_by = p_actor_id then raise exception 'roster_role_denied'; end if;
      update public.roster_open_shifts set status = 'open', claimed_by = null, claimed_at = null where id = v_open.id;
      return jsonb_build_object('openShiftId', v_open.id, 'status', 'open');
    end if;

    if p_action = 'open.claim' then
      if v_open.status <> 'open' then raise exception 'roster_open_shift_taken'; end if;
      if v_open.starts_at <= now() or v_open.posted_by = p_actor_id then raise exception 'roster_not_found'; end if;
      v_id := p_actor_id;
    else
      if not v_is_manager or v_open.status <> 'claimed' or v_open.claimed_by = p_actor_id then raise exception 'roster_role_denied'; end if;
      v_id := v_open.claimed_by;
    end if;
    v_taker_rank := public.roster_grade_rank(
      (select grade from public.roster_member_roles where service_id = p_service_id and user_id = v_id and revoked_at is null));
    if v_taker_rank is null or (v_open.min_grade is not null and v_taker_rank < public.roster_grade_rank(v_open.min_grade))
       or public.roster_placement_problem(p_service_id, v_id, v_open.starts_at, v_open.ends_at,
            array[v_open.assignment_id], null) is not null then
      raise exception 'roster_swap_not_eligible';
    end if;
    if p_action = 'open.claim' and (
         coalesce(v_settings.swap_approval, 'auto_same_grade') = 'manager'
         or v_open.starts_at < now() + interval '7 days'
         or v_open.min_grade is null or v_taker_rank <> public.roster_grade_rank(v_open.min_grade)
         or public.roster_placement_problem(p_service_id, v_id, v_open.starts_at, v_open.ends_at,
              array[v_open.assignment_id], v_min_break) is not null) then
      update public.roster_open_shifts set status = 'claimed', claimed_by = v_id, claimed_at = now() where id = v_open.id;
      return jsonb_build_object('openShiftId', v_open.id, 'status', 'claimed');
    end if;

    -- Apply: the shift moves to the taker (or a gap becomes their shift), with its undo.
    if v_open.assignment_id is not null then
      select * into v_give from public.roster_assignments where id = v_open.assignment_id for update;
      if v_give.superseded_at is not null then raise exception 'roster_conflict'; end if;
      update public.roster_assignments set user_id = v_id, roster_name = null where id = v_give.id;
      v_row := jsonb_build_object('id', v_give.id, 'userId', v_give.user_id, 'rosterName', v_give.roster_name);
    else
      select * into v_pub from public.roster_publications where service_id = p_service_id order by version desc limit 1;
      if not found then raise exception 'roster_conflict'; end if;
      insert into public.roster_assignments (service_id, publication_id, user_id, site_id, starts_at, ends_at, shift_code, kind, grade)
      values (p_service_id, v_pub.id, v_id, v_open.site_id, v_open.starts_at, v_open.ends_at, v_open.shift_code, v_open.kind, v_open.min_grade)
      returning * into v_give;
      v_row := jsonb_build_object('id', v_give.id, 'delete', true);
    end if;
    update public.roster_open_shifts
       set status = 'approved', claimed_by = v_id, claimed_at = coalesce(claimed_at, now()), decided_at = now(),
           decided_by = case when p_action = 'open.approve' then p_actor_id else null end
     where id = v_open.id;
    insert into public.roster_changes (service_id, target, source, change, undo, actor_id)
    values (p_service_id, 'live', 'open_shift', jsonb_build_object('kind', 'open_shift', 'openShiftId', v_open.id),
            jsonb_build_object('assignments', jsonb_build_array(v_row)), p_actor_id);
    return jsonb_build_object('openShiftId', v_open.id, 'status', 'approved', 'assignmentId', v_give.id);

  -- ---------------------------------------------------------------- roster maker (Release 3)
  elsif p_action = 'codes.set' then
    if not v_is_manager then raise exception 'roster_role_denied'; end if;
    delete from public.roster_shift_codes where service_id = p_service_id;
    insert into public.roster_shift_codes (service_id, code, kind, starts, ends, label)
    select p_service_id, btrim(x ->> 'code'), x ->> 'kind', (x ->> 'starts')::time, (x ->> 'ends')::time, nullif(btrim(x ->> 'label'), '')
    from jsonb_array_elements(coalesce(p_payload -> 'codes', '[]')) x;
    if (select count(*) from public.roster_shift_codes where service_id = p_service_id) > 100 then raise exception 'roster_limit'; end if;
    return jsonb_build_object('ok', true);

  elsif p_action = 'needs.set' then
    if not v_is_manager then raise exception 'roster_role_denied'; end if;
    delete from public.roster_staffing_needs where service_id = p_service_id;
    insert into public.roster_staffing_needs (service_id, weekday, on_date, kind, grade, site_id, needed)
    select p_service_id, (x ->> 'weekday')::smallint, (x ->> 'date')::date, x ->> 'kind', x ->> 'grade',
           (x ->> 'siteId')::uuid, (x ->> 'needed')::smallint
    from jsonb_array_elements(coalesce(p_payload -> 'needs', '[]')) x;
    if (select count(*) from public.roster_staffing_needs where service_id = p_service_id) > 2000 then raise exception 'roster_limit'; end if;
    return jsonb_build_object('ok', true);

  elsif p_action = 'draft.open' then
    -- Start (or return) the draft for a period, copied from the live roster.
    if not v_is_manager then raise exception 'roster_role_denied'; end if;
    v_from := (p_payload ->> 'periodStart')::date;
    v_to := (p_payload ->> 'periodEnd')::date;
    select * into v_draft from public.roster_drafts
     where service_id = p_service_id and period_start = v_from and period_end = v_to;
    if found then return jsonb_build_object('draftId', v_draft.id, 'created', false); end if;
    if (select count(*) from public.roster_drafts where service_id = p_service_id) >= 12 then raise exception 'roster_limit'; end if;
    insert into public.roster_drafts (service_id, period_start, period_end, based_on_publication_id, created_by)
    values (p_service_id, v_from, v_to,
            (select id from public.roster_publications where service_id = p_service_id order by version desc limit 1), p_actor_id)
    returning * into v_draft;
    insert into public.roster_draft_assignments (draft_id, user_id, roster_name, site_id, starts_at, ends_at, shift_code, kind, grade)
    select v_draft.id, a.user_id,
           case when a.user_id is null then coalesce(a.roster_name, 'Unnamed') else a.roster_name end,
           a.site_id, a.starts_at, a.ends_at, a.shift_code, a.kind, a.grade
    from public.roster_assignments a
    where a.service_id = p_service_id and a.superseded_at is null
      and (a.starts_at at time zone 'Australia/Perth')::date between v_from and v_to;
    return jsonb_build_object('draftId', v_draft.id, 'created', true);

  elsif p_action = 'draft.change' then
    -- payload {draftId, source, ops: [{op:'add', row{...}} | {op:'remove', id} | {op:'update', id, row{...}}]}
    -- One roster_changes row per op, each with its undo, in this one transaction.
    if not v_is_manager then raise exception 'roster_role_denied'; end if;
    select * into v_draft from public.roster_drafts
     where id = (p_payload ->> 'draftId')::uuid and service_id = p_service_id for update;
    if not found then raise exception 'roster_not_found'; end if;
    if coalesce(p_payload ->> 'source', '') not in ('typed', 'grid', 'upload')
       or jsonb_typeof(p_payload -> 'ops') is distinct from 'array' or jsonb_array_length(p_payload -> 'ops') > 500 then
      raise exception 'roster_invalid_request';
    end if;
    for v_row in select value from jsonb_array_elements(p_payload -> 'ops') loop
      if v_row ->> 'op' = 'add' then
        if (v_row #>> '{row,userId}') is not null
           and not public.service_member_active(p_service_id, (v_row #>> '{row,userId}')::uuid) then
          raise exception 'roster_invalid_request';
        end if;
        insert into public.roster_draft_assignments (draft_id, user_id, roster_name, site_id, starts_at, ends_at, shift_code, kind, grade)
        values (v_draft.id, (v_row #>> '{row,userId}')::uuid, nullif(btrim(v_row #>> '{row,rosterName}'), ''),
                (v_row #>> '{row,siteId}')::uuid, (v_row #>> '{row,startsAt}')::timestamptz, (v_row #>> '{row,endsAt}')::timestamptz,
                btrim(v_row #>> '{row,shiftCode}'), v_row #>> '{row,kind}', v_row #>> '{row,grade}')
        returning id into v_id;
        insert into public.roster_changes (service_id, draft_id, target, source, change, undo, actor_id)
        values (p_service_id, v_draft.id, 'draft', p_payload ->> 'source', v_row || jsonb_build_object('id', v_id),
                jsonb_build_object('op', 'remove', 'id', v_id), p_actor_id)
        returning id into v_change_id;
      elsif v_row ->> 'op' in ('remove', 'update') then
        select to_jsonb(d) - 'draft_id' into v_result from public.roster_draft_assignments d
         where d.id = (v_row ->> 'id')::uuid and d.draft_id = v_draft.id for update;
        if v_result is null then raise exception 'roster_conflict'; end if;
        if v_row ->> 'op' = 'remove' then
          delete from public.roster_draft_assignments where id = (v_row ->> 'id')::uuid;
          insert into public.roster_changes (service_id, draft_id, target, source, change, undo, actor_id)
          values (p_service_id, v_draft.id, 'draft', p_payload ->> 'source', v_row,
                  jsonb_build_object('op', 'add', 'row', v_result), p_actor_id)
          returning id into v_change_id;
        else
          if (v_row #>> '{row,userId}') is not null
             and not public.service_member_active(p_service_id, (v_row #>> '{row,userId}')::uuid) then
            raise exception 'roster_invalid_request';
          end if;
          update public.roster_draft_assignments set
            user_id = case when v_row -> 'row' ? 'userId' then (v_row #>> '{row,userId}')::uuid else user_id end,
            roster_name = case when v_row -> 'row' ? 'rosterName' then nullif(btrim(v_row #>> '{row,rosterName}'), '') else roster_name end,
            site_id = case when v_row -> 'row' ? 'siteId' then (v_row #>> '{row,siteId}')::uuid else site_id end,
            starts_at = coalesce((v_row #>> '{row,startsAt}')::timestamptz, starts_at),
            ends_at = coalesce((v_row #>> '{row,endsAt}')::timestamptz, ends_at),
            shift_code = coalesce(btrim(v_row #>> '{row,shiftCode}'), shift_code),
            kind = coalesce(v_row #>> '{row,kind}', kind),
            grade = case when v_row -> 'row' ? 'grade' then v_row #>> '{row,grade}' else grade end
          where id = (v_row ->> 'id')::uuid;
          insert into public.roster_changes (service_id, draft_id, target, source, change, undo, actor_id)
          values (p_service_id, v_draft.id, 'draft', p_payload ->> 'source', v_row,
                  jsonb_build_object('op', 'update', 'id', v_row ->> 'id', 'row', v_result - 'id'), p_actor_id)
          returning id into v_change_id;
        end if;
      else
        raise exception 'roster_invalid_request';
      end if;
    end loop;
    if (select count(*) from public.roster_draft_assignments where draft_id = v_draft.id) > 5000 then raise exception 'roster_limit'; end if;
    update public.roster_drafts set updated_at = now() where id = v_draft.id;
    return jsonb_build_object('ok', true, 'lastChangeId', v_change_id);

  elsif p_action = 'draft.undo' then
    if not v_is_manager then raise exception 'roster_role_denied'; end if;
    select to_jsonb(x) into v_row from public.roster_changes x
     where x.id = (p_payload ->> 'changeId')::bigint and x.service_id = p_service_id
       and x.target = 'draft' and x.undone_at is null for update;
    if v_row is null then raise exception 'roster_not_found'; end if;
    if v_row #>> '{undo,op}' = 'remove' then
      delete from public.roster_draft_assignments where id = (v_row #>> '{undo,id}')::uuid
        and draft_id = (v_row ->> 'draft_id')::uuid;
      if not found then raise exception 'roster_conflict'; end if;
    elsif v_row #>> '{undo,op}' = 'add' then
      insert into public.roster_draft_assignments (id, draft_id, user_id, roster_name, site_id, starts_at, ends_at, shift_code, kind, grade)
      values ((v_row #>> '{undo,row,id}')::uuid, (v_row ->> 'draft_id')::uuid, (v_row #>> '{undo,row,user_id}')::uuid,
              v_row #>> '{undo,row,roster_name}', (v_row #>> '{undo,row,site_id}')::uuid,
              (v_row #>> '{undo,row,starts_at}')::timestamptz, (v_row #>> '{undo,row,ends_at}')::timestamptz,
              v_row #>> '{undo,row,shift_code}', v_row #>> '{undo,row,kind}', v_row #>> '{undo,row,grade}');
    else
      update public.roster_draft_assignments set
        user_id = (v_row #>> '{undo,row,user_id}')::uuid, roster_name = v_row #>> '{undo,row,roster_name}',
        site_id = (v_row #>> '{undo,row,site_id}')::uuid, starts_at = (v_row #>> '{undo,row,starts_at}')::timestamptz,
        ends_at = (v_row #>> '{undo,row,ends_at}')::timestamptz, shift_code = v_row #>> '{undo,row,shift_code}',
        kind = v_row #>> '{undo,row,kind}', grade = v_row #>> '{undo,row,grade}'
      where id = (v_row #>> '{undo,id}')::uuid and draft_id = (v_row ->> 'draft_id')::uuid;
      if not found then raise exception 'roster_conflict'; end if;
    end if;
    update public.roster_changes set undone_at = now(), undone_by = p_actor_id where id = (v_row ->> 'id')::bigint;
    return jsonb_build_object('ok', true);

  elsif p_action = 'agreement.record' then
    if not exists (select 1 from public.roster_changes c where c.id = (p_payload ->> 'changeId')::bigint
                   and c.service_id = p_service_id and c.agreement_required and c.undone_at is null) then
      raise exception 'roster_not_found';
    end if;
    insert into public.roster_change_agreements (change_id, user_id) values ((p_payload ->> 'changeId')::bigint, p_actor_id)
      on conflict do nothing;
    return jsonb_build_object('ok', true);
  end if;

  raise exception 'roster_invalid_request';
end $$;

-- The platform path that names or removes a roster manager (Josh's confirm button, from the
-- owner panel). Managers are never self-appointed.
create function public.roster_set_manager(p_service_id uuid, p_user_id uuid, p_actor_id uuid, p_manager boolean)
returns jsonb
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  if p_service_id is null or p_user_id is null or p_actor_id is null or p_manager is null then
    raise exception 'roster_invalid_request';
  end if;
  perform 1 from public.on_call_services where id = p_service_id for share;
  if not found or not public.service_member_active(p_service_id, p_user_id) then raise exception 'roster_not_found'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_service_id::text, 74817));
  insert into public.roster_member_roles (service_id, user_id, role, granted_by)
  values (p_service_id, p_user_id, case when p_manager then 'manager' else 'member' end, p_actor_id)
  on conflict (service_id, user_id) do update set
    role = excluded.role, granted_by = excluded.granted_by, granted_at = now(), revoked_at = null;
  insert into public.on_call_service_member_events (service_id, user_id, event, mode, actor_id)
  values (p_service_id, p_user_id, 'role_changed', 'roster', p_actor_id);
  return jsonb_build_object('ok', true);
end $$;

-- 12-month retention (Josh). Runs nightly from pg_cron. Printed names of people not on the app
-- are cleared 90 days after the shift ends.
create function public.roster_retention_purge() returns jsonb
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_publications integer; v_events integer; v_names integer;
begin
  delete from public.roster_publications where published_at < now() - interval '12 months';
  get diagnostics v_publications = row_count;
  delete from public.roster_swaps where created_at < now() - interval '12 months';
  delete from public.roster_open_shifts where created_at < now() - interval '12 months';
  delete from public.roster_changes where at < now() - interval '12 months';
  delete from public.roster_drafts where updated_at < now() - interval '12 months';
  delete from public.roster_unavailability where on_date < (now() at time zone 'Australia/Perth')::date - 30;
  delete from public.roster_leave where ends_on < (now() at time zone 'Australia/Perth')::date - 365;
  delete from public.on_call_service_member_events where at < now() - interval '12 months';
  get diagnostics v_events = row_count;
  update public.roster_assignments set roster_name = null
   where user_id is null and roster_name is not null and ends_at < now() - interval '90 days';
  get diagnostics v_names = row_count;
  return jsonb_build_object('publications', v_publications, 'memberEvents', v_events, 'namesCleared', v_names);
end $$;

do $grants$
declare f text;
begin
  foreach f in array array[
    'public.roster_can_invite(uuid, uuid)',
    'public.roster_own_shifts_replace(uuid, date, date, text, text, text, jsonb, jsonb, integer, integer, integer)',
    'public.roster_grade_rank(text)',
    'public.roster_placement_problem(uuid, uuid, timestamptz, timestamptz, uuid[], numeric)',
    'public.roster_person_name(uuid, uuid, text)',
    'public.roster_assignment_json(public.roster_assignments)',
    'public.roster_read(uuid, uuid, text, jsonb)',
    'public.roster_command(uuid, uuid, text, jsonb)',
    'public.roster_set_manager(uuid, uuid, uuid, boolean)',
    'public.roster_retention_purge()'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.roster_on_membership_revoked()',
    'public.roster_calendar_links_cap()',
    'public.web_push_subscriptions_cap()'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
  end loop;
end
$grants$;

-- Nightly retention job. pg_cron is already enabled (20260901033250).
do $roster_retention$
declare job record;
begin
  if to_regprocedure('public.roster_retention_purge()') is null then
    raise exception 'Missing public.roster_retention_purge()';
  end if;
  for job in select jobid from cron.job where jobname = 'roster-retention-purge' loop
    perform cron.unschedule(job.jobid);
  end loop;
  perform cron.schedule('roster-retention-purge', '20 3 * * *', $job$select public.roster_retention_purge();$job$);
end
$roster_retention$;

-- 20260926225509_admin_mode.sql
-- admin_mode.sql: Admin mode's file for Roster's combined DB PR (Admin thread, 2026-09-26, v2 against
-- /mnt/project-files/roster-mode/shared-db-contract.md v1). Placeholder name; Roster stamps it as file 3,
-- after roster_shared_services_hardening and roster_mode, before teaching_mode. Josh merges the PR himself.
--
-- Tenancy is the same as on_call_shifts (20260926051500):
--   * RLS is on, with no grant to anon or authenticated; only service_role can reach these tables.
--   * Every API query filters by owner_id.
-- Nothing here is shared with a service, and the service sees nothing (Josh, 2026-09-26).
-- The only free text is source_note on balances (80 characters). The API rejects identifier-like text in it
-- (reusing the existing identifier pattern); claim_reference has a fixed pattern.
--
-- v2 change: admin_member_roles is dropped from this PR. Josh is the only editor at launch (as service
-- admin), Admin publishes through the existing on_call_service_command, and nothing would read the table
-- yet. When a second editor is needed, Admin adds its role table in the contract's shape (granted_by,
-- granted_at, revoked_at, audit rows with mode = 'admin', service_member_active() check, advisory lock
-- key 74819) together with the RPC change that reads it. Admin takes no advisory lock in this file: every
-- row is owner-only and nothing is written per service.

-- 1. The shared extra-time record. Roster writes the times; Admin writes the claim fields.
--    There is deliberately no foreign key to on_call_shifts: a roster re-import replaces
--    shift rows, and that must never delete or orphan a claim. The link is by time only.
create table public.extra_time_records (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  kind text not null check (kind in ('stayed_late', 'called_in')),
  started_at timestamptz not null,
  -- Empty while a recall is still under way (a one-tap "Called in" at 02:10); filled in when it ends.
  ended_at timestamptz,
  -- Fixed choices only, with no free-text reason, so nothing clinical can be typed here.
  reason text check (reason is null or reason in ('handover', 'ward_work', 'admissions', 'emergency', 'teaching', 'admin', 'other')),
  claim_status text not null default 'draft' check (claim_status in ('draft', 'sent', 'paid', 'queried')),
  claim_reference text check (claim_reference is null or claim_reference ~ '^[A-Za-z0-9/_-]{1,40}$'),
  claim_sent_on date,
  claim_paid_on date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint extra_time_records_ends_after_start check (ended_at is null or ended_at > started_at),
  constraint extra_time_records_max_length check (ended_at is null or ended_at - started_at <= interval '24 hours'),
  -- Roster and Admin can both offer to log the same late finish; this stops a duplicate.
  constraint extra_time_records_one_per_start unique (owner_id, kind, started_at),
  -- Claim dates follow the claim status.
  constraint extra_time_records_sent_date_matches_status check (claim_sent_on is null or claim_status in ('sent', 'paid', 'queried')),
  constraint extra_time_records_paid_date_matches_status check (claim_paid_on is null or claim_status = 'paid'),
  -- A claim cannot be sent before the time it claims for has ended.
  constraint extra_time_records_ended_before_claim check (claim_status = 'draft' or ended_at is not null),
  constraint extra_time_records_paid_after_sent check (claim_paid_on is null or claim_sent_on is null or claim_paid_on >= claim_sent_on)
);
create index extra_time_records_owner_started_idx on public.extra_time_records (owner_id, started_at desc);
create trigger extra_time_records_updated_at before update on public.extra_time_records
  for each row execute function public.set_updated_at();
alter table public.extra_time_records enable row level security;
revoke all on table public.extra_time_records from public, anon, authenticated;
grant select, insert, update, delete on table public.extra_time_records to service_role;
create policy "extra time records service role all" on public.extra_time_records
  for all to service_role using (true) with check (true);

-- 2. Leave balances. These are figures the doctor types in, as of a date they choose.
--    There is no accrual and no entitlement maths. Planned leave dates live in Roster's own
--    planned-leave record, and Admin only reads that. There are no sick or personal leave kinds.
create table public.admin_leave_balances (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references auth.users (id) on delete cascade,
  kind text not null check (kind in ('annual', 'professional_development_leave', 'development_allowance')),
  amount numeric(8, 2) not null check (amount >= 0 and amount <= 100000),
  unit text not null check (unit in ('days', 'hours', 'dollars')),
  as_of date not null,
  source_note text check (source_note is null or (btrim(source_note) <> '' and char_length(source_note) <= 80)),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint admin_leave_balances_unit_matches_kind check (
    (kind = 'development_allowance' and unit = 'dollars') or (kind <> 'development_allowance' and unit in ('days', 'hours'))
  ),
  constraint admin_leave_balances_one_per_kind unique (owner_id, kind)
);
create trigger admin_leave_balances_updated_at before update on public.admin_leave_balances
  for each row execute function public.set_updated_at();
alter table public.admin_leave_balances enable row level security;
revoke all on table public.admin_leave_balances from public, anon, authenticated;
grant select, insert, update, delete on table public.admin_leave_balances to service_role;
create policy "admin leave balances service role all" on public.admin_leave_balances
  for all to service_role using (true) with check (true);

-- 3. Per-doctor Admin settings: one row per doctor.
--    level is used only to choose which guides show; nothing is calculated from it.
--    after_shift_asked_until stores only the end time of the last shift already asked about,
--    so the after-shift question is never asked twice. It holds no shift content.
create table public.admin_settings (
  owner_id uuid primary key references auth.users (id) on delete cascade,
  level text check (level is null or level in ('intern', 'resident', 'registrar', 'fellow', 'consultant', 'other')),
  pay_fortnight_start date,
  after_shift_prompt boolean not null default true,
  after_shift_asked_until timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger admin_settings_updated_at before update on public.admin_settings
  for each row execute function public.set_updated_at();
alter table public.admin_settings enable row level security;
revoke all on table public.admin_settings from public, anon, authenticated;
grant select, insert, update, delete on table public.admin_settings to service_role;
create policy "admin settings service role all" on public.admin_settings
  for all to service_role using (true) with check (true);

-- 20260926225609_teaching_mode.sql
-- Teaching: a health service's teaching programme, attendance, check-in codes, supervision and
-- feedback, built on the shared team tables (on_call_services and on_call_service_members).
--
-- Working file name only. Roster stamps this file when it assembles the combined DB PR, in the
-- order shared -> On Call -> Roster -> Admin -> Teaching, and it relies on every file before it:
-- on_call_services.verified_at and is_demo, on_call_service_members.display_name,
-- on_call_service_invitations.invited_email and issued_via_mode, on_call_service_member_events
-- and public.service_member_active(). It never replaces on_call_service_command.
--
-- Tenancy: every table is service_role only (RLS on, no policies, nothing granted to anon or
-- authenticated). Server routes call the security-invoker functions below with the actor id
-- taken from the signed-in session. No function reads auth.users. Nothing is seeded.

-- Link lists ({label, url}, https only, at most ten). Used by a table check and by the command.
create function public.teaching_valid_links(p_links jsonb) returns boolean
language sql immutable security invoker set search_path = public, pg_catalog, pg_temp as $$
  select case
    when p_links is null or jsonb_typeof(p_links) is distinct from 'array' then false
    when jsonb_array_length(p_links) > 10 then false
    else not exists (
      select 1 from jsonb_array_elements(p_links) as l(value)
      where jsonb_typeof(l.value) is distinct from 'object'
        or l.value - array['label','url'] <> '{}'::jsonb
        or jsonb_typeof(l.value->'label') is distinct from 'string'
        or char_length(btrim(l.value->>'label')) not between 1 and 120
        or jsonb_typeof(l.value->'url') is distinct from 'string'
        or char_length(l.value->>'url') > 2000
        or (l.value->>'url') !~ '^https://[^/@[:space:]]+(/|$)'
    )
  end
$$;

-- A supervision correction holds only the corrected field, never free text.
create function public.teaching_valid_correction(p_reason text, p_value jsonb) returns boolean
language sql immutable security invoker set search_path = public, pg_catalog, pg_temp as $$
  select case
    when p_value is null or jsonb_typeof(p_value) is distinct from 'object' then false
    when p_reason = 'entered_in_error' then p_value = '{}'::jsonb
    when p_reason = 'wrong_date' then
      p_value - 'date' = '{}'::jsonb and jsonb_typeof(p_value->'date') = 'string'
      and (p_value->>'date') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    when p_reason = 'wrong_length' then
      case
        when p_value - 'minutes' <> '{}'::jsonb or jsonb_typeof(p_value->'minutes') is distinct from 'number'
          or (p_value->>'minutes') !~ '^[0-9]{2,3}$' then false
        else (p_value->>'minutes')::integer between 15 and 240 and (p_value->>'minutes')::integer % 15 = 0
      end
    when p_reason = 'wrong_type' then
      p_value - 'type' = '{}'::jsonb and jsonb_typeof(p_value->'type') = 'string'
      and (p_value->>'type') in ('individual','group')
    when p_reason = 'wrong_topics' then
      case
        when p_value - 'topics' <> '{}'::jsonb or jsonb_typeof(p_value->'topics') is distinct from 'array' then false
        else jsonb_array_length(p_value->'topics') between 0 and 5
          and not exists (
            select 1 from jsonb_array_elements(p_value->'topics') as t(value)
            where jsonb_typeof(t.value) is distinct from 'string'
              or (t.value #>> '{}') not in ('case_review','risk','psychotherapy','formulation','medication','mha_legal','teaching_skills','career','exam_prep','wellbeing','other')
          )
      end
    else false
  end
$$;

-- Teaching roles are separate from the On Call role on on_call_service_members. An active member
-- with no active row here is a doctor.
create table public.teaching_member_roles (
  service_id uuid not null,
  user_id uuid not null,
  role text not null check (role in ('doctor','organiser','admin')),
  granted_by uuid null references auth.users(id) on delete set null,
  granted_at timestamptz not null default now(),
  revoked_at timestamptz null,
  primary key (service_id, user_id),
  foreign key (service_id, user_id) references public.on_call_service_members(service_id, user_id) on delete cascade
);

create table public.teaching_series (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services(id) on delete cascade,
  title text not null check (char_length(btrim(title)) between 3 and 160),
  kind text not null check (kind in ('lecture','case','journal','grand_round','simulation','workshop','other')),
  group_ids uuid[] not null default '{}' check (cardinality(group_ids) <= 20),
  repeat text not null check (repeat in ('once','weekly','fortnightly','monthly_nth')),
  first_date date not null,
  start_time time not null,
  minutes integer not null check (minutes between 10 and 480),
  time_zone text not null default 'Australia/Perth' check (time_zone = 'Australia/Perth'),
  venue text check (venue is null or char_length(btrim(venue)) between 1 and 160),
  join_url text check (join_url is null or (char_length(join_url) <= 2000 and join_url ~ '^https://[^/@[:space:]]+(/|$)')),
  skip_dates date[] not null default '{}' check (cardinality(skip_dates) <= 60),
  end_date date not null,
  presenter_id uuid references auth.users(id) on delete set null,
  materials jsonb not null default '[]'::jsonb check (public.teaching_valid_links(materials)),
  last_confirmed_at timestamptz,
  -- What's on (spec §5a): team-only until an organiser opens it to the team's health service.
  -- Only a verified or demo team with a platform-set health service may open (series.set_open_to).
  open_to text not null default 'team' check (open_to in ('team','health_service')),
  -- "My level" (R4): who the series is aimed at. The viewer's own level stays on their device.
  audience text not null default 'all_doctors' check (audience in ('interns','residents','registrars','consultants','all_doctors')),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, service_id),
  check (end_date >= first_date and end_date <= first_date + 366)
);
create index teaching_series_service on public.teaching_series(service_id);

create table public.teaching_occurrences (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services(id) on delete cascade,
  series_id uuid,
  -- The Perth date the series rule produced this occurrence for. It stays put when the session
  -- is moved, so saving the series again never recreates a moved or cancelled date.
  series_date date,
  title text not null check (char_length(btrim(title)) between 3 and 160),
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  venue text check (venue is null or char_length(btrim(venue)) between 1 and 160),
  join_url text check (join_url is null or (char_length(join_url) <= 2000 and join_url ~ '^https://[^/@[:space:]]+(/|$)')),
  presenter_id uuid references auth.users(id) on delete set null,
  status text not null default 'scheduled' check (status in ('scheduled','moved','cancelled')),
  change_reason text check (change_reason is null or change_reason in ('presenter_unavailable','room_change','clinical_pressure','public_holiday','rescheduled','other')),
  changed_at timestamptz,
  -- The start just before the latest move that changed the time ("Moved from 12:30"). A move of
  -- the venue only keeps it as it was. session.read returns it only while the status is moved.
  previous_starts_at timestamptz,
  -- Server-only. Never returned by any function (tests/teaching-migration-contract.test.ts).
  checkin_secret bytea not null default extensions.gen_random_bytes(32) check (octet_length(checkin_secret) = 32),
  created_at timestamptz not null default now(),
  unique (id, service_id),
  unique (series_id, series_date),
  foreign key (series_id, service_id) references public.teaching_series(id, service_id) on delete set null (series_id),
  check (ends_at > starts_at and ends_at <= starts_at + interval '8 hours'),
  check ((status = 'scheduled') = (change_reason is null)),
  check ((change_reason is null) = (changed_at is null)),
  check (previous_starts_at is null or status <> 'scheduled')
);
create index teaching_occurrences_service_starts on public.teaching_occurrences(service_id, starts_at);
create index teaching_occurrences_presenter on public.teaching_occurrences(presenter_id, starts_at) where presenter_id is not null;
-- What's on and the feed read one week across teams, so they range on starts_at alone.
create index teaching_occurrences_starts on public.teaching_occurrences(starts_at);

create table public.teaching_groups (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services(id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 80),
  created_at timestamptz not null default now(),
  unique (service_id, name),
  unique (id, service_id)
);
create table public.teaching_group_members (
  group_id uuid not null,
  service_id uuid not null,
  user_id uuid not null,
  primary key (group_id, user_id),
  foreign key (group_id, service_id) references public.teaching_groups(id, service_id) on delete cascade,
  foreign key (service_id, user_id) references public.on_call_service_members(service_id, user_id) on delete cascade
);
create index teaching_group_members_user on public.teaching_group_members(user_id, service_id);

-- Notice wording is built in TypeScript from the occurrence and kind. No free text is stored.
create table public.teaching_notices (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services(id) on delete cascade,
  occurrence_id uuid not null,
  kind text not null check (kind in ('moved','cancelled')),
  created_at timestamptz not null default now(),
  created_by uuid references auth.users(id) on delete set null,
  foreign key (occurrence_id, service_id) references public.teaching_occurrences(id, service_id) on delete cascade
);
create index teaching_notices_occurrence on public.teaching_notices(occurrence_id);
create index teaching_notices_service_created on public.teaching_notices(service_id, created_at desc);
create table public.teaching_notice_reads (
  notice_id uuid not null references public.teaching_notices(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  read_at timestamptz not null default now(),
  primary key (notice_id, user_id)
);

-- A doctor's own attendance is their record, so it goes when their account is deleted.
create table public.teaching_attendance (
  occurrence_id uuid not null,
  service_id uuid not null,
  user_id uuid not null references auth.users(id) on delete cascade,
  method text not null check (method in ('code_room','code_teams','self')),
  recorded_at timestamptz not null default now(),
  upgraded_from text check (upgraded_from is null or (upgraded_from = 'self' and method <> 'self')),
  -- A visitor from another team in the same health service (spec §5a): always self-reported,
  -- visible only to the visitor, and counted (never named) for the host team.
  visitor boolean not null default false,
  primary key (occurrence_id, user_id),
  check (not visitor or method = 'self'),
  foreign key (occurrence_id, service_id) references public.teaching_occurrences(id, service_id) on delete cascade
);
create index teaching_attendance_user on public.teaching_attendance(user_id, recorded_at desc);

create table public.teaching_checkin_claims (
  id uuid primary key default gen_random_uuid(),
  occurrence_id uuid not null references public.teaching_occurrences(id) on delete cascade,
  stream text not null check (stream in ('room','teams')),
  claim_hash text not null unique check (claim_hash ~ '^[a-f0-9]{64}$'),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  used_at timestamptz,
  used_by uuid references auth.users(id) on delete set null,
  check (expires_at > created_at and expires_at <= created_at + interval '10 minutes'),
  check (used_by is null or used_at is not null)
);
create index teaching_checkin_claims_occurrence on public.teaching_checkin_claims(occurrence_id, expires_at);

create table public.teaching_display_links (
  id uuid primary key default gen_random_uuid(),
  occurrence_id uuid not null references public.teaching_occurrences(id) on delete cascade,
  stream text not null check (stream in ('room','teams')),
  link_hash text not null unique check (link_hash ~ '^[a-f0-9]{64}$'),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null,
  revoked_at timestamptz,
  check (expires_at > created_at)
);
create index teaching_display_links_occurrence on public.teaching_display_links(occurrence_id);

create table public.teaching_calendar_optins (
  service_id uuid not null,
  user_id uuid not null,
  created_at timestamptz not null default now(),
  primary key (service_id, user_id),
  foreign key (service_id, user_id) references public.on_call_service_members(service_id, user_id) on delete cascade
);

-- What's on and Resources (spec §5a), PR B. The team's health service is platform-only, like
-- on_call_services.verified_at: only teaching_platform_command writes it. A fixed list, the five
-- WA health service providers plus demo (demo only for is_demo teams).
create table public.teaching_team_settings (
  service_id uuid primary key references public.on_call_services(id) on delete cascade,
  health_service text not null check (health_service in ('nmhs','smhs','emhs','wachs','cahs','demo')),
  set_by uuid references auth.users(id) on delete set null,
  set_at timestamptz not null default now()
);
create index teaching_team_settings_health_service on public.teaching_team_settings(health_service);

-- A session or series from another team, added to a person's own week from What's on. It then
-- shows in Week and the calendar feed while the session stays open. Personal, so it goes with the account.
create table public.teaching_week_adds (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  occurrence_id uuid references public.teaching_occurrences(id) on delete cascade,
  series_id uuid references public.teaching_series(id) on delete cascade,
  added_at timestamptz not null default now(),
  check (num_nonnulls(occurrence_id, series_id) = 1),
  unique (user_id, occurrence_id),
  unique (user_id, series_id)
);
create index teaching_week_adds_occurrence on public.teaching_week_adds(occurrence_id) where occurrence_id is not null;
create index teaching_week_adds_series on public.teaching_week_adds(series_id) where series_id is not null;

-- Organiser-made collections (for example Exam prep) and their sections (for example Written exam).
create table public.teaching_collections (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services(id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 80),
  sort_order integer not null default 0 check (sort_order between 0 and 999),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (service_id, name),
  unique (id, service_id)
);
create table public.teaching_collection_sections (
  id uuid primary key default gen_random_uuid(),
  collection_id uuid not null,
  service_id uuid not null,
  name text not null check (char_length(btrim(name)) between 1 and 80),
  sort_order integer not null default 0 check (sort_order between 0 and 999),
  unique (collection_id, name),
  unique (id, collection_id),
  foreign key (collection_id, service_id) references public.teaching_collections(id, service_id) on delete cascade
);

-- Links only: slides and recordings stay where they live, and nothing is uploaded or copied. A
-- resource is an https link or a PsychSift library document id, never both. Who may see it is
-- derived, not stored: the team, plus the health service while its linked session is open.
-- Soft-deleted (removed_at) so saves and the audit trail keep their subject.
create table public.teaching_resources (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services(id) on delete cascade,
  title text not null check (char_length(btrim(title)) between 1 and 160),
  kind text not null check (kind in ('slides','recording','reading','link','library')),
  url text check (url is null or (char_length(url) <= 2000 and url ~ '^https://[^/@[:space:]]+(/|$)')),
  library_document_id uuid,
  collection_id uuid,
  section_id uuid,
  occurrence_id uuid,
  series_id uuid,
  added_by uuid references auth.users(id) on delete set null,
  added_at timestamptz not null default now(),
  -- The adder ticked "No patient details in this file"; added_by records who.
  no_patient_details_confirmed_at timestamptz not null,
  removed_at timestamptz,
  removed_by uuid references auth.users(id) on delete set null,
  check ((url is null) <> (library_document_id is null)),
  check ((kind = 'library') = (library_document_id is not null)),
  check (removed_at is null or removed_at >= added_at),
  foreign key (collection_id, service_id) references public.teaching_collections(id, service_id) on delete set null (collection_id),
  foreign key (section_id, collection_id) references public.teaching_collection_sections(id, collection_id) on delete set null (section_id),
  foreign key (occurrence_id, service_id) references public.teaching_occurrences(id, service_id) on delete set null (occurrence_id),
  foreign key (series_id, service_id) references public.teaching_series(id, service_id) on delete set null (series_id)
);
create index teaching_resources_service on public.teaching_resources(service_id, added_at desc) where removed_at is null;
create index teaching_resources_occurrence on public.teaching_resources(occurrence_id) where occurrence_id is not null;
create index teaching_resources_series on public.teaching_resources(series_id) where series_id is not null;
create index teaching_resources_collection on public.teaching_resources(collection_id) where collection_id is not null;

create table public.teaching_resource_saves (
  user_id uuid not null references auth.users(id) on delete cascade,
  resource_id uuid not null references public.teaching_resources(id) on delete cascade,
  saved_at timestamptz not null default now(),
  primary key (user_id, resource_id)
);
create index teaching_resource_saves_resource on public.teaching_resource_saves(resource_id);

-- PR B tables, used by Plan 2. Created now so the database changes once.
create table public.teaching_readiness (
  occurrence_id uuid primary key,
  service_id uuid not null,
  -- The presenter's checklist (the four approved items) and the cases-checked confirmation. Until the
  -- presenter confirms the cases check, the occurrence's slides are hidden from everyone but the
  -- presenter and organisers (teaching_slides_released).
  items text[] not null default '{}' check (items <@ array['reading_list','aims','slides_link','room']::text[]),
  deid_confirmed_at timestamptz,
  deid_confirmed_by uuid references auth.users(id) on delete set null,
  updated_at timestamptz not null default now(),
  foreign key (occurrence_id, service_id) references public.teaching_occurrences(id, service_id) on delete cascade
);

-- Feedback lives in two tables with no link between them. The answers carry no person, no
-- timestamp and no ordering column; the reply marker carries no answer, no timestamp and no user
-- id, only a one-way sha256 "already answered" marker for that occurrence (D4 feedback.submit).
create table public.teaching_feedback_answers (
  id uuid primary key default gen_random_uuid(),
  occurrence_id uuid not null,
  service_id uuid not null,
  useful smallint not null check (useful between 1 and 5),
  pace text not null check (pace in ('slow','right','fast')),
  foreign key (occurrence_id, service_id) references public.teaching_occurrences(id, service_id) on delete cascade
);
create index teaching_feedback_answers_occurrence on public.teaching_feedback_answers(occurrence_id);
create table public.teaching_feedback_replied (
  occurrence_id uuid not null references public.teaching_occurrences(id) on delete cascade,
  reply_marker text not null check (reply_marker ~ '^[a-f0-9]{64}$'),
  primary key (occurrence_id, reply_marker)
);

create table public.teaching_supervision_pairings (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.on_call_services(id) on delete cascade,
  registrar_id uuid references auth.users(id) on delete set null,
  supervisor_id uuid references auth.users(id) on delete set null,
  starts_on date not null,
  ends_on date not null,
  -- The registrar's own hours target (supervision.target.set, registrar only). Nullable, no default.
  target_hours numeric(5,1) check (target_hours is null or target_hours between 1 and 500),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (id, service_id),
  check (registrar_id <> supervisor_id),
  check (ends_on >= starts_on and ends_on <= starts_on + 731)
);
create index teaching_supervision_pairings_registrar on public.teaching_supervision_pairings(registrar_id) where registrar_id is not null;
create index teaching_supervision_pairings_supervisor on public.teaching_supervision_pairings(supervisor_id) where supervisor_id is not null;
create index teaching_supervision_pairings_service on public.teaching_supervision_pairings(service_id);

create table public.teaching_supervision_entries (
  id uuid primary key default gen_random_uuid(),
  pairing_id uuid not null,
  service_id uuid not null,
  session_date date not null,
  minutes integer not null check (minutes between 15 and 240 and minutes % 15 = 0),
  type text not null check (type in ('individual','group')),
  -- Optional: none to five topics.
  topics text[] not null check (cardinality(topics) between 0 and 5 and topics <@ array['case_review','risk','psychotherapy','formulation','medication','mha_legal','teaching_skills','career','exam_prep','wellbeing','other']::text[]),
  status text not null default 'pending' check (status in ('pending','confirmed')),
  confirmed_by uuid references auth.users(id) on delete set null,
  confirmed_at timestamptz,
  locked boolean not null default false,
  logged_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  unique (id, service_id),
  foreign key (pairing_id, service_id) references public.teaching_supervision_pairings(id, service_id) on delete cascade,
  check ((status = 'confirmed') = (confirmed_at is not null)),
  check (locked = (status = 'confirmed'))
);
create index teaching_supervision_entries_pairing on public.teaching_supervision_entries(pairing_id, session_date);

create table public.teaching_supervision_notes (
  id uuid primary key default gen_random_uuid(),
  entry_id uuid not null,
  service_id uuid not null,
  reason text not null check (reason in ('wrong_date','wrong_length','wrong_type','wrong_topics','entered_in_error')),
  corrected_value jsonb not null default '{}'::jsonb check (public.teaching_valid_correction(reason, corrected_value)),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  confirmed_by uuid references auth.users(id) on delete set null,
  confirmed_at timestamptz,
  foreign key (entry_id, service_id) references public.teaching_supervision_entries(id, service_id) on delete cascade
);
create index teaching_supervision_notes_entry on public.teaching_supervision_notes(entry_id);

-- Fixed fields only. Kept when a team or account is deleted (no service foreign key; the actor
-- becomes null). subject_id has no foreign key (it can be a user id, for role.set), so it goes
-- with the row: rows older than 12 months are purged nightly, as the shared contract's
-- on_call_service_member_events are (the pg_cron job is registered in D3 Step 4).
create table public.teaching_audit_events (
  id bigint generated always as identity primary key,
  service_id uuid not null,
  actor_id uuid references auth.users(id) on delete set null,
  action text not null check (action ~ '^[a-z_.]{3,48}$'),
  subject_id uuid,
  at timestamptz not null default now()
);
create index teaching_audit_events_service_at on public.teaching_audit_events(service_id, at desc, id desc);

-- A confirmed supervision entry is locked. Only a person column being cleared by an account
-- deletion (on delete set null) may still change it, so deleting an account is never blocked.
create function public.teaching_guard_supervision_entry() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  if old.locked and (new.pairing_id, new.service_id, new.session_date, new.minutes, new.type, new.topics,
      new.status, new.confirmed_at, new.locked, new.created_at)
    is distinct from (old.pairing_id, old.service_id, old.session_date, old.minutes, old.type, old.topics,
      old.status, old.confirmed_at, old.locked, old.created_at) then
    raise exception 'teaching_invalid_request';
  end if;
  return new;
end $$;
create trigger teaching_supervision_entry_locked before update on public.teaching_supervision_entries
  for each row execute function public.teaching_guard_supervision_entry();

alter table public.teaching_member_roles enable row level security;
alter table public.teaching_series enable row level security;
alter table public.teaching_occurrences enable row level security;
alter table public.teaching_groups enable row level security;
alter table public.teaching_group_members enable row level security;
alter table public.teaching_notices enable row level security;
alter table public.teaching_notice_reads enable row level security;
alter table public.teaching_attendance enable row level security;
alter table public.teaching_checkin_claims enable row level security;
alter table public.teaching_display_links enable row level security;
alter table public.teaching_calendar_optins enable row level security;
alter table public.teaching_readiness enable row level security;
alter table public.teaching_feedback_answers enable row level security;
alter table public.teaching_feedback_replied enable row level security;
alter table public.teaching_supervision_pairings enable row level security;
alter table public.teaching_supervision_entries enable row level security;
alter table public.teaching_supervision_notes enable row level security;
alter table public.teaching_audit_events enable row level security;
alter table public.teaching_team_settings enable row level security;
alter table public.teaching_week_adds enable row level security;
alter table public.teaching_collections enable row level security;
alter table public.teaching_collection_sections enable row level security;
alter table public.teaching_resources enable row level security;
alter table public.teaching_resource_saves enable row level security;
revoke all on public.teaching_member_roles, public.teaching_series, public.teaching_occurrences, public.teaching_groups, public.teaching_group_members, public.teaching_notices, public.teaching_notice_reads, public.teaching_attendance, public.teaching_checkin_claims, public.teaching_display_links, public.teaching_calendar_optins, public.teaching_readiness, public.teaching_feedback_answers, public.teaching_feedback_replied, public.teaching_supervision_pairings, public.teaching_supervision_entries, public.teaching_supervision_notes, public.teaching_audit_events, public.teaching_team_settings, public.teaching_week_adds, public.teaching_collections, public.teaching_collection_sections, public.teaching_resources, public.teaching_resource_saves from public, anon, authenticated;
grant select, insert, update, delete on public.teaching_member_roles, public.teaching_series, public.teaching_occurrences, public.teaching_groups, public.teaching_group_members, public.teaching_notices, public.teaching_notice_reads, public.teaching_attendance, public.teaching_checkin_claims, public.teaching_display_links, public.teaching_calendar_optins, public.teaching_readiness, public.teaching_feedback_answers, public.teaching_feedback_replied, public.teaching_supervision_pairings, public.teaching_supervision_entries, public.teaching_supervision_notes, public.teaching_team_settings, public.teaching_week_adds, public.teaching_collections, public.teaching_collection_sections, public.teaching_resources, public.teaching_resource_saves to service_role;
-- The audit trail is append-only for the application: no update grant. Delete stays for retention.
grant select, insert, delete on public.teaching_audit_events to service_role;

revoke all on function public.teaching_valid_links(jsonb) from public, anon, authenticated;
grant execute on function public.teaching_valid_links(jsonb) to service_role;
revoke all on function public.teaching_valid_correction(text, jsonb) from public, anon, authenticated;
grant execute on function public.teaching_valid_correction(text, jsonb) to service_role;
revoke all on function public.teaching_guard_supervision_entry() from public, anon, authenticated;
grant execute on function public.teaching_guard_supervision_entry() to service_role;

-- Payload readers. A malformed value raises teaching_invalid_request (400) instead of a raw cast
-- error, which the API would otherwise report as "Teaching is unavailable" (503).
create function public.teaching_text_arg(p_payload jsonb, p_key text) returns text
language plpgsql immutable security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_value jsonb := p_payload->p_key;
begin
  if v_value is null or v_value = 'null'::jsonb then return null; end if;
  if jsonb_typeof(v_value) <> 'string' then raise exception 'teaching_invalid_request'; end if;
  return v_value #>> '{}';
end $$;

create function public.teaching_uuid_arg(p_payload jsonb, p_key text) returns uuid
language plpgsql immutable security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_text text := public.teaching_text_arg(p_payload, p_key);
begin
  if v_text is null then return null; end if;
  if v_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'teaching_invalid_request';
  end if;
  return v_text::uuid;
end $$;

create function public.teaching_int_arg(p_payload jsonb, p_key text) returns integer
language plpgsql immutable security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_value jsonb := p_payload->p_key;
begin
  if v_value is null or v_value = 'null'::jsonb then return null; end if;
  if jsonb_typeof(v_value) <> 'number' or (v_value #>> '{}') !~ '^-?[0-9]{1,6}$' then
    raise exception 'teaching_invalid_request';
  end if;
  return (v_value #>> '{}')::integer;
end $$;

create function public.teaching_date_arg(p_payload jsonb, p_key text) returns date
language plpgsql immutable security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_text text := public.teaching_text_arg(p_payload, p_key); v_date date;
begin
  if v_text is null then return null; end if;
  if v_text !~ '^(19|20)[0-9]{2}-[0-9]{2}-[0-9]{2}$' then raise exception 'teaching_invalid_request'; end if;
  begin
    v_date := v_text::date;
  exception when invalid_datetime_format or datetime_field_overflow then
    raise exception 'teaching_invalid_request';
  end;
  return v_date;
end $$;

create function public.teaching_ts_arg(p_payload jsonb, p_key text) returns timestamptz
language plpgsql stable security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_text text := public.teaching_text_arg(p_payload, p_key); v_at timestamptz;
begin
  if v_text is null then return null; end if;
  -- An explicit offset is required, so no value is read in the database session's time zone.
  if v_text !~ '^(19|20)[0-9]{2}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2}(\.[0-9]{1,6})?)?(Z|[+-][0-9]{2}:[0-9]{2})$' then
    raise exception 'teaching_invalid_request';
  end if;
  begin
    v_at := v_text::timestamptz;
  exception when invalid_datetime_format or datetime_field_overflow then
    raise exception 'teaching_invalid_request';
  end;
  return v_at;
end $$;

create function public.teaching_uuid_array_arg(p_payload jsonb, p_key text, p_max integer) returns uuid[]
language plpgsql immutable security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_value jsonb := p_payload->p_key; v_item jsonb; v_out uuid[] := '{}';
begin
  if v_value is null or v_value = 'null'::jsonb then return '{}'; end if;
  if jsonb_typeof(v_value) <> 'array' or jsonb_array_length(v_value) > p_max then raise exception 'teaching_invalid_request'; end if;
  for v_item in select value from jsonb_array_elements(v_value) loop
    v_out := v_out || public.teaching_uuid_arg(jsonb_build_object('v', v_item), 'v');
  end loop;
  if array_position(v_out, null) is not null then raise exception 'teaching_invalid_request'; end if;
  return array(select distinct u from unnest(v_out) as u order by u);
end $$;

create function public.teaching_date_array_arg(p_payload jsonb, p_key text, p_max integer) returns date[]
language plpgsql immutable security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_value jsonb := p_payload->p_key; v_item jsonb; v_out date[] := '{}';
begin
  if v_value is null or v_value = 'null'::jsonb then return '{}'; end if;
  if jsonb_typeof(v_value) <> 'array' or jsonb_array_length(v_value) > p_max then raise exception 'teaching_invalid_request'; end if;
  for v_item in select value from jsonb_array_elements(v_value) loop
    v_out := v_out || public.teaching_date_arg(jsonb_build_object('v', v_item), 'v');
  end loop;
  if array_position(v_out, null) is not null then raise exception 'teaching_invalid_request'; end if;
  return array(select distinct d from unnest(v_out) as d order by d);
end $$;

create function public.teaching_text_array_arg(p_payload jsonb, p_key text, p_max integer) returns text[]
language plpgsql immutable security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_value jsonb := p_payload->p_key; v_item jsonb; v_out text[] := '{}';
begin
  if v_value is null or v_value = 'null'::jsonb then return '{}'; end if;
  if jsonb_typeof(v_value) <> 'array' or jsonb_array_length(v_value) > p_max then raise exception 'teaching_invalid_request'; end if;
  for v_item in select value from jsonb_array_elements(v_value) loop
    if jsonb_typeof(v_item) <> 'string' then raise exception 'teaching_invalid_request'; end if;
    v_out := v_out || (v_item #>> '{}');
  end loop;
  return array(select distinct t from unnest(v_out) as t order by t);
end $$;

-- Constant-time comparison: xor-fold over every byte, no early exit on the first difference.
create function public.teaching_const_eq(p_left text, p_right text) returns boolean
language plpgsql immutable security invoker set search_path = public, pg_catalog, pg_temp as $$
declare
  v_left bytea;
  v_right bytea;
  v_diff integer := 0;
  v_index integer;
begin
  if p_left is null or p_right is null then return false; end if;
  v_left := convert_to(p_left, 'UTF8');
  v_right := convert_to(p_right, 'UTF8');
  if octet_length(v_left) = 0 or octet_length(v_left) <> octet_length(v_right) then return false; end if;
  for v_index in 0 .. octet_length(v_left) - 1 loop
    v_diff := v_diff | (get_byte(v_left, v_index) # get_byte(v_right, v_index));
  end loop;
  return v_diff = 0;
end $$;

-- 32 hex characters: the first 16 bytes of HMAC-SHA256(occurrence:stream:window, secret).
create function public.teaching_code_mac(p_secret bytea, p_occurrence uuid, p_stream text, p_window bigint) returns text
language sql immutable security invoker set search_path = public, pg_catalog, pg_temp as $$
  select encode(substring(extensions.hmac(convert_to(p_occurrence::text || ':' || p_stream || ':' || p_window::text, 'UTF8'), p_secret, 'sha256') from 1 for 16), 'hex')
$$;

-- Six digits for typing in when a camera cannot scan. A separate HMAC input from the scan code.
create function public.teaching_typed_code(p_secret bytea, p_occurrence uuid, p_stream text, p_window bigint) returns text
language sql immutable security invoker set search_path = public, pg_catalog, pg_temp as $$
  select lpad((((('x' || encode(substring(extensions.hmac(convert_to(p_occurrence::text || ':' || p_stream || ':' || p_window::text || ':typed', 'UTF8'), p_secret, 'sha256') from 1 for 4), 'hex'))::bit(32)::bigint) & 4294967295) % 1000000)::text, 6, '0')
$$;

-- The Teaching role of an active member, or null for anyone who is not an active member.
-- A role row granted before the member's latest join is stale and ignored. The revoke cascade
-- below already revokes the row at the shared revoke; this guard is the second layer, so a
-- rejoining member never regains organiser or admin.
create function public.teaching_member_role(p_service_id uuid, p_user_id uuid) returns text
language plpgsql stable security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_role text;
begin
  if p_service_id is null or p_user_id is null or not public.service_member_active(p_service_id, p_user_id) then
    return null;
  end if;
  select r.role into v_role
  from public.teaching_member_roles r
  join public.on_call_service_members m on m.service_id = r.service_id and m.user_id = r.user_id
  where r.service_id = p_service_id and r.user_id = p_user_id
    and r.revoked_at is null and m.revoked_at is null and r.granted_at >= m.joined_at;
  return coalesce(v_role, 'doctor');
end $$;

-- Called at run time by On Call's shared join for an invitation with issued_via_mode = 'teaching'.
create function public.teaching_can_invite(p_service_id uuid, p_user_id uuid) returns boolean
language plpgsql stable security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  return coalesce(public.teaching_member_role(p_service_id, p_user_id) in ('organiser','admin'), false);
end $$;

-- Active Teaching admins, by the same rule as teaching_member_role.
create function public.teaching_admin_count(p_service_id uuid) returns integer
language plpgsql stable security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_count integer;
begin
  select count(*) into v_count
  from public.teaching_member_roles r
  join public.on_call_service_members m on m.service_id = r.service_id and m.user_id = r.user_id
  where r.service_id = p_service_id and r.role = 'admin'
    and r.revoked_at is null and m.revoked_at is null and r.granted_at >= m.joined_at;
  return v_count;
end $$;

-- Revoke cascade (shared contract v5 item 10). When a shared membership is revoked (revoked_at
-- goes from null to a time), the member's active Teaching role is revoked in the same transaction
-- and one shared member event is written. A rejoin clears revoked_at, which the when clause does
-- not match, so it never re-revokes; roles are not restored on rejoin and must be granted again.
-- A member with no active Teaching row (a doctor) had no role to change, so no event is written.
-- A trigger cannot see who revoked, so actor_id is null; On Call's own 'revoked' event names them.
create function public.teaching_cascade_member_revoke() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  update public.teaching_member_roles set revoked_at = now()
  where service_id = new.service_id and user_id = new.user_id and revoked_at is null;
  if found then
    insert into public.on_call_service_member_events(service_id, user_id, event, mode, actor_id)
    values (new.service_id, new.user_id, 'role_changed', 'teaching', null);
  end if;
  return null;
end $$;
create trigger teaching_member_revoke_cascade
  after update of revoked_at on public.on_call_service_members
  for each row when (old.revoked_at is null and new.revoked_at is not null)
  execute function public.teaching_cascade_member_revoke();

create function public.teaching_audit(p_service_id uuid, p_actor_id uuid, p_action text, p_subject_id uuid) returns void
language plpgsql volatile security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  insert into public.teaching_audit_events(service_id, actor_id, action, subject_id)
  values (p_service_id, p_actor_id, p_action, p_subject_id);
end $$;

-- One attendance row per person per session. A code check-in upgrades a self-declared row and
-- the upgrade is audited; nothing ever downgrades a code check-in.
create function public.teaching_record_attendance(p_actor_id uuid, p_service_id uuid, p_occurrence_id uuid, p_method text) returns jsonb
language plpgsql volatile security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_row public.teaching_attendance;
begin
  if p_method not in ('code_room','code_teams','self') then raise exception 'teaching_invalid_request'; end if;
  insert into public.teaching_attendance(occurrence_id, service_id, user_id, method)
  values (p_occurrence_id, p_service_id, p_actor_id, p_method)
  on conflict (occurrence_id, user_id) do nothing
  returning * into v_row;
  if found then
    perform public.teaching_audit(p_service_id, p_actor_id, 'attendance.' || p_method, p_occurrence_id);
  else
    select * into v_row from public.teaching_attendance
    where occurrence_id = p_occurrence_id and user_id = p_actor_id for update;
    if v_row.method = 'self' and p_method <> 'self' then
      update public.teaching_attendance set method = p_method, upgraded_from = 'self', visitor = false, recorded_at = now()
      where occurrence_id = p_occurrence_id and user_id = p_actor_id
      returning * into v_row;
      perform public.teaching_audit(p_service_id, p_actor_id, 'attendance.upgrade', p_occurrence_id);
    elsif v_row.visitor then
      -- A What's on visitor who has since joined this team: the row becomes a member's row.
      update public.teaching_attendance set visitor = false
      where occurrence_id = p_occurrence_id and user_id = p_actor_id
      returning * into v_row;
    end if;
  end if;
  return jsonb_build_object('occurrenceId', v_row.occurrence_id, 'method', v_row.method, 'recordedAt', v_row.recorded_at);
end $$;

-- Scan landing, before sign-in. Verifies the token and records a single-use 10-minute claim that
-- teaching_command('checkin.complete') redeems after sign-in. Returns only what the landing page
-- shows. The MAC is checked before anything about the session is revealed.
create function public.teaching_checkin_open(p_token text, p_claim_hash text) returns jsonb
language plpgsql volatile security invoker set search_path = public, pg_catalog, pg_temp as $$
declare
  v_parts text[];
  v_occ public.teaching_occurrences;
  v_service public.on_call_services;
  v_stream text;
  v_window bigint;
  v_now_window bigint := floor(extract(epoch from now()) / 30)::bigint;
  v_expected text;
begin
  if p_token is null or p_claim_hash is null or p_claim_hash !~ '^[a-f0-9]{64}$' then
    raise exception 'teaching_code_invalid';
  end if;
  v_parts := regexp_match(p_token, '^([0-9a-f]{32})([rt])([0-9]{1,12})([0-9a-f]{32})$');
  if v_parts is null then raise exception 'teaching_code_invalid'; end if;
  v_stream := case v_parts[2] when 'r' then 'room' else 'teams' end;
  v_window := v_parts[3]::bigint;
  select * into v_occ from public.teaching_occurrences where id = v_parts[1]::uuid;
  if not found then raise exception 'teaching_code_invalid'; end if;
  v_expected := public.teaching_code_mac(v_occ.checkin_secret, v_occ.id, v_stream, v_window);
  if not public.teaching_const_eq(v_parts[4], v_expected) then raise exception 'teaching_code_invalid'; end if;
  select * into v_service from public.on_call_services where id = v_occ.service_id for share;
  if not (v_service.verified_at is not null or v_service.is_demo) then raise exception 'teaching_team_unverified'; end if;
  if v_occ.status = 'cancelled' or now() < v_occ.starts_at - interval '15 minutes' or now() > v_occ.ends_at + interval '15 minutes' then
    raise exception 'teaching_window_closed';
  end if;
  if v_window not in (v_now_window, v_now_window - 1) then raise exception 'teaching_code_expired'; end if;
  if (select count(*) from public.teaching_checkin_claims
      where occurrence_id = v_occ.id and used_at is null and expires_at > now()) >= 2000 then
    raise exception 'teaching_limit';
  end if;
  insert into public.teaching_checkin_claims(occurrence_id, stream, claim_hash, expires_at)
  values (v_occ.id, v_stream, p_claim_hash, now() + interval '10 minutes');
  perform public.teaching_audit(v_occ.service_id, null, 'checkin.open', v_occ.id);
  return jsonb_build_object('occurrenceId', v_occ.id, 'title', v_occ.title, 'startsAt', v_occ.starts_at, 'stream', v_stream);
end $$;

-- Display-only screen on a shared PC: shows the current codes for one session and nothing else.
-- The link dies when check-in closes, when it is revoked, or when its creator leaves the team.
create function public.teaching_display_code(p_link_hash text) returns jsonb
language plpgsql volatile security invoker set search_path = public, pg_catalog, pg_temp as $$
declare
  v_link public.teaching_display_links;
  v_occ public.teaching_occurrences;
  v_service public.on_call_services;
  v_window bigint := floor(extract(epoch from now()) / 30)::bigint;
  v_mac text;
  v_typed text;
begin
  if p_link_hash is null or p_link_hash !~ '^[a-f0-9]{64}$' then raise exception 'teaching_link_expired'; end if;
  select * into v_link from public.teaching_display_links where link_hash = p_link_hash;
  if not found or v_link.revoked_at is not null or v_link.expires_at <= now() then raise exception 'teaching_link_expired'; end if;
  select * into v_occ from public.teaching_occurrences where id = v_link.occurrence_id;
  select * into v_service from public.on_call_services where id = v_occ.service_id for share;
  if not (v_service.verified_at is not null or v_service.is_demo)
    or v_link.created_by is null or not public.service_member_active(v_occ.service_id, v_link.created_by)
    or v_occ.status = 'cancelled' or now() > v_occ.ends_at + interval '15 minutes' then
    raise exception 'teaching_link_expired';
  end if;
  if now() < v_occ.starts_at - interval '15 minutes' then raise exception 'teaching_window_closed'; end if;
  v_mac := public.teaching_code_mac(v_occ.checkin_secret, v_occ.id, v_link.stream, v_window);
  v_typed := public.teaching_typed_code(v_occ.checkin_secret, v_occ.id, v_link.stream, v_window);
  return jsonb_build_object(
    'token', replace(v_occ.id::text, '-', '') || left(v_link.stream, 1) || v_window::text || v_mac,
    'typedCode', v_typed,
    'window', v_window,
    'title', v_occ.title,
    'venue', v_occ.venue,
    'closesAt', least(v_link.expires_at, v_occ.ends_at + interval '15 minutes')
  );
end $$;

