-- "Who can cover?": any active member reads the names and grades of their own team's current
-- members, nothing else (20261003013000_roster_team_members.sql).
create function public.roster_team_members(p_actor_id uuid, p_service_id uuid)
returns jsonb
language plpgsql stable security invoker set search_path = public, pg_catalog, pg_temp as $$
declare
  v_service public.on_call_services;
  v_result jsonb;
begin
  if p_actor_id is null then raise exception 'roster_auth_required'; end if;
  select * into v_service from public.on_call_services where id = p_service_id;
  if not found or not public.service_member_active(p_service_id, p_actor_id) then
    raise exception 'roster_access_denied';
  end if;
  if v_service.verified_at is null and not v_service.is_demo then raise exception 'roster_team_not_verified'; end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'userId', m.user_id, 'name', coalesce(m.display_name, r.roster_name), 'grade', r.grade
  ) order by coalesce(m.display_name, r.roster_name), m.user_id), '[]') into v_result
  from public.on_call_service_members m
  left join public.roster_member_roles r on r.service_id = m.service_id and r.user_id = m.user_id and r.revoked_at is null
  where m.service_id = p_service_id and m.revoked_at is null;
  return jsonb_build_object('members', v_result);
end $$;

revoke all on function public.roster_team_members(uuid, uuid) from public, anon, authenticated;
grant execute on function public.roster_team_members(uuid, uuid) to service_role;

-- Timed alert sender (20261006070000_alerts_timed_sender.sql): the server holds only when a Remind me
-- note is due, never its words; alert_brief_sent records the Perth day the morning brief last went out.
create table public.alert_reminder_times (
  owner_id uuid not null references auth.users (id) on delete cascade,
  ref text not null check (ref ~ '^[A-Za-z0-9_-]{1,64}$'),
  due_at timestamptz not null,
  endpoint text not null check (endpoint ~ '^https://' and char_length(endpoint) <= 1000),
  created_at timestamptz not null default now(),
  primary key (owner_id, ref)
);
create index alert_reminder_times_due_idx on public.alert_reminder_times (due_at);

-- The phone keeps at most 20 notes (REMIND_ME_MAX); the server keeps no more than that.
create function public.alert_reminder_times_cap() returns trigger
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
begin
  perform pg_advisory_xact_lock(hashtextextended(new.owner_id::text, 74818));
  -- An upsert that moves an existing note's time fires this trigger too; it adds nothing.
  if exists (select 1 from public.alert_reminder_times where owner_id = new.owner_id and ref = new.ref) then
    return new;
  end if;
  if (select count(*) from public.alert_reminder_times where owner_id = new.owner_id) >= 20 then
    raise exception 'alerts_limit';
  end if;
  return new;
end $$;
create trigger alert_reminder_times_cap before insert on public.alert_reminder_times
  for each row execute function public.alert_reminder_times_cap();

create table public.alert_brief_sent (
  owner_id uuid primary key references auth.users (id) on delete cascade,
  perth_date date not null,
  sent_at timestamptz not null default now()
);

alter table public.alert_reminder_times enable row level security;
alter table public.alert_brief_sent enable row level security;
revoke all on table public.alert_reminder_times from public, anon, authenticated;
revoke all on table public.alert_brief_sent from public, anon, authenticated;
grant select, insert, update, delete on table public.alert_reminder_times to service_role;
grant select, insert, update, delete on table public.alert_brief_sent to service_role;

-- Take every reminder due by p_now and delete it in the same statement, so two app servers
-- never send the same one and nothing is kept once it has gone out.
create function public.alert_claim_due_reminders(p_now timestamptz, p_limit integer)
returns table (owner_id uuid, ref text, due_at timestamptz, endpoint text)
language sql security invoker set search_path = public, pg_catalog, pg_temp as $$
  delete from public.alert_reminder_times t
  using (
    select d.owner_id, d.ref from public.alert_reminder_times d
    where d.due_at <= p_now
    order by d.due_at
    limit greatest(1, least(coalesce(p_limit, 200), 500))
    for update skip locked
  ) due
  where t.owner_id = due.owner_id and t.ref = due.ref
  returning t.owner_id, t.ref, t.due_at, t.endpoint;
$$;

-- True exactly once per owner per Perth day: the caller that gets true sends the brief.
create function public.alert_claim_morning_brief(p_owner_id uuid, p_perth_date date)
returns boolean
language plpgsql security invoker set search_path = public, pg_catalog, pg_temp as $$
declare v_claimed uuid;
begin
  insert into public.alert_brief_sent as s (owner_id, perth_date, sent_at)
  values (p_owner_id, p_perth_date, now())
  on conflict (owner_id) do update set perth_date = excluded.perth_date, sent_at = excluded.sent_at
    where s.perth_date < excluded.perth_date
  returning s.owner_id into v_claimed;
  return v_claimed is not null;
end $$;

revoke all on function public.alert_claim_due_reminders(timestamptz, integer) from public, anon, authenticated;
grant execute on function public.alert_claim_due_reminders(timestamptz, integer) to service_role;
revoke all on function public.alert_claim_morning_brief(uuid, date) from public, anon, authenticated;
grant execute on function public.alert_claim_morning_brief(uuid, date) to service_role;
revoke all on function public.alert_reminder_times_cap() from public, anon, authenticated;

-- Admin paperwork kept with the account (20261008003000_work_admin_paperwork.sql): one row per
-- doctor holding their requests, documents list, sharing choices, payslip checks and tax checklist.
-- Written only by /api/work/sync with the service role; a null record means the doctor cleared it.
create table public.work_admin_paperwork (
  owner_id uuid primary key references auth.users (id) on delete cascade,
  record jsonb,
  updated_at timestamptz not null default now(),
  constraint work_admin_paperwork_record_object check (record is null or jsonb_typeof(record) = 'object'),
  constraint work_admin_paperwork_record_size check (record is null or octet_length(record::text) <= 262144)
);

alter table public.work_admin_paperwork enable row level security;
revoke all on table public.work_admin_paperwork from public, anon, authenticated;
grant select, insert, update, delete on table public.work_admin_paperwork to service_role;

-- Work records backed up to the account (20261008003100_work_backups.sql): Teaching's term tracker
-- and exam prep, and CPD's job applications season. One row per doctor and record, written only by
-- /api/work/sync with the service role; a null record means the doctor cleared it.
create table public.work_backups (
  owner_id uuid not null references auth.users (id) on delete cascade,
  section text not null,
  record jsonb,
  updated_at timestamptz not null default now(),
  primary key (owner_id, section),
  constraint work_backups_section_check check (section in ('term_tracker', 'exam_prep', 'job_applications')),
  constraint work_backups_record_object check (record is null or jsonb_typeof(record) = 'object'),
  constraint work_backups_record_size check (record is null or octet_length(record::text) <= 131072)
);

alter table public.work_backups enable row level security;
